def _runtime_exact_semantic_definition_candidate_artifact_bindings(
    rows: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    path_keys = (
        "candidate_artifact_path",
        "definition_only_candidate_artifact_path",
        "signature_probe_artifact_path",
        "source_theorem_signature_probe_artifact_path",
        "proof_body_signature_probe_artifact_path",
    )
    bindings: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for row in rows:
        containers = [row]
        for key in (
            "candidate_definition_request",
            "source_theorem_exact_semantic_definition_typechecked_candidate",
        ):
            value = row.get(key, {})
            if isinstance(value, Mapping):
                containers.append(value)
        for container in containers:
            for key in path_keys:
                path_text = str(container.get(key, "") or "").strip()
                if not path_text or (key, path_text) in seen:
                    continue
                seen.add((key, path_text))
                path = Path(path_text)
                try:
                    source = path.read_bytes()
                    artifact_present = True
                except OSError:
                    source = b""
                    artifact_present = False
                bindings.append(
                    {
                        "source_field": key,
                        "artifact_path": path_text,
                        "artifact_present": artifact_present,
                        "artifact_content_hash": (
                            stable_hash(
                                source.decode("utf-8", errors="replace")
                            )
                            if artifact_present
                            else ""
                        ),
                        "artifact_utf8_bytes": len(source),
                        "proof_evidence_status": (
                            "EXACT_SEMANTIC_CANDIDATE_BINDING_NOT_PROOF_EVIDENCE"
                        ),
                    }
                )
    return bindings


def _runtime_exact_semantic_definition_review_execution_policy(
    runtime_config: ResearchAgentRuntimeConfig,
) -> dict[str, Any]:
    authoring_config = _exact_semantic_definition_authoring_worker_config(
        runtime_config
    )
    materializer_config = AuthoringCandidateMaterializerConfig()
    return {
        "environment_preflight_enabled": bool(
            runtime_config.source_theorem_exact_semantic_definition_lean_environment_repair_executor
        ),
        "authoring_enabled": bool(
            runtime_config.source_theorem_exact_semantic_definition_authoring_worker
        ),
        "authoring_config_fingerprint": stable_hash(asdict(authoring_config)),
        "materializer_config_fingerprint": stable_hash(
            asdict(materializer_config)
        ),
        "local_lean": bool(
            runtime_config.source_theorem_exact_semantic_definition_lean_repair_executor_local_lean
        ),
        "lean_project": str(
            _exact_semantic_definition_lean_repair_executor_project(
                runtime_config
            )
            or ""
        ),
        "lean_timeout": int(
            runtime_config.source_theorem_exact_semantic_definition_lean_repair_executor_lean_timeout
        ),
        "proof_body_execute": bool(
            runtime_config.source_theorem_formal_environment_proofengineer_execute_proof_body
        ),
        "proof_body_local_lean": bool(
            runtime_config.source_theorem_formal_environment_proofengineer_proof_body_local_lean
        ),
        "proof_body_lean_project": str(
            runtime_config.source_theorem_formal_environment_proofengineer_lean_project
            or ""
        ),
        "proof_body_lean_timeout": int(
            runtime_config.source_theorem_formal_environment_proofengineer_lean_timeout
        ),
        "proof_body_overwrite": bool(
            runtime_config.source_theorem_formal_environment_proofengineer_proof_body_overwrite_artifacts
        ),
        "runtime_generated_lean": False,
        "python_lean_grammar_generation_or_repair": False,
    }


def _runtime_exact_semantic_definition_work_order(
    *,
    source_task: AgentTask,
    question: OpenResearchQuestion,
    architect_context: Mapping[str, Any],
    formalization_manifest: Mapping[str, Any],
    return_task: AgentTask,
    runtime_config: ResearchAgentRuntimeConfig,
) -> dict[str, Any]:
    rows = _runtime_exact_semantic_definition_rows_from_manifest(
        formalization_manifest
    )
    execution_policy = {
        "source_roots": [
            str(value)
            for value in runtime_config.source_theorem_exact_semantic_definition_source_roots
            if str(value).strip()
        ],
        "max_hits_per_work_order": int(
            runtime_config.source_theorem_exact_semantic_definition_source_lookup_max_hits
        ),
        "proofengineer_bridge_enabled": bool(
            runtime_config.source_theorem_exact_semantic_definition_proofengineer_bridge
        ),
        "lean_repair_executor_enabled": bool(
            runtime_config.source_theorem_exact_semantic_definition_lean_repair_executor
        ),
        "local_lean": bool(
            runtime_config.source_theorem_exact_semantic_definition_lean_repair_executor_local_lean
        ),
        "lean_project": str(
            _exact_semantic_definition_lean_repair_executor_project(runtime_config)
            or ""
        ),
        "lean_timeout": int(
            runtime_config.source_theorem_exact_semantic_definition_lean_repair_executor_lean_timeout
        ),
        "authoring_worker_enabled": bool(
            runtime_config.source_theorem_exact_semantic_definition_authoring_worker
        ),
        "generation_policy": (
            "dedicated LLM authoring worker with source lookup and compiler feedback"
        ),
        "python_lean_grammar_generation_or_repair": False,
    }
    source_proof_body_rows = (
        _runtime_exact_source_theorem_proof_body_rows_from_manifest(
            formalization_manifest
        )
    )
    source_proof_body_candidate_bindings = (
        _runtime_exact_source_candidate_bindings(source_proof_body_rows)
    )
    review_execution_policy = (
        _runtime_exact_semantic_definition_review_execution_policy(
            runtime_config
        )
    )
    source_manifest_id = str(
        formalization_manifest.get("manifest_id", "") or ""
    )
    work_order_id = "runtime_exact_semantic_definition_work_order:" + stable_hash(
        [
            source_task.task_id,
            question.id,
            source_manifest_id,
            [stable_hash(row) for row in rows],
            [stable_hash(row) for row in source_proof_body_rows],
            source_proof_body_candidate_bindings,
            execution_policy,
            review_execution_policy,
        ]
    )[:20]
    control_seed = _runtime_architect_control_seed_from_context(
        architect_context,
        subsystem=EXACT_SEMANTIC_DEFINITION_SUBSYSTEM,
    )
    work_order = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": EXACT_SEMANTIC_DEFINITION_RUNTIME_WORK_ORDER_KIND,
        "work_order_id": work_order_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "question_id": question.id,
        "source_task_id": source_task.task_id,
        "source_subsystem": source_task.owner_subsystem,
        "target_subsystem": EXACT_SEMANTIC_DEFINITION_SUBSYSTEM,
        "source_formalization_manifest_id": source_manifest_id,
        "source_formalization_manifest_hash": stable_hash(
            formalization_manifest
        ),
        "work_order_rows": rows,
        "work_order_row_hashes": [stable_hash(row) for row in rows],
        "candidate_artifact_bindings": (
            _runtime_exact_semantic_definition_candidate_artifact_bindings(rows)
        ),
        "source_proof_body_rows": source_proof_body_rows,
        "source_proof_body_row_hashes": [
            stable_hash(row) for row in source_proof_body_rows
        ],
        "source_proof_body_candidate_bindings": (
            source_proof_body_candidate_bindings
        ),
        "execution_policy": execution_policy,
        "execution_policy_fingerprint": stable_hash(execution_policy),
        "review_execution_policy": review_execution_policy,
        "review_execution_policy_fingerprint": stable_hash(
            review_execution_policy
        ),
        "source_task": asdict(source_task),
        "return_task": asdict(return_task),
        "proof_evidence_status": (
            "EXACT_SEMANTIC_DEFINITION_RUNTIME_WORK_ORDER_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }
    return _runtime_artifact_with_architect_control(
        work_order_id,
        work_order,
        control_seed,
        subsystem_override=EXACT_SEMANTIC_DEFINITION_SUBSYSTEM,
    )


def _runtime_exact_semantic_definition_dispatch_task(
    *,
    question: OpenResearchQuestion,
    architect_context: Mapping[str, Any],
    work_order: Mapping[str, Any],
) -> AgentTask:
    work_order_id = str(work_order.get("work_order_id", "") or "")
    return AgentTask(
        task_id=(
            f"exact-semantic-definition:{question.id}:"
            f"{stable_hash(work_order_id)[:8]}"
        ),
        owner_subsystem=EXACT_SEMANTIC_DEFINITION_SUBSYSTEM,
        objective=(
            "Run source lookup, exact semantic-definition LLM authoring, and "
            "Lean feedback for the immutable semantic work order."
        ),
        inputs={
            "question": _question_to_payload(question),
            "architect_context": dict(architect_context),
            "exact_semantic_definition_work_order_id": work_order_id,
            "exact_semantic_definition_work_order_hash": stable_hash(work_order),
        },
        allowed_tools=(
            "blackboard",
            "formal_source_retrieval",
            "model_backend",
            "local_lean",
            "lean_lsp_mcp",
        ),
        expected_artifacts=(
            "exact_semantic_definition_runtime_execution",
            "runtime_learning_rows",
        ),
        acceptance_gate=(
            "all stage artifacts preserve immutable work-order and candidate "
            "lineage, and generated definitions return through local Lean feedback"
        ),
        stop_condition=(
            "exact semantic feedback returned to ProofEngineer or a typed "
            "lineage/verifier blocker recorded"
        ),
    )


class FormalizationEvaluatorRuntimeSubsystem:
    name = "FormalizationEvaluator"

    def __init__(
        self,
        *,
        proposal_agent: LLMFormalizerProofEngineerAgent | None = None,
        proof_verifier: ProofVerifier | None = None,
        proof_state_provider: ProofStateFeedbackProvider | None = None,
        formal_source_retriever: Any | None = None,
        proof_search_provider: LeanProofSearchProvider | None = None,
        inline_proof_search_enabled: bool = True,
        external_proof_candidate_rerunner: Callable[..., Mapping[str, Any]] = (
            execute_external_exact_source_theorem_proof_candidates
        ),
        proof_obligation_ids: tuple[str, ...] = (),
        max_proof_obligations: int = 0,
        lean_candidate_root: Path = Path("runs") / "formalizer_lean_candidates",
        lean_candidate_local_lean: bool = False,
        lean_candidate_lean_project: Path | None = None,
        lean_candidate_lean_timeout: int = 30,
        architect_coordinator_available: bool = False,
        pseudo_formal_block_verifier_available: bool = False,
        formal_target_semantic_reviewer_available: bool = False,
        formal_target_semantic_review_max_revisions: int = 1,
        runtime_config: ResearchAgentRuntimeConfig = ResearchAgentRuntimeConfig(),
    ) -> None:
        self.proposal_agent = proposal_agent
        self.proof_state_provider = proof_state_provider
        self.lean_candidate_root = lean_candidate_root
        self.lean_candidate_local_lean = lean_candidate_local_lean
        self.lean_candidate_lean_project = lean_candidate_lean_project
        self.lean_candidate_lean_timeout = lean_candidate_lean_timeout
        self.architect_coordinator_available = architect_coordinator_available
        self.pseudo_formal_block_verifier_available = bool(
            pseudo_formal_block_verifier_available
        )
        self.formal_target_semantic_reviewer_available = bool(
            formal_target_semantic_reviewer_available
        )
        self.formal_target_semantic_review_max_revisions = max(
            0,
            int(formal_target_semantic_review_max_revisions or 0),
        )
        self.runtime_config = runtime_config
        self.formal_source_retriever = formal_source_retriever
        self.proof_search_provider = proof_search_provider
        self.inline_proof_search_enabled = inline_proof_search_enabled
        self.external_proof_candidate_rerunner = external_proof_candidate_rerunner
        self.prover = FormalSubclaimProver(
            verifier=proof_verifier,
            formal_source_retriever=formal_source_retriever,
            proof_obligation_ids=proof_obligation_ids,
            max_proof_obligations=max_proof_obligations,
        )

    def run(self, task: AgentTask, blackboard: BlackboardState) -> AgentStepResult:
        subsystem_name = str(
            getattr(self, "name", "FormalizationEvaluator")
            or "FormalizationEvaluator"
        )
        question = _question_from_payload(task.inputs["question"])
        _, planner_action_binding_errors = validate_action_work_order_binding(
            task=task,
            blackboard=blackboard,
            question_id=question.id,
        )
        if planner_action_binding_errors:
            failure_id = (
                "formalization_gap_planner_action_binding_failure:"
                + stable_hash(
                    [task.task_id, planner_action_binding_errors]
                )[:20]
            )
            failure_artifact = {
                "schema_version": RUNTIME_SCHEMA_VERSION,
                "artifact_kind": (
                    "RuntimeFormalizationGapPlannerActionBindingFailure"
                ),
                "failure_id": failure_id,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "task_id": task.task_id,
                "question": _question_to_payload(question),
                "binding_errors": planner_action_binding_errors,
                "proof_evidence_status": (
                    "FORMALIZATION_GAP_PLANNER_ACTION_BINDING_FAILURE_"
                    "NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
            return AgentStepResult(
                status="BLOCKED",
                rationale=(
                    "ProofEngineer rejected a missing, changed, or cross-task "
                    "FormalizationGapPlanner action work order before invoking "
                    "the model, retriever, or Lean environment."
                ),
                produced_artifacts={failure_id: failure_artifact},
                observations=(
                    EnvironmentObservation(
                        observation_type=(
                            "formalization_gap_planner_action_binding_failure"
                        ),
                        summary="; ".join(planner_action_binding_errors)[:500],
                        payload={
                            "failure_id": failure_id,
                            "binding_errors": planner_action_binding_errors,
                            "proof_evidence_status": failure_artifact[
                                "proof_evidence_status"
                            ],
                        },
                    ),
                ),
                failure_classification=(
                    "formalization_gap_planner_action_work_order_binding_failed"
                ),
            )
        pseudo_formal_feedback_binding_errors = (
            pseudo_formal_block_verifier_feedback_task_errors(
                task,
                blackboard,
                question_id=question.id,
            )
        )
        if pseudo_formal_feedback_binding_errors:
            return pseudo_formal_block_verifier_feedback_binding_failure_result(
                task=task,
                question=_question_to_payload(question),
                errors=pseudo_formal_feedback_binding_errors,
            )
        context = dict(task.inputs.get("architect_context", {}) or {})
        context["runtime_task"] = _runtime_task_prompt_summary(task)
        environment_feedback: Mapping[str, Any] = (
            task.inputs.get("environment_feedback", {})
            if isinstance(task.inputs.get("environment_feedback", {}), Mapping)
            else {}
        )
        (
            source_theorem_promotion_generation_request,
            source_theorem_promotion_generation_lineage_errors,
        ) = _runtime_bound_source_theorem_promotion_generation_request(
            task=task,
            blackboard=blackboard,
        )
        if source_theorem_promotion_generation_lineage_errors:
            return _runtime_source_theorem_promotion_generation_lineage_failure_result(
                task=task,
                errors=source_theorem_promotion_generation_lineage_errors,
            )
        if source_theorem_promotion_generation_request:
            environment_feedback = dict(environment_feedback)
            environment_feedback.update(
                {
                    "source_theorem_promotion_execution_id": str(
                        task.inputs.get(
                            "source_theorem_promotion_execution_id",
                            "",
                        )
                        or ""
                    ),
                    "source_theorem_promotion_generation_request_id": str(
                        source_theorem_promotion_generation_request.get(
                            "request_id",
                            "",
                        )
                        or ""
                    ),
                    "source_theorem_promotion_generation_request_hash": stable_hash(
                        source_theorem_promotion_generation_request
                    ),
                    "source_theorem_promotion_generation_request": dict(
                        source_theorem_promotion_generation_request
                    ),
                }
            )
        environment_feedback = (
            _runtime_environment_feedback_with_theory_trace_downstream_alignment(
                environment_feedback,
                context,
                question.id,
                target_consumer_subsystem="FormalizerProofEngineer",
            )
        )
        if environment_feedback:
            context["environment_feedback"] = environment_feedback
        context = _runtime_context_with_environment_feedback_contract(
            context,
            environment_feedback,
            subsystem=subsystem_name,
        )
        context = _runtime_context_with_formalizer_capability_memory_contract(
            context,
            question.id,
            subsystem=subsystem_name,
        )
        formalization_control = _architect_control_payload(context, subsystem_name)
        formalization_control_seed = _runtime_architect_control_seed_from_control(
            formalization_control,
            control_source="formalization_architect_control",
        )
        packet_id = str(task.inputs.get("theory_packet_id", ""))
        packet = blackboard.artifacts.get(packet_id, {})
        trace_repair_result = _runtime_theory_trace_repair_result_if_needed(
            source_subsystem=subsystem_name,
            task=task,
            question=question,
            theory_packet_id=packet_id,
            theory_packet=packet if isinstance(packet, Mapping) else {},
        )
        if trace_repair_result is not None:
            return trace_repair_result
        runtime_theory_trace_contract = _runtime_theory_trace_consumption_contract(
            consumer_subsystem="FormalizerProofEngineer",
            source_theory_packet_id=packet_id,
            theory_packet=packet if isinstance(packet, Mapping) else {},
        )
        simulation_manifest_id = str(task.inputs.get("simulation_manifest_id", ""))
        algorithm_sandbox_manifest_id = str(task.inputs.get("algorithm_sandbox_manifest_id", ""))
        simulation_manifest = blackboard.artifacts.get(simulation_manifest_id, {})
        algorithm_manifest = blackboard.artifacts.get(algorithm_sandbox_manifest_id, {})
        missing_simulation_result = (
            _runtime_missing_simulation_handoff_result_if_needed(
                source_subsystem=subsystem_name,
                task=task,
                question=question,
                context=context,
                simulation_manifest_id=simulation_manifest_id,
                simulation_manifest=simulation_manifest,
                theory_packet_id=packet_id,
                n_runs=task.inputs.get("n_runs", 100),
                seed=task.inputs.get("seed", 20260528),
            )
        )
        if missing_simulation_result is not None:
            return missing_simulation_result
        missing_algorithm_result = (
            _runtime_missing_algorithm_handoff_result_if_needed(
                source_subsystem=subsystem_name,
                task=task,
                question=question,
                context=context,
                algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
                algorithm_manifest=algorithm_manifest,
                theory_packet_id=packet_id,
                simulation_manifest_id=simulation_manifest_id,
                implementation_gaps=task.inputs.get("implementation_gaps", []),
                n_runs=task.inputs.get("n_runs", 100),
                seed=task.inputs.get("seed", 20260528),
            )
        )
        if missing_algorithm_result is not None:
            return missing_algorithm_result
        llm_research_authority = runtime_llm_research_authority_required(
            context,
            packet if isinstance(packet, Mapping) else {},
        )
        if llm_research_authority:
            research_bundle = derive_runtime_research_problem(
                question=question,
                architect_context=context,
                theory_packet=packet if isinstance(packet, Mapping) else {},
            )
            problem = research_bundle.problem
            theorem_goals = list(research_bundle.theorem_goals)
            problem_authority = research_bundle.provenance()
        else:
            problem = ProblemFormalizer().formalize(question)
            _procedures, theorem_goals = TheoryPlanner().plan(problem)
            problem_authority = legacy_runtime_research_problem_provenance()
        proof_bank_obligation_catalog = self.prover.proof_obligation_catalog(problem, theorem_goals)
        proposal_packet: dict[str, Any] | None = None
        proposal_evidence: EvidenceLedgerEntry | None = None
        llm_requested_proof_obligation_ids: tuple[str, ...] = ()
        llm_prioritized_proof_obligation_ids: tuple[str, ...] = ()
        llm_suppressed_kernel_verified_proof_obligation_ids: tuple[str, ...] = ()
        llm_off_catalog_proof_obligation_ids: tuple[str, ...] = ()
        llm_rejected_proof_obligation_ids: tuple[str, ...] = ()
        memory_kernel_verified_proof_obligation_ids = (
            _runtime_learning_memory_kernel_verified_proof_obligation_ids(
                context,
                catalog_ids=tuple(
                    str(row.get("obligation_id", "") or "")
                    for row in proof_bank_obligation_catalog
                    if isinstance(row, Mapping)
                ),
            )
        )
        (
            memory_prioritized_proof_obligation_ids,
            memory_off_catalog_proof_obligation_ids,
            memory_rejected_proof_obligation_ids,
        ) = _runtime_learning_memory_proof_obligation_ids(
            context,
            catalog_ids=tuple(
                str(row.get("obligation_id", "") or "")
                for row in proof_bank_obligation_catalog
                if isinstance(row, Mapping)
            ),
        )
        proof_bank_runtime_memory_summary = _formalizer_proof_bank_runtime_memory_summary(
            context=context,
            proof_bank_obligation_catalog=proof_bank_obligation_catalog,
            theorem_goals=theorem_goals,
            memory_kernel_verified_proof_obligation_ids=memory_kernel_verified_proof_obligation_ids,
            memory_prioritized_proof_obligation_ids=memory_prioritized_proof_obligation_ids,
        )
        produced_artifacts: dict[str, Any] = {}
        source_theorem_promotion_generation_response_binding: dict[str, Any] = {}
        source_theorem_promotion_generation_response_binding_evidence: (
            EvidenceLedgerEntry | None
        ) = None
        observations: list[EnvironmentObservation] = []
        external_proof_search_artifacts: dict[str, Any] = {}
        external_proof_search_observations: list[EnvironmentObservation] = []
        external_proof_search_evidence_entries: list[EvidenceLedgerEntry] = []
        external_proof_search_tool_calls: list[ToolCallRecord] = []
        (
            prior_external_proof_search_result,
            prior_external_exact_candidate_rerun_result,
            prior_external_prover_execution_errors,
        ) = _runtime_prior_exact_source_theorem_prover_execution(
            environment_feedback=environment_feedback,
            blackboard=blackboard,
            question_id=question.id,
        )
        external_proof_search_result = prior_external_proof_search_result
        external_exact_candidate_rerun_result = (
            prior_external_exact_candidate_rerun_result
        )
        external_exact_source_theorem_verified = bool(
            external_exact_candidate_rerun_result
            and external_exact_candidate_rerun_result.get(
                "runtime_verification_contract_satisfied",
                False,
            )
            and _runtime_manifest_int(
                external_exact_candidate_rerun_result,
                "n_source_theorem_kernel_verified",
            )
            > 0
        )
        if prior_external_prover_execution_errors:
            observations.append(
                EnvironmentObservation(
                    observation_type=(
                        "exact_source_theorem_prover_execution_lineage_rejected"
                    ),
                    summary=(
                        "dedicated exact-source prover results failed immutable "
                        "blackboard lineage validation and cannot support a proof claim"
                    ),
                    payload={
                        "errors": list(prior_external_prover_execution_errors),
                        "proof_evidence_status": (
                            "EXACT_SOURCE_THEOREM_PROVER_LINEAGE_REJECTED_NOT_PROOF_EVIDENCE"
                        ),
                    },
                )
            )
        if (
            self.proof_search_provider is not None
            and self.inline_proof_search_enabled
        ):
            external_proof_search_request = _runtime_external_proof_search_request(
                task=task,
                question=question,
                environment_feedback=environment_feedback,
            )
            if external_proof_search_request:
                try:
                    raw_external_proof_search_result = self.proof_search_provider.run(
                        external_proof_search_request
                    )
                    if not isinstance(raw_external_proof_search_result, Mapping):
                        raise TypeError(
                            "proof search provider must return a mapping result"
                        )
                    external_proof_search_result = dict(
                        raw_external_proof_search_result
                    )
                except Exception as exc:
                    external_proof_search_result = (
                        _runtime_external_proof_search_error_result(
                            request=external_proof_search_request,
                            provider=self.proof_search_provider,
                            exc=exc,
                        )
                    )
                external_result_id = str(
                    external_proof_search_result.get("result_id", "")
                    or "external_proof_search_result:"
                    + stable_hash(external_proof_search_result)[:20]
                )
                external_proof_search_result["result_id"] = external_result_id
                external_proof_search_result.setdefault(
                    "proof_evidence_status",
                    "EXTERNAL_PROOF_SEARCH_RESULT_NOT_PROOF_EVIDENCE",
                )
                external_proof_search_result.setdefault(
                    "proof_evidence_boundary",
                    LEAN_PROVIDER_BOUNDARY,
                )
                if external_proof_search_result.get(
                    "source_theorem_candidate_proof_bodies"
                ):
                    try:
                        raw_external_exact_candidate_rerun_result = (
                            self.external_proof_candidate_rerunner(
                                request=external_proof_search_request,
                                provider_result=external_proof_search_result,
                                out_dir=(
                                    self.lean_candidate_root.parent
                                    / "external_exact_proof_candidate_reruns"
                                ),
                                local_lean=self.lean_candidate_local_lean,
                                lean_project=self.lean_candidate_lean_project,
                                lean_timeout=self.lean_candidate_lean_timeout,
                            )
                        )
                        if not isinstance(
                            raw_external_exact_candidate_rerun_result,
                            Mapping,
                        ):
                            raise TypeError(
                                "external proof candidate rerunner must return a mapping"
                            )
                        external_exact_candidate_rerun_result = dict(
                            raw_external_exact_candidate_rerun_result
                        )
                    except Exception as exc:
                        external_exact_candidate_rerun_result = (
                            _runtime_external_exact_candidate_rerun_error_result(
                                request=external_proof_search_request,
                                provider_result=external_proof_search_result,
                                exc=exc,
                            )
                        )
                    external_exact_candidate_rerun_result = (
                        _runtime_validated_external_exact_candidate_rerun_result(
                            request=external_proof_search_request,
                            provider_result=external_proof_search_result,
                            result=external_exact_candidate_rerun_result,
                            runtime_lean_project=(
                                self.lean_candidate_lean_project
                            ),
                            runtime_lean_timeout=(
                                self.lean_candidate_lean_timeout
                            ),
                        )
                    )
                    external_exact_rerun_id = str(
                        external_exact_candidate_rerun_result.get(
                            "manifest_id",
                            "",
                        )
                        or "external_exact_proof_candidate_rerun:"
                        + stable_hash(external_exact_candidate_rerun_result)[:20]
                    )
                    external_exact_candidate_rerun_result["manifest_id"] = (
                        external_exact_rerun_id
                    )
                    external_exact_candidate_rerun_result = (
                        _runtime_artifact_with_architect_control(
                            external_exact_rerun_id,
                            external_exact_candidate_rerun_result,
                            formalization_control_seed,
                            subsystem_override=subsystem_name,
                        )
                    )
                    external_proof_search_result["exact_candidate_rerun"] = (
                        _runtime_external_exact_candidate_rerun_summary(
                            external_exact_candidate_rerun_result
                        )
                    )
                    produced_artifacts[external_exact_rerun_id] = (
                        external_exact_candidate_rerun_result
                    )
                    external_proof_search_artifacts[external_exact_rerun_id] = (
                        external_exact_candidate_rerun_result
                    )
                    external_exact_source_theorem_verified = bool(
                        external_exact_candidate_rerun_result.get(
                            "runtime_verification_contract_satisfied",
                            False,
                        )
                    )
                    external_proof_search_observations.append(
                        EnvironmentObservation(
                            observation_type=(
                                "external_exact_proof_candidate_rerun"
                            ),
                            summary=(
                                "checked="
                                f"{external_exact_candidate_rerun_result.get('n_local_lean_checked', 0)} "
                                "compiled="
                                f"{external_exact_candidate_rerun_result.get('n_local_lean_compiled', 0)} "
                                "source_verified="
                                f"{int(external_exact_source_theorem_verified)}"
                            ),
                            payload=(
                                _runtime_external_exact_candidate_rerun_summary(
                                    external_exact_candidate_rerun_result
                                )
                            ),
                        )
                    )
                    external_rerun_boundary = str(
                        external_exact_candidate_rerun_result.get(
                            "proof_evidence_boundary",
                            KERNEL_PROOF_BOUNDARY,
                        )
                        or KERNEL_PROOF_BOUNDARY
                    )
                    external_proof_search_evidence_entries.append(
                        EvidenceLedgerEntry(
                            evidence_id="evidence:"
                            + stable_hash(
                                [task.task_id, external_exact_rerun_id]
                            )[:20],
                            task_id=task.task_id,
                            artifact_id=external_exact_rerun_id,
                            evidence_type=(
                                "external_exact_proof_candidate_kernel_rerun"
                            ),
                            status=(
                                "EXACT_SOURCE_THEOREM_KERNEL_VERIFIED"
                                if external_exact_source_theorem_verified
                                else "EXTERNAL_EXACT_CANDIDATE_RERUN_RECORDED_NOT_SOURCE_PROOF"
                            ),
                            boundary=external_rerun_boundary,
                            payload={
                                "n_local_lean_checked": _runtime_manifest_int(
                                    external_exact_candidate_rerun_result,
                                    "n_local_lean_checked",
                                ),
                                "n_local_lean_compiled": _runtime_manifest_int(
                                    external_exact_candidate_rerun_result,
                                    "n_local_lean_compiled",
                                ),
                                "n_source_theorem_kernel_verified": _runtime_manifest_int(
                                    external_exact_candidate_rerun_result,
                                    "n_source_theorem_kernel_verified",
                                ),
                                "runtime_owned_local_lean_checked": _runtime_manifest_int(
                                    external_exact_candidate_rerun_result,
                                    "runtime_owned_local_lean_checked",
                                ),
                                "runtime_owned_local_lean_compiled": _runtime_manifest_int(
                                    external_exact_candidate_rerun_result,
                                    "runtime_owned_local_lean_compiled",
                                ),
                                "target_ids": list(
                                    external_exact_candidate_rerun_result.get(
                                        "target_ids",
                                        [],
                                    )
                                    or []
                                ),
                            },
                        )
                    )
                    external_proof_search_tool_calls.append(
                        ToolCallRecord(
                            tool_name=(
                                "ExactSourceTheoremProofBodyExecutor."
                                "rerun_external_candidate"
                            ),
                            inputs={
                                "request_fingerprint": str(
                                    external_proof_search_request.get(
                                        "request_fingerprint",
                                        "",
                                    )
                                    or ""
                                ),
                                "target_lean_declaration": str(
                                    external_proof_search_request.get(
                                        "target_lean_declaration",
                                        "",
                                    )
                                    or ""
                                ),
                                "local_lean_requested": (
                                    self.lean_candidate_local_lean
                                ),
                            },
                            output_paths=tuple(
                                str(
                                    external_exact_candidate_rerun_result.get(
                                        key,
                                        "",
                                    )
                                    or ""
                                )
                                for key in ("manifest_path", "rows_path")
                                if str(
                                    external_exact_candidate_rerun_result.get(
                                        key,
                                        "",
                                    )
                                    or ""
                                )
                            ),
                            exit_status=(
                                "0"
                                if external_exact_source_theorem_verified
                                else "source_theorem_not_verified"
                            ),
                            stdout_summary=(
                                "checked="
                                f"{external_exact_candidate_rerun_result.get('n_local_lean_checked', 0)} "
                                "compiled="
                                f"{external_exact_candidate_rerun_result.get('n_local_lean_compiled', 0)} "
                                "source_verified="
                                f"{int(external_exact_source_theorem_verified)}"
                            ),
                            safety_boundary=external_rerun_boundary,
                        )
                    )
                    runtime_owned_checked = _runtime_manifest_int(
                        external_exact_candidate_rerun_result,
                        "runtime_owned_local_lean_checked",
                    )
                    if runtime_owned_checked > 0:
                        runtime_owned_compiled = _runtime_manifest_int(
                            external_exact_candidate_rerun_result,
                            "runtime_owned_local_lean_compiled",
                        )
                        external_proof_search_tool_calls.append(
                            ToolCallRecord(
                                tool_name=(
                                    "AgentRuntime."
                                    "verify_external_exact_candidate_local_lean"
                                ),
                                inputs={
                                    "request_fingerprint": str(
                                        external_proof_search_request.get(
                                            "request_fingerprint",
                                            "",
                                        )
                                        or ""
                                    ),
                                    "target_lean_declaration": str(
                                        external_proof_search_request.get(
                                            "target_lean_declaration",
                                            "",
                                        )
                                        or ""
                                    ),
                                    "lean_project": str(
                                        self.lean_candidate_lean_project or ""
                                    ),
                                },
                                output_paths=tuple(
                                    str(row.get("candidate_artifact_path", "") or "")
                                    for row in external_exact_candidate_rerun_result.get(
                                        "rows",
                                        [],
                                    )
                                    or []
                                    if isinstance(row, Mapping)
                                    and str(
                                        row.get("candidate_artifact_path", "")
                                        or ""
                                    )
                                ),
                                exit_status=(
                                    "0"
                                    if external_exact_source_theorem_verified
                                    else "runtime_owned_source_theorem_not_verified"
                                ),
                                stdout_summary=(
                                    f"checked={runtime_owned_checked} "
                                    f"compiled={runtime_owned_compiled} "
                                    "source_verified="
                                    f"{int(external_exact_source_theorem_verified)}"
                                ),
                                safety_boundary=external_rerun_boundary,
                            )
                        )
                external_proof_search_result = (
                    _runtime_artifact_with_architect_control(
                        external_result_id,
                        external_proof_search_result,
                        formalization_control_seed,
                        subsystem_override=subsystem_name,
                    )
                )
                produced_artifacts[external_result_id] = (
                    external_proof_search_result
                )
                external_proof_search_artifacts[external_result_id] = (
                    external_proof_search_result
                )
                environment_feedback = (
                    _runtime_environment_feedback_with_external_proof_search_result(
                        environment_feedback,
                        external_proof_search_result,
                    )
                )
                context["environment_feedback"] = environment_feedback
                external_status = str(
                    external_proof_search_result.get("status", "") or ""
                )
                external_proof_search_observations.append(
                    EnvironmentObservation(
                        observation_type="external_proof_search",
                        summary=(
                            "provider="
                            f"{getattr(self.proof_search_provider, 'name', type(self.proof_search_provider).__name__)} "
                            f"status={external_status}"
                        ),
                        payload={
                            "result_id": external_result_id,
                            "status": external_status,
                            "request_fingerprint": str(
                                external_proof_search_result.get(
                                    "request_fingerprint",
                                    "",
                                )
                                or ""
                            ),
                            "n_source_theorem_candidate_proof_bodies": len(
                                external_proof_search_result.get(
                                    "source_theorem_candidate_proof_bodies",
                                    [],
                                )
                                or []
                            ),
                            "n_verified_support_assets": len(
                                external_proof_search_result.get(
                                    "verified_support_assets",
                                    [],
                                )
                                or []
                            ),
                            "proof_evidence_status": str(
                                external_proof_search_result.get(
                                    "proof_evidence_status",
                                    "",
                                )
                                or ""
                            ),
                        },
                    )
                )
                observations.extend(external_proof_search_observations)
                external_proof_search_evidence_entries.append(
                    EvidenceLedgerEntry(
                        evidence_id="evidence:"
                        + stable_hash([task.task_id, external_result_id])[:20],
                        task_id=task.task_id,
                        artifact_id=external_result_id,
                        evidence_type="external_proof_search_feedback",
                        status=(
                            "EXTERNAL_PROOF_SEARCH_RECORDED_NOT_PROOF_EVIDENCE"
                        ),
                        boundary=LEAN_PROVIDER_BOUNDARY,
                        payload={
                            "provider": str(
                                getattr(
                                    self.proof_search_provider,
                                    "name",
                                    type(self.proof_search_provider).__name__,
                                )
                            ),
                            "status": external_status,
                            "exact_kernel_rerun_required": (
                                not external_exact_source_theorem_verified
                            ),
                        },
                    )
                )
                external_proof_search_tool_calls.insert(
                    0,
                    ToolCallRecord(
                        tool_name="LeanProofSearchProvider.run",
                        inputs={
                            "provider": str(
                                getattr(
                                    self.proof_search_provider,
                                    "name",
                                    type(self.proof_search_provider).__name__,
                                )
                            ),
                            "request_fingerprint": str(
                                external_proof_search_request.get(
                                    "request_fingerprint",
                                    "",
                                )
                                or ""
                            ),
                            "target_lean_declaration": str(
                                external_proof_search_request.get(
                                    "target_lean_declaration",
                                    "",
                                )
                                or ""
                            ),
                        },
                        output_paths=tuple(
                            str(external_proof_search_result.get(key, "") or "")
                            for key in ("report_path", "checkpoint_path")
                            if str(
                                external_proof_search_result.get(key, "") or ""
                            )
                        ),
                        exit_status=(
                            "provider_error"
                            if external_status == "PROVIDER_ERROR"
                            else "0"
                        ),
                        stdout_summary=(
                            f"status={external_status} candidates="
                            f"{len(external_proof_search_result.get('source_theorem_candidate_proof_bodies', []) or [])} "
                            "support_assets="
                            f"{len(external_proof_search_result.get('verified_support_assets', []) or [])}"
                        ),
                        safety_boundary=LEAN_PROVIDER_BOUNDARY,
                    ),
                )

        def preserve_external_proof_search(
            result: AgentStepResult,
        ) -> AgentStepResult:
            return _agent_step_result_with_external_proof_search(
                result,
                external_result=external_proof_search_result,
                artifacts=external_proof_search_artifacts,
                observations=external_proof_search_observations,
                evidence_entries=external_proof_search_evidence_entries,
                tool_calls=external_proof_search_tool_calls,
            )

        proposal_source = ""
        formalizer_theory_trace_contract: dict[str, Any] = {}
        formalizer_theory_trace_alignment_contract: dict[str, Any] = {}
        pseudo_formalization_required = _feedback_requires_pseudo_formalization(
            environment_feedback,
            proof_bank_runtime_memory_summary,
        )
        lean_candidate_revision_feedback: dict[str, Any] | None = None
        lean_candidate_materialization: dict[str, Any] | None = None
        candidate_proof_state_manifest: dict[str, Any] | None = None
        candidate_proof_state_evidence: EvidenceLedgerEntry | None = None
        lean_candidate_client_tool_loop_evidence: dict[str, Any] = {}
        lean_candidate_client_tool_loop_ledger_entry: (
            EvidenceLedgerEntry | None
        ) = None

        def record_candidate_proof_state_feedback(
            proof_state_feedback: Mapping[str, Any],
        ) -> None:
            nonlocal candidate_proof_state_manifest
            nonlocal candidate_proof_state_evidence
            if self.proof_state_provider is None or lean_candidate_materialization is None:
                return
            candidate_proof_state_subclaims = (
                _formalizer_lean_candidate_proof_state_subclaims(
                    lean_candidate_materialization,
                    proof_state_feedback,
                )
            )
            candidate_proof_state_rows = (
                self.proof_state_provider.inspect(candidate_proof_state_subclaims)
                if candidate_proof_state_subclaims
                else []
            )
            candidate_proof_state_row_dicts = [
                proof_state_feedback_row_to_json(row)
                for row in candidate_proof_state_rows
            ]
            if not candidate_proof_state_row_dicts:
                return
            candidate_lean_lsp_mcp_live_called = any(
                any(
                    str(tool).startswith("lean_lsp_mcp.")
                    for tool in (row.get("executed_tools", []) or [])
                )
                for row in candidate_proof_state_row_dicts
            )
            candidate_proof_state_manifest_id = (
                "formalizer_lean_candidate_proof_state_feedback_manifest:"
                + stable_hash(
                    [
                        task.task_id,
                        lean_candidate_materialization.get("manifest_id", ""),
                        candidate_proof_state_row_dicts,
                    ]
                )[:20]
            )
            candidate_proof_state_manifest = {
                "schema_version": RUNTIME_SCHEMA_VERSION,
                "artifact_kind": (
                    "RuntimeFormalizerLeanCandidateProofStateFeedbackManifest"
                ),
                "manifest_id": candidate_proof_state_manifest_id,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "question": _question_to_payload(question),
                "task_id": task.task_id,
                "source_materialization_manifest_id": str(
                    lean_candidate_materialization.get("manifest_id", "")
                ),
                "provider_name": getattr(
                    self.proof_state_provider,
                    "name",
                    "unknown",
                ),
                "lean_lsp_mcp_live_called": candidate_lean_lsp_mcp_live_called,
                "rows": candidate_proof_state_row_dicts,
                "counts": {
                    "rows": len(candidate_proof_state_row_dicts),
                    "residual_goals": sum(
                        len(row.residual_goals) for row in candidate_proof_state_rows
                    ),
                    "executed_tool_calls": sum(
                        len(row.tool_call_trace) for row in candidate_proof_state_rows
                    ),
                    "local_lean_tool_calls": sum(
                        1
                        for row in candidate_proof_state_rows
                        if "local.lake_env_lean" in set(row.executed_tools)
                    ),
                    "lean_lsp_mcp_tool_calls": sum(
                        sum(
                            1
                            for tool in (row.get("executed_tools", []) or [])
                            if str(tool).startswith("lean_lsp_mcp.")
                        )
                        for row in candidate_proof_state_row_dicts
                    ),
                    "route_revision_recommended": sum(
                        1
                        for row in candidate_proof_state_rows
                        if row.route_revision_recommended
                    ),
                },
                "proof_evidence_status": (
                    "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_FEEDBACK_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
            }
            candidate_proof_state_manifest["learning_rows"] = (
                _formalizer_lean_candidate_proof_state_feedback_learning_rows(
                    candidate_proof_state_manifest
                )
            )
            candidate_proof_state_manifest["n_learning_rows"] = len(
                candidate_proof_state_manifest["learning_rows"]
            )
            candidate_proof_state_manifest = _runtime_artifact_with_architect_control(
                candidate_proof_state_manifest_id,
                candidate_proof_state_manifest,
                formalization_control_seed,
                subsystem_override=subsystem_name,
            )
            produced_artifacts[candidate_proof_state_manifest_id] = (
                candidate_proof_state_manifest
            )
            candidate_proof_state_evidence = EvidenceLedgerEntry(
                evidence_id="evidence:"
                + stable_hash([task.task_id, candidate_proof_state_manifest_id])[:20],
                task_id=task.task_id,
                artifact_id=candidate_proof_state_manifest_id,
                evidence_type="formalizer_lean_candidate_proof_state_feedback",
                status=(
                    "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_FEEDBACK_RECORDED_NOT_PROOF_EVIDENCE"
                ),
                boundary=PROOF_STATE_FEEDBACK_BOUNDARY,
                payload={
                    "counts": candidate_proof_state_manifest["counts"],
                    "provider_name": candidate_proof_state_manifest["provider_name"],
                    "lean_lsp_mcp_live_called": candidate_lean_lsp_mcp_live_called,
                },
            )

        if external_exact_source_theorem_verified:
            proposal_source = (
                "external_exact_source_theorem_candidate_kernel_rerun"
            )
            pseudo_formalization_required = False
        elif not llm_research_authority and _should_emit_deterministic_theorem_closure_packet(
            proof_bank_runtime_memory_summary
        ) and not _runtime_context_requires_formalizer_lean_candidate(
            context
        ) and str(
            environment_feedback.get("feedback_type", "") or ""
        ) != "theorem_reduction_closure_execution_feedback":
            proposal_packet = _deterministic_theorem_closure_proposal_packet(
                question=question,
                theorem_goals=theorem_goals,
                proof_bank_runtime_memory_summary=proof_bank_runtime_memory_summary,
            )
            proposal_source = "deterministic_theorem_closure_work_order_seed"
        elif self.proposal_agent is not None:
            try:
                environment_feedback = (
                    _runtime_environment_feedback_with_architect_directive(
                        context=context,
                        subsystem=subsystem_name,
                        feedback=environment_feedback,
                    )
                )
                environment_feedback = (
                    formalizer_feedback_with_task_bound_formal_source_queries(
                        environment_feedback,
                        question=question,
                        theory_packet=(
                            packet if isinstance(packet, Mapping) else {}
                        ),
                        theorem_goals=[
                            _theorem_goal_to_json(row) for row in theorem_goals
                        ],
                    )
                )
                environment_feedback = (
                    _formalizer_environment_feedback_with_formal_source_grounding(
                        environment_feedback,
                        formal_source_retriever=self.formal_source_retriever,
                    )
                )
                formal_source_grounding_summary = (
                    _formalizer_environment_feedback_formal_source_grounding_summary(
                        environment_feedback
                    )
                )
                pseudo_formalization_required = _feedback_requires_pseudo_formalization(
                    environment_feedback,
                    proof_bank_runtime_memory_summary,
                )
                if formal_source_grounding_summary:
                    observations.append(
                        EnvironmentObservation(
                            observation_type=(
                                "formalizer_environment_feedback_formal_source_grounding"
                            ),
                            summary=(
                                "Formalizer/ProofEngineer repair feedback enriched "
                                "with bounded formal-source grounding hits before "
                                "LLM proposal; grounding is not proof evidence"
                            ),
                            payload=formal_source_grounding_summary,
                        )
                    )
                client_tool_revision = (
                    _runtime_formalizer_lean_candidate_client_tool_revision(
                        proposal_agent=self.proposal_agent,
                        question=question,
                        task=task,
                        blackboard=blackboard,
                        theory_packet=(
                            packet if isinstance(packet, Mapping) else {}
                        ),
                        environment_feedback=environment_feedback,
                        proof_bank_runtime_memory_summary=(
                            proof_bank_runtime_memory_summary
                        ),
                        formal_source_retriever=self.formal_source_retriever,
                        lean_candidate_root=self.lean_candidate_root,
                        lean_candidate_local_lean=(
                            self.lean_candidate_local_lean
                        ),
                        lean_candidate_lean_project=(
                            self.lean_candidate_lean_project
                        ),
                        lean_candidate_lean_timeout=(
                            self.lean_candidate_lean_timeout
                        ),
                    )
                )
                if client_tool_revision is not None:
                    (
                        proposal_packet,
                        lean_candidate_client_tool_loop_evidence,
                    ) = client_tool_revision
                else:
                    proposal_packet = self.proposal_agent.propose(
                        question=question,
                        theory_packet=packet if isinstance(packet, Mapping) else {},
                        simulation_manifest=(
                            simulation_manifest
                            if isinstance(simulation_manifest, Mapping)
                            else {}
                        ),
                        algorithm_manifest=(
                            algorithm_manifest
                            if isinstance(algorithm_manifest, Mapping)
                            else {}
                        ),
                        registered_problem=_problem_to_json(problem),
                        theorem_goals=[_theorem_goal_to_json(row) for row in theorem_goals],
                        proof_bank_obligation_catalog=proof_bank_obligation_catalog,
                        proof_bank_runtime_memory_summary=proof_bank_runtime_memory_summary,
                        environment_feedback=environment_feedback,
                    )
            except PacketValidationError as exc:
                return preserve_external_proof_search(
                    _formalizer_packet_validation_failure_result(
                        task=task,
                        question=question,
                        theory_packet_id=packet_id,
                        simulation_manifest_id=simulation_manifest_id,
                        algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
                        proof_bank_runtime_memory_summary=(
                            proof_bank_runtime_memory_summary
                        ),
                        exc=exc,
                        environment_feedback=environment_feedback,
                        formal_source_retriever=self.formal_source_retriever,
                    )
                )
            except Exception as exc:
                return preserve_external_proof_search(
                    _formalizer_provider_failure_result(
                        task=task,
                        question=question,
                        theory_packet_id=packet_id,
                        simulation_manifest_id=simulation_manifest_id,
                        algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
                        proof_bank_runtime_memory_summary=(
                            proof_bank_runtime_memory_summary
                        ),
                        environment_feedback=environment_feedback,
                        exc=exc,
                        max_provider_retries=(
                            self.runtime_config.max_subsystem_retries
                        ),
                    )
                )
            proposal_source = "llm_formalizer_proof_engineer_proposal"
        if proposal_packet is not None:
            if source_theorem_promotion_generation_request:
                (
                    promotion_response_rows,
                    promotion_response_errors,
                ) = _runtime_source_theorem_promotion_generation_response_binding(
                    proposal_packet=proposal_packet,
                    generation_request=(
                        source_theorem_promotion_generation_request
                    ),
                )
                if promotion_response_errors:
                    return preserve_external_proof_search(
                        _formalizer_packet_validation_failure_result(
                            task=task,
                            question=question,
                            theory_packet_id=packet_id,
                            simulation_manifest_id=simulation_manifest_id,
                            algorithm_sandbox_manifest_id=(
                                algorithm_sandbox_manifest_id
                            ),
                            proof_bank_runtime_memory_summary=(
                                proof_bank_runtime_memory_summary
                            ),
                            exc=PacketValidationError(
                                validation_label=(
                                    "Source theorem promotion generation response"
                                ),
                                attempts=1,
                                errors=list(promotion_response_errors),
                                history=[
                                    {
                                        "source_theorem_promotion_generation_request_id": str(
                                            source_theorem_promotion_generation_request.get(
                                                "request_id",
                                                "",
                                            )
                                            or ""
                                        ),
                                        "formalizer_packet_id": str(
                                            proposal_packet.get("packet_id", "") or ""
                                        ),
                                        "n_requested_targets": len(
                                            source_theorem_promotion_generation_request.get(
                                                "target_rows",
                                                [],
                                            )
                                            or []
                                        ),
                                    }
                                ],
                            ),
                            environment_feedback=environment_feedback,
                            formal_source_retriever=(
                                self.formal_source_retriever
                            ),
                        )
                    )
                promotion_response_binding_id = (
                    "runtime_source_theorem_promotion_generation_response_binding:"
                    + stable_hash(
                        [
                            source_theorem_promotion_generation_request.get(
                                "request_id",
                                "",
                            ),
                            proposal_packet.get("packet_id", ""),
                            promotion_response_rows,
                        ]
                    )[:20]
                )
                source_theorem_promotion_generation_response_binding = {
                    "schema_version": RUNTIME_SCHEMA_VERSION,
                    "artifact_kind": (
                        "RuntimeSourceTheoremPromotionGenerationResponseBinding"
                    ),
                    "binding_id": promotion_response_binding_id,
                    "created_at": datetime.now(timezone.utc).isoformat(),
                    "question_id": question.id,
                    "task_id": task.task_id,
                    "source_theorem_promotion_generation_request_id": str(
                        source_theorem_promotion_generation_request.get(
                            "request_id",
                            "",
                        )
                        or ""
                    ),
                    "source_theorem_promotion_generation_request_hash": stable_hash(
                        source_theorem_promotion_generation_request
                    ),
                    "formalizer_packet_id": str(
                        proposal_packet.get("packet_id", "") or ""
                    ),
                    "formalizer_packet_hash_before_runtime_control": stable_hash(
                        proposal_packet
                    ),
                    "target_bindings": promotion_response_rows,
                    "n_requested_targets": len(
                        source_theorem_promotion_generation_request.get(
                            "target_rows",
                            [],
                        )
                        or []
                    ),
                    "n_bound_response_targets": len(promotion_response_rows),
                    "response_contract_satisfied": True,
                    "next_compiler_subsystem": (
                        EXACT_SOURCE_THEOREM_PROOF_BODY_SUBSYSTEM
                    ),
                    "proof_evidence_status": (
                        "PROMOTION_GENERATION_RESPONSE_BOUND_NOT_PROOF_EVIDENCE"
                    ),
                    "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
                }
                source_theorem_promotion_generation_response_binding = (
                    _runtime_artifact_with_architect_control(
                        promotion_response_binding_id,
                        source_theorem_promotion_generation_response_binding,
                        formalization_control_seed,
                        subsystem_override=subsystem_name,
                    )
                )
                produced_artifacts[promotion_response_binding_id] = (
                    source_theorem_promotion_generation_response_binding
                )
                source_theorem_promotion_generation_response_binding_evidence = (
                    EvidenceLedgerEntry(
                        evidence_id="evidence:"
                        + stable_hash(
                            [task.task_id, promotion_response_binding_id]
                        )[:20],
                        task_id=task.task_id,
                        artifact_id=promotion_response_binding_id,
                        evidence_type=(
                            "source_theorem_promotion_generation_response_binding"
                        ),
                        status=(
                            "PROMOTION_GENERATION_RESPONSE_BOUND_NOT_PROOF_EVIDENCE"
                        ),
                        boundary=KERNEL_PROOF_BOUNDARY,
                        payload={
                            "generation_request_id": str(
                                source_theorem_promotion_generation_request.get(
                                    "request_id",
                                    "",
                                )
                                or ""
                            ),
                            "n_bound_response_targets": len(
                                promotion_response_rows
                            ),
                            "next_compiler_subsystem": (
                                EXACT_SOURCE_THEOREM_PROOF_BODY_SUBSYSTEM
                            ),
                            "source_theorem_kernel_verified": False,
                        },
                    )
                )
            (
                llm_requested_proof_obligation_ids,
                llm_off_catalog_proof_obligation_ids,
                llm_rejected_proof_obligation_ids,
            ) = _proof_bank_obligation_request_ids(
                proposal_packet,
                catalog_ids=tuple(
                    str(row.get("obligation_id", "") or "")
                    for row in proof_bank_obligation_catalog
                    if isinstance(row, Mapping)
                ),
            )
            memory_kernel_verified_set = set(memory_kernel_verified_proof_obligation_ids)
            llm_prioritized_proof_obligation_ids = tuple(
                row for row in llm_requested_proof_obligation_ids if row not in memory_kernel_verified_set
            )
            llm_suppressed_kernel_verified_proof_obligation_ids = tuple(
                row for row in llm_requested_proof_obligation_ids if row in memory_kernel_verified_set
            )
            proposal_id = str(proposal_packet["packet_id"])
            proposal_packet = _runtime_artifact_with_architect_control(
                proposal_id,
                proposal_packet,
                formalization_control_seed,
                subsystem_override=subsystem_name,
            )
            theory_trace_contracts = _runtime_theory_trace_consumption_contracts(
                proposal_packet
            )
            formalizer_theory_trace_contract = (
                theory_trace_contracts[0] if theory_trace_contracts else {}
            )
            formalizer_theory_trace_alignment_contract = (
                dict(proposal_packet.get("theory_trace_alignment_contract", {}))
                if isinstance(
                    proposal_packet.get("theory_trace_alignment_contract", {}),
                    Mapping,
                )
                else {}
            )
            produced_artifacts[proposal_id] = proposal_packet
            if lean_candidate_client_tool_loop_evidence:
                loop_artifact_id = str(
                    lean_candidate_client_tool_loop_evidence.get(
                        "artifact_id",
                        "",
                    )
                    or "formalizer_lean_candidate_client_tool_loop:"
                    + stable_hash(
                        [
                            task.task_id,
                            proposal_id,
                            lean_candidate_client_tool_loop_evidence,
                        ]
                    )[:20]
                )
                lean_candidate_client_tool_loop_evidence["artifact_id"] = (
                    loop_artifact_id
                )
                produced_artifacts[loop_artifact_id] = (
                    _runtime_artifact_with_architect_control(
                        loop_artifact_id,
                        lean_candidate_client_tool_loop_evidence,
                        formalization_control_seed,
                        subsystem_override=subsystem_name,
                    )
                )
                lean_candidate_client_tool_loop_ledger_entry = (
                    EvidenceLedgerEntry(
                        evidence_id="evidence:"
                        + stable_hash([task.task_id, loop_artifact_id])[:20],
                        task_id=task.task_id,
                        artifact_id=loop_artifact_id,
                        evidence_type=(
                            "formalizer_lean_candidate_client_tool_loop"
                        ),
                        status=(
                            "LEAN_CANDIDATE_CLIENT_TOOL_LOOP_RECORDED_"
                            "NOT_PROOF_EVIDENCE"
                        ),
                        boundary=FORMALIZER_BOUNDARY,
                        payload={
                            "candidate_id": str(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "candidate_id",
                                    "",
                                )
                                or ""
                            ),
                            "parent_source_hash": str(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "parent_source_hash",
                                    "",
                                )
                                or ""
                            ),
                            "submitted_source_hash": str(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "submitted_source_hash",
                                    "",
                                )
                                or ""
                            ),
                            "runtime_executed_tool_calls": int(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "runtime_executed_tool_calls",
                                    0,
                                )
                                or 0
                            ),
                            "runtime_selected_lean_code": False,
                            "independent_semantic_review_required": True,
                            "kernel_verified": False,
                        },
                    )
                )
                observations.append(
                    EnvironmentObservation(
                        observation_type=(
                            "formalizer_lean_candidate_client_tool_loop"
                        ),
                        summary=(
                            "model-owned Lean edit/search/check loop submitted a "
                            "locally compiling candidate for independent review"
                        ),
                        payload={
                            "artifact_id": loop_artifact_id,
                            "candidate_id": str(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "candidate_id",
                                    "",
                                )
                                or ""
                            ),
                            "turns": int(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "turns",
                                    0,
                                )
                                or 0
                            ),
                            "tool_calls": int(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "tool_calls",
                                    0,
                                )
                                or 0
                            ),
                            "runtime_executed_tool_calls": int(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "runtime_executed_tool_calls",
                                    0,
                                )
                                or 0
                            ),
                            "proof_evidence_status": str(
                                lean_candidate_client_tool_loop_evidence.get(
                                    "proof_evidence_status",
                                    "",
                                )
                                or ""
                            ),
                        },
                    )
                )
            pseudo_formal_work_order_rows = _formalizer_pseudo_formal_work_order_rows(
                proposal_packet=proposal_packet
            )
            lean_candidate_materialization = (
                _materialize_formalizer_lean_candidate_artifacts(
                    root=self.lean_candidate_root,
                    question=question,
                    task=task,
                    proposal_packet=proposal_packet,
                    local_lean=self.lean_candidate_local_lean,
                    lean_project=self.lean_candidate_lean_project,
                    lean_timeout=self.lean_candidate_lean_timeout,
                )
            )
            lean_candidate_materialization = _runtime_artifact_with_architect_control(
                str(lean_candidate_materialization.get("manifest_id", "")),
                lean_candidate_materialization,
                formalization_control_seed,
                subsystem_override=subsystem_name,
            )
            required_pf_bv_route_satisfies_formalizer_candidate_gate = (
                _feedback_requires_pseudo_formalization(
                    environment_feedback,
                    proof_bank_runtime_memory_summary,
                )
                and bool(
                    pseudo_formal_routable_work_order_rows(
                        pseudo_formal_work_order_rows
                    )
                )
            )
            if (
                _runtime_context_requires_formalizer_lean_candidate(context)
                and int(
                    lean_candidate_materialization.get("n_candidate_sources", 0)
                    or 0
                )
                == 0
                and not required_pf_bv_route_satisfies_formalizer_candidate_gate
            ):
                validation_task = AgentTask(
                    task_id=task.task_id,
                    owner_subsystem=task.owner_subsystem,
                    objective=task.objective,
                    inputs={**task.inputs, "architect_context": context},
                    allowed_tools=task.allowed_tools,
                    budget=task.budget,
                    expected_artifacts=task.expected_artifacts,
                    acceptance_gate=task.acceptance_gate,
                    stop_condition=task.stop_condition,
                )
                return preserve_external_proof_search(
                    _formalizer_packet_validation_failure_result(
                        task=validation_task,
                        question=question,
                        theory_packet_id=packet_id,
                        simulation_manifest_id=simulation_manifest_id,
                        algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
                        proof_bank_runtime_memory_summary=(
                            proof_bank_runtime_memory_summary
                        ),
                        exc=PacketValidationError(
                            validation_label=(
                                "Formalizer capability-eval Lean candidate"
                            ),
                            attempts=1,
                            errors=[
                                "capability_eval requires at least one Claude/OpenAI-generated "
                                "Lean statement sketch in formal_targets or "
                                "source_to_bridge_premise_derivation_candidates"
                            ],
                            history=[
                                {
                                    "packet_id": proposal_id,
                                    "n_candidate_sources": 0,
                                    "runtime_requested_evidence_contract": dict(
                                        context.get(
                                            "runtime_requested_evidence_contract",
                                            {},
                                        )
                                        if isinstance(
                                            context.get(
                                                "runtime_requested_evidence_contract",
                                                {},
                                            ),
                                            Mapping,
                                        )
                                        else {}
                                    ),
                                }
                            ],
                        ),
                        environment_feedback=environment_feedback,
                        formal_source_retriever=self.formal_source_retriever,
                    )
                )
            if lean_candidate_materialization["n_candidate_sources"] > 0:
                produced_artifacts[
                    str(lean_candidate_materialization["manifest_id"])
                ] = lean_candidate_materialization
                lean_candidate_revision_feedback = (
                    _formalizer_lean_candidate_revision_feedback(
                        lean_candidate_materialization,
                        formal_source_retriever=self.formal_source_retriever,
                        prior_environment_feedback=environment_feedback,
                    )
                )
                if lean_candidate_revision_feedback is not None:
                    repair_retry_depth = max(
                        0,
                        _runtime_safe_int(
                            environment_feedback.get(
                                "formalizer_lean_revision_depth",
                                environment_feedback.get(
                                    "formalizer_lean_repair_retry_depth",
                                    0,
                                ),
                            )
                        ),
                    )
                    if str(task.task_id).startswith(
                        ("formalize-lean-revision:", "formalize-lean-repair:")
                    ):
                        repair_retry_depth += 1
                    lean_candidate_revision_feedback[
                        "formalizer_lean_revision_depth"
                    ] = repair_retry_depth
                    lean_candidate_revision_feedback[
                        "formalizer_lean_repair_retry_depth"
                    ] = repair_retry_depth
                    lean_candidate_revision_feedback[
                        "repeated_formalizer_lean_candidate_failure"
                    ] = repair_retry_depth > 0
                    _enrich_repeated_formalizer_lean_candidate_feedback(
                        lean_candidate_revision_feedback
                    )
                    record_candidate_proof_state_feedback(
                        lean_candidate_revision_feedback
                    )
                    if candidate_proof_state_manifest is not None:
                        proofengineer_context = (
                            lean_candidate_revision_feedback.setdefault(
                                "proofengineer_repair_context",
                                {},
                            )
                        )
                        if isinstance(proofengineer_context, dict):
                            complete_candidate_proof_state_manifest = deepcopy(
                                dict(candidate_proof_state_manifest)
                            )
                            proofengineer_context[
                                "candidate_proof_state_manifest"
                            ] = complete_candidate_proof_state_manifest
                            proofengineer_context[
                                "candidate_proof_state_feedback_rows"
                            ] = deepcopy(
                                list(
                                    candidate_proof_state_manifest.get(
                                        "rows",
                                        [],
                                    )
                                    or []
                                )
                            )
                            proofengineer_context[
                                "candidate_proof_state_feedback_counts"
                            ] = deepcopy(
                                dict(
                                    candidate_proof_state_manifest.get(
                                        "counts",
                                        {},
                                    )
                                    or {}
                                )
                            )
                            proofengineer_context[
                                "candidate_proof_state_provider"
                            ] = str(
                                candidate_proof_state_manifest.get(
                                    "provider_name",
                                    "",
                                )
                                or ""
                            )
                elif (
                    self.proof_state_provider is not None
                    and _runtime_context_requires_formalizer_live_prover_tool_call(
                        context
                    )
                    and int(
                        lean_candidate_materialization.get(
                            "n_lean_lsp_mcp_ready_requests",
                            0,
                        )
                        or 0
                    )
                    > 0
                ):
                    record_candidate_proof_state_feedback(
                        _formalizer_lean_candidate_live_prover_inspection_feedback(
                            lean_candidate_materialization
                        )
                    )
            is_deterministic_closure = (
                proposal_source == "deterministic_theorem_closure_work_order_seed"
            )
            observations.append(
                EnvironmentObservation(
                    observation_type=proposal_source,
                    summary=(
                        "deterministic theorem-closure work-order seed recorded after "
                        "runtime memory exhausted the registered proof-bank bridge catalog"
                        if is_deterministic_closure
                        else "validated LLM Formalizer/ProofEngineer proposal recorded "
                        "before proof-bank/kernel evaluation"
                    ),
                    payload={
                        "packet_id": proposal_id,
                        "source_agent": str(proposal_packet.get("source_agent", "")),
                        "n_formal_targets": len(proposal_packet.get("formal_targets", []) or []),
                        "n_retrieval_queries": len(proposal_packet.get("retrieval_queries", []) or []),
                        "n_proof_bank_obligation_requests": len(
                            proposal_packet.get("proof_bank_obligation_requests", []) or []
                        ),
                        "n_lean_candidate_sources": int(
                            lean_candidate_materialization.get(
                                "n_candidate_sources",
                                0,
                            )
                        ),
                        "n_lean_candidate_artifacts_written": int(
                            lean_candidate_materialization.get(
                                "n_candidate_artifacts_written",
                                0,
                            )
                        ),
                        "n_registered_proof_bank_obligation_candidates": len(proof_bank_obligation_catalog),
                        "n_registered_proof_bank_obligation_requests": len(llm_requested_proof_obligation_ids),
                        "n_prioritized_registered_proof_bank_obligation_requests": len(
                            llm_prioritized_proof_obligation_ids
                        ),
                        "n_suppressed_kernel_verified_proof_bank_obligation_requests": len(
                            llm_suppressed_kernel_verified_proof_obligation_ids
                        ),
                        "n_off_catalog_proof_bank_obligation_requests": len(
                            llm_off_catalog_proof_obligation_ids
                        ),
                        "n_pseudo_formal_proof_packets": len(
                            proposal_packet.get("pseudo_formal_proof_packets", [])
                            or []
                        ),
                        "n_pseudo_formal_work_order_rows": len(
                            pseudo_formal_work_order_rows
                        ),
                        "proof_evidence_status": str(
                            proposal_packet.get(
                                "proof_evidence_status",
                                FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE,
                            )
                        ),
                        "runtime_theory_trace_consumption_contract": runtime_theory_trace_contract,
                        "theory_trace_consumption_contract": formalizer_theory_trace_contract,
                        "theory_trace_alignment_contract": formalizer_theory_trace_alignment_contract,
                    },
                )
            )
            proposal_evidence = EvidenceLedgerEntry(
                evidence_id="evidence:" + stable_hash([task.task_id, proposal_id])[:20],
                task_id=task.task_id,
                artifact_id=proposal_id,
                evidence_type=proposal_source,
                status=(
                    "WORK_ORDER_SEED_RECORDED_NOT_PROOF_EVIDENCE"
                    if is_deterministic_closure
                    else "PROPOSAL_RECORDED_REQUIRES_KERNEL_VERIFICATION"
                ),
                boundary=FORMALIZER_BOUNDARY,
                payload={
                    "source_agent": str(proposal_packet.get("source_agent", "")),
                    "n_formal_targets": len(proposal_packet.get("formal_targets", []) or []),
                    "n_retrieval_queries": len(proposal_packet.get("retrieval_queries", []) or []),
                    "n_lean_candidate_sources": int(
                        lean_candidate_materialization.get("n_candidate_sources", 0)
                    ),
                    "n_lean_candidate_artifacts_written": int(
                        lean_candidate_materialization.get(
                            "n_candidate_artifacts_written",
                            0,
                        )
                    ),
                    "lean_candidate_materialization_manifest_id": str(
                        lean_candidate_materialization.get("manifest_id", "")
                    ),
                    "n_registered_proof_bank_obligation_candidates": len(proof_bank_obligation_catalog),
                    "n_registered_proof_bank_obligation_requests": len(llm_requested_proof_obligation_ids),
                    "n_prioritized_registered_proof_bank_obligation_requests": len(
                        llm_prioritized_proof_obligation_ids
                    ),
                    "n_suppressed_kernel_verified_proof_bank_obligation_requests": len(
                        llm_suppressed_kernel_verified_proof_obligation_ids
                    ),
                    "n_off_catalog_proof_bank_obligation_requests": len(llm_off_catalog_proof_obligation_ids),
                    "n_pseudo_formal_proof_packets": len(
                        proposal_packet.get("pseudo_formal_proof_packets", [])
                        or []
                    ),
                    "n_pseudo_formal_work_order_rows": len(
                        pseudo_formal_work_order_rows
                    ),
                    "kernel_verified": False,
                    "full_frontier_theorem_proved": False,
                    "runtime_theory_trace_consumption_contract": runtime_theory_trace_contract,
                    "theory_trace_consumption_contract": formalizer_theory_trace_contract,
                    "theory_trace_alignment_contract": formalizer_theory_trace_alignment_contract,
                },
            )
            contract_failure_result = (
                _formalizer_runtime_capability_contract_failure_result_if_needed(
                    task=task,
                    question=question,
                    context=context,
                    theory_packet_id=packet_id,
                    simulation_manifest_id=simulation_manifest_id,
                    algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
                    lean_candidate_materialization=lean_candidate_materialization,
                    candidate_proof_state_manifest=candidate_proof_state_manifest,
                    proof_state_provider=self.proof_state_provider,
                    lean_candidate_local_lean=self.lean_candidate_local_lean,
                    pseudo_formal_candidate_gate_satisfied=(
                        required_pf_bv_route_satisfies_formalizer_candidate_gate
                    ),
                    architect_coordinator_available=(
                        self.architect_coordinator_available
                    ),
                    produced_artifacts=produced_artifacts,
                    observations=observations,
                    evidence_entries=(
                        proposal_evidence,
                        candidate_proof_state_evidence,
                    ),
                )
            )
            if contract_failure_result is not None:
                return preserve_external_proof_search(contract_failure_result)
        subclaims = _run_runtime_coroutine_from_sync(
            self.prover.prove(
                problem,
                theorem_goals,
                prioritized_proof_obligation_ids=(
                    *memory_prioritized_proof_obligation_ids,
                    *llm_prioritized_proof_obligation_ids,
                ),
                excluded_proof_obligation_ids=memory_kernel_verified_proof_obligation_ids,
            )
        )
        proof_obligation_control = self.prover.proof_obligation_control()
        proof_obligation_control["memory_prioritized_proof_obligation_ids"] = list(
            memory_prioritized_proof_obligation_ids
        )
        proof_obligation_control["memory_off_catalog_proof_obligation_ids"] = list(
            memory_off_catalog_proof_obligation_ids
        )
        proof_obligation_control["memory_rejected_proof_obligation_ids"] = list(
            memory_rejected_proof_obligation_ids
        )
        proof_obligation_control["memory_kernel_verified_proof_obligation_ids"] = list(
            memory_kernel_verified_proof_obligation_ids
        )
