def _formalizer_lean_candidate_declaration_location(
    source: str,
    *,
    candidate_lean_declaration: str,
) -> dict[str, Any]:
    """Locate a structured agent-authored identity without parsing Lean source."""

    declaration = str(candidate_lean_declaration or "").strip()
    if not declaration:
        return {
            "target_lean_line": 0,
            "target_lean_column": 0,
            "target_lean_declaration": "",
            "target_lean_location_source": "structured_candidate_declaration_missing",
        }
    for index, line in enumerate(source.splitlines(), start=1):
        column = line.find(declaration)
        if column >= 0:
            return {
                "target_lean_line": index,
                "target_lean_column": column + 1,
                "target_lean_declaration": declaration,
                "target_lean_location_source": (
                    "formalizer_structured_candidate_declaration_exact_source_location"
                ),
            }
    return {
        "target_lean_line": 0,
        "target_lean_column": 0,
        "target_lean_declaration": declaration,
        "target_lean_location_source": (
            "structured_candidate_declaration_not_located_in_exact_source"
        ),
    }


def _formalizer_lean_candidate_live_proof_state_request(
    *,
    candidate_id: str,
    candidate_kind: str,
    artifact_path: str,
    proof_state_artifact_path: str = "",
    target_location: Mapping[str, Any],
    source_hash: str,
) -> dict[str, Any]:
    target_line = int(target_location.get("target_lean_line", 0) or 0)
    target_declaration = str(
        target_location.get("target_lean_declaration", "") or ""
    )
    if not artifact_path or target_line <= 0 or not target_declaration:
        return {}
    proof_state_path = str(proof_state_artifact_path or artifact_path)
    target_column = int(target_location.get("target_lean_column", 1) or 1)
    mcp_tools = (
        "lean_diagnostic_messages",
        "lean_goal",
        "lean_state_search",
        "lean_multi_attempt",
    )
    return {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "request_id": "formalizer_live_proof_state_request:"
        + stable_hash(
            [
                candidate_id,
                candidate_kind,
                artifact_path,
                proof_state_path,
                target_line,
                target_column,
                target_declaration,
                source_hash,
            ]
        )[:20],
        "provider_preferences": (
            "lean_lsp_mcp",
            "local_lean_proof_state_adapter",
            "local.lake_env_lean",
        ),
        "mcp_tool_calls": tuple(
            {
                "tool": tool,
                "arguments": {
                    "file": proof_state_path,
                    "line": target_line,
                    "column": target_column,
                    "declaration": target_declaration,
                },
            }
            for tool in mcp_tools
        ),
        "fallback_adapter": "local_lean_proof_state_feedback",
        "candidate_artifact_path": artifact_path,
        "kernel_check_artifact_path": artifact_path,
        "proof_state_artifact_path": proof_state_path,
        "project_local_proof_state_artifact": bool(
            proof_state_artifact_path and proof_state_artifact_path != artifact_path
        ),
        "target_lean_file": proof_state_path,
        "target_lean_line": target_line,
        "target_lean_column": target_column,
        "target_lean_declaration": target_declaration,
        "expected_transcript_events": (
            "lean_diagnostic_messages_result",
            "lean_goal_result",
            "lean_state_search_result",
            "lean_multi_attempt_result",
            "local_lean_or_axle_verifier_result",
        ),
        "proof_evidence_status": "LIVE_PROOF_STATE_REQUEST_NOT_PROOF_EVIDENCE",
        "proof_evidence_boundary": (
            "This is an operational ProofEngineer request for live proof-state "
            "diagnostics/search. It is not proof evidence until a regenerated exact "
            "artifact passes local Lean/AXLE kernel verification."
        ),
    }


def _formalizer_proof_state_revision_round(
    environment_feedback: Mapping[str, Any],
) -> int:
    feedback = (
        environment_feedback
        if isinstance(environment_feedback, Mapping)
        else {}
    )
    parent = feedback.get("parent_formalizer_proof_state_feedback", {})
    parent = parent if isinstance(parent, Mapping) else {}
    raw = feedback.get("next_formalizer_proof_state_revision_round")
    if raw is None:
        raw = feedback.get("formalizer_proof_state_revision_round")
    if raw is None:
        raw = (
            feedback.get("next_formalizer_proof_state_repair_round")
            if feedback.get("next_formalizer_proof_state_repair_round") is not None
            else feedback.get("formalizer_proof_state_repair_round")
        )
    if raw is None:
        raw = parent.get("next_formalizer_proof_state_revision_round")
    if raw is None:
        raw = parent.get("formalizer_proof_state_revision_round")
    if raw is None:
        raw = (
            parent.get("next_formalizer_proof_state_repair_round")
            if parent.get("next_formalizer_proof_state_repair_round") is not None
            else parent.get("formalizer_proof_state_repair_round", 0)
        )
    try:
        return max(0, int(raw or 0))
    except (TypeError, ValueError):
        return 0


def _formalizer_proof_state_routing_manifest(
    *,
    question: OpenResearchQuestion,
    task_id: str,
    source_subsystem: str,
    environment_feedback: Mapping[str, Any],
    max_revision_rounds: int,
    proofengineer_available: bool,
    formalization_manifest_id: str,
    proof_state_feedback_manifest_id: str,
    proposal_packet: Mapping[str, Any],
    subclaims: Sequence[FormalSubclaim],
    proof_state_rows: Sequence[Mapping[str, Any]],
    candidate_proof_state_manifest: Mapping[str, Any] | None = None,
    lean_candidate_materialization: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    unresolved_subclaim_rows = [
        deepcopy(dict(row))
        for row in proof_state_rows
        if isinstance(row, Mapping)
        and _bool_like(row.get("route_revision_recommended", False))
        and not _bool_like(row.get("subclaim_kernel_verified", False))
    ]
    candidate_manifest = (
        deepcopy(dict(candidate_proof_state_manifest))
        if isinstance(candidate_proof_state_manifest, Mapping)
        else {}
    )
    candidate_materialization = (
        deepcopy(dict(lean_candidate_materialization))
        if isinstance(lean_candidate_materialization, Mapping)
        else {}
    )
    candidate_source_manifest_id = str(
        candidate_manifest.get("source_materialization_manifest_id", "") or ""
    )
    materialization_manifest_id = str(
        candidate_materialization.get("manifest_id", "") or ""
    )
    candidate_rows_bound = bool(
        candidate_source_manifest_id
        and materialization_manifest_id
        and candidate_source_manifest_id == materialization_manifest_id
    )
    unresolved_candidate_rows = [
        deepcopy(dict(row))
        for row in candidate_manifest.get("rows", []) or []
        if isinstance(row, Mapping)
        and _bool_like(row.get("route_revision_recommended", False))
        and not _bool_like(row.get("subclaim_kernel_verified", False))
    ]
    if not unresolved_subclaim_rows and not unresolved_candidate_rows:
        return None

    current_round = _formalizer_proof_state_revision_round(environment_feedback)
    max_rounds = max(0, int(max_revision_rounds))
    same_agent_revision_available = bool(
        proofengineer_available and current_round < max_rounds
    )
    next_round = current_round + 1 if same_agent_revision_available else current_round
    next_owner = (
        source_subsystem
        if same_agent_revision_available
        else "ArchitectCoordinator"
    )
    failure_classification = (
        "formalizer_proof_state_same_agent_revision_requested"
        if same_agent_revision_available
        else "formalizer_proof_state_revision_budget_architect_replan"
    )
    routing_authority = (
        "same_model_tool_loop"
        if same_agent_revision_available
        else "ArchitectCoordinator_model_packet"
    )
    feedback = {
        "feedback_type": "formalizer_proof_state_feedback",
        "failure_classification": failure_classification,
        "source_subsystem": source_subsystem,
        "formalizer_proof_state_revision_round": current_round,
        "next_formalizer_proof_state_revision_round": next_round,
        "max_formalizer_proof_state_revision_rounds": max_rounds,
        "same_agent_revision_available": same_agent_revision_available,
        "formalization_manifest_id": formalization_manifest_id,
        "proof_state_feedback_manifest_id": proof_state_feedback_manifest_id,
        "candidate_proof_state_feedback_manifest_id": str(
            candidate_manifest.get("manifest_id", "") or ""
        ),
        "candidate_materialization_manifest_id": materialization_manifest_id,
        "candidate_materialization_lineage_bound": candidate_rows_bound,
        "previous_formalizer_proposal_id": str(
            proposal_packet.get("packet_id", "") or ""
        ),
        "source_formalizer_proposal": deepcopy(dict(proposal_packet)),
        "formal_subclaims": [asdict(subclaim) for subclaim in subclaims],
        "candidate_proof_state_manifest": candidate_manifest,
        "lean_candidate_materialization": candidate_materialization,
        "proof_state_feedback_rows": unresolved_subclaim_rows,
        "candidate_proof_state_feedback_rows": unresolved_candidate_rows,
        "runtime_resource_observations": {
            "proofengineer_available": bool(proofengineer_available),
            "candidate_materialization_lineage_bound": candidate_rows_bound,
            "revision_rounds_used": current_round,
            "max_revision_rounds": max_rounds,
            "same_model_revision_available": same_agent_revision_available,
        },
        "routing_authority": routing_authority,
        "runtime_selected_research_owner": False,
        "runtime_selected_source_edit": False,
        "proof_evidence_status": (
            "FORMALIZER_PROOF_STATE_ROUTING_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
    }
    manifest_id = "formalizer_proof_state_routing_manifest:" + stable_hash(
        [task_id, feedback]
    )[:20]
    learning_row = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeLearningRow",
        "learning_task": "formalizer_proof_state_routing",
        "question_id": question.id,
        "question_title": question.title,
        "source_manifest_id": manifest_id,
        "source_formalization_manifest_id": formalization_manifest_id,
        "source_proof_state_feedback_manifest_id": (
            proof_state_feedback_manifest_id
        ),
        "next_owner_subsystem": next_owner,
        "input_summary": {
            "trigger": "FORMALIZER_PROOF_STATE_ROUTE_REVISION",
            "failure_classification": failure_classification,
            "n_subclaim_rows": len(unresolved_subclaim_rows),
            "n_candidate_rows": len(unresolved_candidate_rows),
            "revision_rounds_used": current_round,
            "max_revision_rounds": max_rounds,
            "same_agent_revision_available": same_agent_revision_available,
            "subclaim_ids": sorted(
                {
                    str(row.get("subclaim_id", "") or "")
                    for row in [*unresolved_subclaim_rows, *unresolved_candidate_rows]
                    if str(row.get("subclaim_id", "") or "").strip()
                }
            ),
            "attempt_statuses": sorted(
                {
                    str(row.get("attempt_status", "") or "")
                    for row in [*unresolved_subclaim_rows, *unresolved_candidate_rows]
                    if str(row.get("attempt_status", "") or "").strip()
                }
            ),
        },
        "proof_evidence_status": (
            "FORMALIZER_PROOF_STATE_ROUTING_LEARNING_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
    }
    return {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeFormalizerProofStateRoutingManifest",
        "manifest_id": manifest_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "question": _question_to_payload(question),
        "task_id": task_id,
        "source_subsystem": source_subsystem,
        "source_formalization_manifest_id": formalization_manifest_id,
        "source_proof_state_feedback_manifest_id": proof_state_feedback_manifest_id,
        "source_candidate_proof_state_feedback_manifest_id": str(
            candidate_manifest.get("manifest_id", "") or ""
        ),
        "source_candidate_materialization_manifest_id": materialization_manifest_id,
        "candidate_materialization_lineage_bound": candidate_rows_bound,
        "decision": {
            "next_owner_subsystem": next_owner,
            "failure_classification": failure_classification,
            "formalizer_proof_state_revision_round": current_round,
            "next_formalizer_proof_state_revision_round": next_round,
            "max_formalizer_proof_state_revision_rounds": max_rounds,
            "same_agent_revision_available": same_agent_revision_available,
            "routing_authority": routing_authority,
            "runtime_selected_research_owner": False,
            "runtime_selected_source_edit": False,
        },
        "counts": {
            "route_revision_rows": (
                len(unresolved_subclaim_rows) + len(unresolved_candidate_rows)
            ),
            "subclaim_rows": len(unresolved_subclaim_rows),
            "candidate_rows": len(unresolved_candidate_rows),
        },
        "environment_feedback": feedback,
        "learning_rows": [learning_row],
        "proof_evidence_status": (
            "FORMALIZER_PROOF_STATE_ROUTING_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
    }


def _formalizer_proof_state_routing_task(
    *,
    question: OpenResearchQuestion,
    source_task: AgentTask,
    architect_context: Mapping[str, Any],
    routing_manifest: Mapping[str, Any],
) -> AgentTask | None:
    decision = (
        routing_manifest.get("decision", {})
        if isinstance(routing_manifest.get("decision", {}), Mapping)
        else {}
    )
    feedback = (
        routing_manifest.get("environment_feedback", {})
        if isinstance(
            routing_manifest.get("environment_feedback", {}),
            Mapping,
        )
        else {}
    )
    if not feedback:
        return None

    next_owner = str(decision.get("next_owner_subsystem", "") or "")
    source_subsystem = str(
        routing_manifest.get("source_subsystem", "") or ""
    )
    same_agent_revision_available = _bool_like(
        decision.get("same_agent_revision_available", False)
    )
    if same_agent_revision_available:
        if (
            next_owner not in {"FormalizationEvaluator", "ProofEngineer"}
            or next_owner != source_subsystem
        ):
            return None
        task_prefix = "formalizer-proofstate-revision"
        objective = (
            "Regenerate one complete Formalizer proposal from the complete "
            "proof-state, source, compiler, retrieval, and reviewer observations "
            "using the same proposal model."
        )
        allowed_tools = tuple(
            dict.fromkeys(
                (
                    *source_task.allowed_tools,
                    "model_backend",
                    "local_lean",
                    "lean_lsp_mcp",
                    "formal_source_retrieval",
                    "proof_search",
                    "evidence_ledger",
                )
            )
        )
        expected_artifacts = (
            "formalizer_proof_engineer_proposal",
            "formalization_manifest",
            "formalizer_proof_state_routing_manifest",
        )
        acceptance_gate = (
            "the same model emits a complete new packet or source, and every "
            "compiler/proof-state result remains immutable environment feedback"
        )
        stop_condition = (
            "the complete candidate is tool-checked, the bounded same-model "
            "revision budget is exhausted, or a typed blocker is recorded"
        )
    else:
        if next_owner != "ArchitectCoordinator":
            return None
        task_prefix = "architect-formal-proofstate-replan"
        objective = (
            "Select the next typed owner after the source-producing Formalizer "
            "exhausted its direct revision budget. Preserve the complete source "
            "and environment observations; do not author or prescribe a Lean edit."
        )
        allowed_tools = (
            "model_backend",
            "blackboard",
            "evidence_ledger",
        )
        expected_artifacts = ("architect_feedback_route_decision",)
        acceptance_gate = (
            "the Architect model routes the unchanged blocker to an existing "
            "evidence-producing agent or records a typed blocker"
        )
        stop_condition = (
            "next owner or explicit blocker selected with the proof boundary preserved"
        )

    context = dict(architect_context)
    context["environment_feedback"] = deepcopy(dict(feedback))
    context["runtime_feedback_loop"] = {
        **(
            dict(context.get("runtime_feedback_loop", {}))
            if isinstance(context.get("runtime_feedback_loop", {}), Mapping)
            else {}
        ),
        "source_subsystem": source_subsystem,
        "handoff": str(feedback.get("failure_classification", "") or ""),
        "formalizer_proof_state_routing_manifest_id": str(
            routing_manifest.get("manifest_id", "") or ""
        ),
        "formalization_manifest_id": str(
            routing_manifest.get("source_formalization_manifest_id", "") or ""
        ),
    }
    context = _runtime_context_with_environment_feedback_contract(
        context,
        feedback,
        subsystem=next_owner,
    )
    return AgentTask(
        task_id=(
            f"{task_prefix}:{question.id}:"
            f"{stable_hash([routing_manifest.get('manifest_id', ''), feedback])[:8]}"
        ),
        owner_subsystem=next_owner,
        objective=objective,
        inputs={
            **dict(source_task.inputs),
            "question": _question_to_payload(question),
            "architect_context": context,
            "environment_feedback": deepcopy(dict(feedback)),
            "runtime_architect_operation": (
                ARCHITECT_FEEDBACK_ROUTE_OPERATION
                if next_owner == "ArchitectCoordinator"
                else ""
            ),
            "formalization_manifest_id": str(
                routing_manifest.get("source_formalization_manifest_id", "") or ""
            ),
            "theory_packet_id": str(
                source_task.inputs.get("theory_packet_id", "") or ""
            ),
        },
        allowed_tools=allowed_tools,
        expected_artifacts=expected_artifacts,
        acceptance_gate=acceptance_gate,
        stop_condition=stop_condition,
    )


def _formalizer_lean_candidate_revision_feedback(
    manifest: Mapping[str, Any],
    *,
    formal_source_retriever: Any | None = None,
    prior_environment_feedback: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return complete Lean tool observations to the source-producing model."""

    del formal_source_retriever
    candidate_rows = [
        deepcopy(dict(row))
        for row in manifest.get("candidate_rows", []) or []
        if isinstance(row, Mapping)
    ]
    compiled_non_diagnostic_rows = [
        row
        for row in candidate_rows
        if _bool_like(row.get("local_lean_compiled", False))
        and not _bool_like(row.get("diagnostic_helper_not_source_theorem", False))
    ]
    failed_rows: list[dict[str, Any]] = []
    for row in candidate_rows:
        row["local_lean_attempted"] = _bool_like(
            row.get("local_lean_attempted", False)
        )
        row["local_lean_compiled"] = _bool_like(
            row.get("local_lean_compiled", False)
        )
        precheck_failed = str(row.get("precheck_status", "") or "") == (
            "REJECTED_BY_RUNTIME_PRECHECK"
        )
        precheck_diagnostic_failed = bool(
            str(row.get("precheck_status", "") or "")
            == "MATERIALIZED_WITH_PRECHECK_DIAGNOSTICS_REQUIRES_LOCAL_LEAN_OR_AXLE"
            and row.get("precheck_errors", [])
        )
        local_lean_failed = bool(
            _bool_like(row.get("local_lean_attempted", False))
            and not _bool_like(row.get("local_lean_compiled", False))
        )
        target_identity_failed = bool(
            not _bool_like(row.get("diagnostic_helper_not_source_theorem", False))
            and not _bool_like(row.get("support_candidate_not_source_theorem", False))
            and (
                _bool_like(
                    row.get("target_identity_mismatch_not_source_theorem", False)
                )
                or _bool_like(
                    row.get("target_identity_unbound_not_source_theorem", False)
                )
            )
        )
        if (
            _bool_like(row.get("diagnostic_helper_not_source_theorem", False))
            and compiled_non_diagnostic_rows
            and (precheck_failed or precheck_diagnostic_failed or local_lean_failed)
        ):
            continue
        if not (
            precheck_failed
            or precheck_diagnostic_failed
            or local_lean_failed
            or target_identity_failed
        ):
            continue
        if not str(row.get("lean_source", "") or ""):
            source = str(row.get("lean_source_excerpt", "") or "")
            artifact_path = str(row.get("artifact_path", "") or "")
            if not source and artifact_path:
                try:
                    source = Path(artifact_path).expanduser().read_text(
                        encoding="utf-8"
                    )
                except OSError:
                    source = ""
            if source:
                row["lean_source"] = source
        failed_rows.append(row)
    if not failed_rows:
        return None

    prior_feedback = coding_agent_observations_only(
        prior_environment_feedback
        if isinstance(prior_environment_feedback, Mapping)
        else {}
    )
    prior_context = (
        deepcopy(dict(prior_feedback.get("proofengineer_repair_context", {}) or {}))
        if isinstance(
            prior_feedback.get("proofengineer_repair_context", {}),
            Mapping,
        )
        else {}
    )
    current_context = _formalizer_candidate_exact_proof_search_context(
        manifest=manifest,
        diagnostics=failed_rows,
    )
    candidate_context = {**prior_context, **current_context}
    for runtime_authored_strategy_field in (
        "owner_subsystem",
        "repair_scope",
        "required_behavior",
        "acceptance_gate",
        "proof_body_generation_contract",
        "proof_search_role",
    ):
        candidate_context.pop(runtime_authored_strategy_field, None)
    candidate_context.update(
        {
            "context_kind": "model_owned_complete_lean_revision_observations",
            "model_owns_next_action": True,
            "runtime_selected_source_edit": False,
            "external_proof_search_dispatch_eligible": False,
            "routing_authority_after_revision_budget": (
                "ArchitectCoordinator_model_packet"
            ),
        }
    )

    parent_proof_state_feedback: dict[str, Any] = {}
    if str(prior_feedback.get("feedback_type", "") or "") == (
        "formalizer_proof_state_feedback"
    ):
        parent_proof_state_feedback = deepcopy(prior_feedback)
    elif isinstance(
        prior_feedback.get("parent_formalizer_proof_state_feedback", {}),
        Mapping,
    ):
        parent_proof_state_feedback = deepcopy(
            dict(
                prior_feedback.get(
                    "parent_formalizer_proof_state_feedback",
                    {},
                )
            )
        )

    feedback = {
        "schema_version": manifest.get("schema_version", RUNTIME_SCHEMA_VERSION),
        "source_artifact_kind": str(manifest.get("artifact_kind", "") or ""),
        "source_manifest_id": str(manifest.get("manifest_id", "") or ""),
        "source_manifest_path": str(manifest.get("manifest_path", "") or ""),
        "question": deepcopy(manifest.get("question", {})),
        "task_id": str(manifest.get("task_id", "") or ""),
        "source_formalizer_packet_id": str(
            manifest.get("source_formalizer_packet_id", "") or ""
        ),
        "n_candidate_sources": len(candidate_rows),
        "n_candidate_artifacts_written": int(
            manifest.get("n_candidate_artifacts_written", 0) or 0
        ),
        "n_precheck_rejected": int(manifest.get("n_precheck_rejected", 0) or 0),
        "n_local_lean_checked": int(
            manifest.get("n_local_lean_checked", 0) or 0
        ),
        "n_local_lean_compiled": int(
            manifest.get("n_local_lean_compiled", 0) or 0
        ),
        "feedback_id": (
            "formalizer_lean_candidate_observation:"
            + stable_hash(
                [
                    manifest.get("manifest_id", ""),
                    failed_rows,
                    prior_feedback,
                ]
            )[:20]
        ),
        "feedback_type": "formalizer_lean_candidate_local_lean_feedback",
        "failure_classification": "formalizer_lean_candidate_tool_rejected",
        "candidate_rows": candidate_rows,
        "candidate_diagnostics": failed_rows,
        "proofengineer_repair_context": candidate_context,
        "model_owned_complete_source_regeneration": True,
        "runtime_selected_source_edit": False,
        "proof_evidence_status": (
            "FORMALIZER_LEAN_CANDIDATE_TOOL_OBSERVATIONS_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }
    if prior_feedback:
        feedback["prior_environment_feedback"] = prior_feedback
    if parent_proof_state_feedback:
        feedback["parent_formalizer_proof_state_feedback"] = (
            parent_proof_state_feedback
        )
    prior_external_proof_search_result = prior_feedback.get(
        "external_proof_search_result",
        {},
    )
    if isinstance(prior_external_proof_search_result, Mapping) and (
        prior_external_proof_search_result
    ):
        feedback["external_proof_search_result"] = deepcopy(
            dict(prior_external_proof_search_result)
        )
    return feedback


def _enrich_repeated_formalizer_lean_candidate_feedback(
    feedback: dict[str, Any],
) -> dict[str, Any]:
    """Record repeated tool failure lineage without prescribing a Lean repair."""

    if not isinstance(feedback, dict):
        return feedback
    if not _bool_like(
        feedback.get("repeated_formalizer_lean_candidate_failure", False)
    ):
        return feedback
    feedback["repeated_formalizer_lean_candidate_observation"] = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RepeatedFormalizerToolObservation",
        "observation_id": "repeated_formalizer_tool_observation:"
        + stable_hash(
            [
                feedback.get("source_manifest_id", ""),
                feedback.get(
                    "formalizer_lean_revision_depth",
                    feedback.get("formalizer_lean_repair_retry_depth", 0),
                ),
                feedback.get("candidate_diagnostics", []),
            ]
        )[:20],
        "source_manifest_id": str(feedback.get("source_manifest_id", "") or ""),
        "retry_depth": int(
            feedback.get(
                "formalizer_lean_revision_depth",
                feedback.get("formalizer_lean_repair_retry_depth", 0),
            )
            or 0
        ),
        "model_owned_next_action": True,
        "runtime_selected_revision": False,
        "proof_evidence_status": (
            "REPEATED_FORMALIZER_TOOL_OBSERVATION_NOT_PROOF_EVIDENCE"
        ),
        "boundary": (
            "Repeated Lean failure is a model-visible tool observation. It does "
            "not select a tactic, import, theorem decomposition, or proof."
        ),
    }
    return feedback


def _formalizer_candidate_exact_proof_search_context(
    *,
    manifest: Mapping[str, Any],
    diagnostics: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Bind a hash-verified complete candidate to downstream tool observations.

    Lean owns declaration grammar and elaboration. This function checks only
    artifact identity, immutable source hashes, and typed target lineage; it
    neither parses proof bodies nor proposes a proof strategy.
    """

    question = (
        manifest.get("question", {})
        if isinstance(manifest.get("question", {}), Mapping)
        else {}
    )
    question_id = str(question.get("id", "") or "").strip()
    for diagnostic in diagnostics:
        if (
            _bool_like(
                diagnostic.get("diagnostic_helper_not_source_theorem", False)
            )
            or _bool_like(
                diagnostic.get("support_candidate_not_source_theorem", False)
            )
            or _bool_like(
                diagnostic.get(
                    "target_identity_mismatch_not_source_theorem",
                    False,
                )
            )
            or _bool_like(
                diagnostic.get(
                    "target_identity_unbound_not_source_theorem",
                    False,
                )
            )
            or not _bool_like(
                diagnostic.get(
                    "source_theorem_candidate_evidence_eligible",
                    False,
                )
            )
        ):
            continue

        formal_target_role, formal_target_role_source = (
            _formalizer_candidate_formal_target_role(diagnostic)
        )
        if (
            formal_target_role
            != FORMAL_TARGET_ROLE_SOURCE_THEOREM_CANDIDATE
            or str(diagnostic.get("source_field", "") or "").strip()
            != "formal_targets"
            or _bool_like(
                diagnostic.get(
                    "formal_target_role_unbound_not_source_theorem",
                    False,
                )
            )
        ):
            continue

        provenance = (
            dict(diagnostic.get("source_theorem_target_provenance", {}) or {})
            if isinstance(
                diagnostic.get("source_theorem_target_provenance", {}),
                Mapping,
            )
            else {}
        )
        target_known = _source_theorem_target_known_value(diagnostic)
        if target_known is None:
            target_known = _source_theorem_target_known_value(provenance)
        if target_known is None:
            continue

        target_declaration = str(
            diagnostic.get("actual_target_lean_declaration", "")
            or diagnostic.get("target_lean_declaration", "")
            or ""
        ).strip()
        expected_declaration = str(
            diagnostic.get("expected_target_lean_declaration", "")
            or target_declaration
        ).strip()
        target_ids = tuple(
            dict.fromkeys(
                str(value).strip()
                for value in diagnostic.get("target_ids", []) or []
                if str(value).strip()
            )
        )
        artifact_path_text = str(
            diagnostic.get("artifact_path", "") or ""
        ).strip()
        expected_source_hash = str(
            diagnostic.get("source_hash", "") or ""
        ).strip()
        identity_errors = tuple(
            str(value).strip()
            for value in diagnostic.get("target_identity_errors", []) or []
            if str(value).strip()
        )
        if (
            not target_declaration
            or not expected_declaration
            or expected_declaration != target_declaration
            or not target_ids
            or not artifact_path_text
            or not expected_source_hash
            or identity_errors
        ):
            continue
        if (
            _bool_like(diagnostic.get("repair_target_identity_required", False))
            and str(
                diagnostic.get("repair_target_identity_binding_status", "")
                or ""
            )
            != "BOUND"
        ):
            continue

        artifact_path = Path(artifact_path_text).expanduser()
        try:
            source = artifact_path.read_text(encoding="utf-8")
        except OSError:
            continue
        if stable_hash(source) != expected_source_hash:
            continue

        lineage_seed = {
            "manifest_id": str(manifest.get("manifest_id", "") or ""),
            "task_id": str(manifest.get("task_id", "") or ""),
            "question_id": question_id,
            "candidate_id": str(diagnostic.get("candidate_id", "") or ""),
            "source_hash": expected_source_hash,
            "target_lean_declaration": target_declaration,
            "target_ids": list(target_ids),
        }
        source_work_order_id = (
            "runtime_formalizer_candidate_work_order:"
            + stable_hash(lineage_seed)[:20]
        )
        execution_queue_id = (
            "runtime_formalizer_candidate_proof_search_queue:"
            + stable_hash([lineage_seed, source_work_order_id])[:20]
        )
        provenance.update(
            {
                "source_theorem_target_known": target_known is True,
                "formal_target_role": formal_target_role,
                "target_lean_declaration": target_declaration,
                "target_ids": list(target_ids),
                "source_work_order_id": source_work_order_id,
                "execution_queue_id": execution_queue_id,
            }
        )
        if question_id:
            provenance["source_theorem_question_id"] = question_id

        def string_tuple(value: Any) -> tuple[str, ...]:
            values = value if isinstance(value, (list, tuple, set)) else [value]
            return tuple(
                dict.fromkeys(
                    str(item).strip()
                    for item in values
                    if str(item or "").strip()
                )
            )

        compiler_diagnostics = string_tuple(
            [
                *(diagnostic.get("precheck_errors", []) or []),
                diagnostic.get("local_lean_stdout_excerpt", ""),
                diagnostic.get("local_lean_stderr_excerpt", ""),
            ]
        )
        exit_status = str(
            diagnostic.get("local_lean_exit_status", "") or ""
        ).strip()
        try:
            compiler_returncode = int(exit_status)
        except ValueError:
            compiler_returncode = -1
        target_statement = str(
            diagnostic.get("target_theorem_statement", "") or source
        )
        lineage_payload = {
            "source_work_order_id": source_work_order_id,
            "execution_queue_id": execution_queue_id,
            "lineage_candidate_artifact_path": artifact_path_text,
            "lineage_candidate_artifact_hash": expected_source_hash,
            "target_declaration_source_hash": expected_source_hash,
            "target_theorem_statement_hash": (
                _external_exact_target_statement_hash(target_statement)
            ),
            "target_theorem_statement_hash_algorithm": (
                EXACT_TARGET_STATEMENT_HASH_ALGORITHM
            ),
            "expected_target_lean_declaration": expected_declaration,
            "target_lean_declaration": target_declaration,
            "target_ids": list(target_ids),
        }
        context = {
            "context_kind": "model_owned_complete_lean_candidate",
            "target_lean_declaration": target_declaration,
            "target_ids": list(target_ids),
            "source_theorem_target_known": target_known is True,
            "source_theorem_target_identity_status": (
                "SOURCE_THEOREM_TARGET_KNOWN"
                if target_known is True
                else "GENERATED_FORMAL_TARGET_PENDING_SEMANTIC_REVIEW"
            ),
            "source_theorem_target_provenance": provenance,
            **lineage_payload,
            "source_lineage_id": _external_exact_source_lineage_id(
                lineage_payload
            ),
            "target_identity_status": "TARGET_DECLARATION_MATCHED",
            "target_identity_errors": list(identity_errors),
            "target_identity_source": (
                "runtime_formalizer_candidate_artifact_and_target_binding"
            ),
            "source_theorem_kernel_evidence_eligible": False,
            "candidate_artifact_path": artifact_path_text,
            "source_candidate_artifact_path": artifact_path_text,
            "candidate_source": source,
            "target_theorem_statement": target_statement,
            "semantic_alignment_constraints": list(
                string_tuple(
                    provenance.get("semantic_alignment_constraints", [])
                )
            ),
            "semantic_alignment_blockers": list(
                string_tuple(provenance.get("semantic_alignment_blockers", []))
            ),
            "compiler_feedback": {
                "provider": "configured_local_lean_or_lsp",
                "checked": _bool_like(
                    diagnostic.get("local_lean_attempted", False)
                ),
                "returncode": compiler_returncode,
                "diagnostics": list(compiler_diagnostics),
                "candidate_artifact_hash": expected_source_hash,
            },
            "proof_evidence_status": (
                "MODEL_OWNED_COMPLETE_LEAN_CANDIDATE_NOT_PROOF_EVIDENCE"
            ),
        }
        return {
            **context,
            "formal_target_role": formal_target_role,
            "formal_target_role_source": formal_target_role_source,
            "formalizer_candidate_exact_search_eligible": True,
            "external_proof_search_dispatch_eligible": False,
            "external_proof_search_dispatch_blockers": [
                "Independent whole-target semantic review must accept this exact "
                "hash-bound statement before external prover search."
            ],
            "formalizer_candidate_semantic_review_status": (
                "INDEPENDENT_SEMANTIC_FAITHFULNESS_REVIEW_REQUIRED"
            ),
            "source_theorem_promotion_blockers": [
                "A Formalizer-generated declaration requires independent semantic "
                "faithfulness review before it can be promoted as the source theorem."
            ],
        }
    return {}


def _formalizer_compiled_exact_candidate_semantic_review_feedback(
    manifest: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Bind an already-compiling exact candidate to whole-target review.

    Local Lean establishes only that the generated artifact compiles. The same
    immutable target must still pass independent mathematical review before it
    can enter source-theorem proof promotion or external prover search.
    """

    compiled_exact_rows = [
        dict(row)
        for row in manifest.get("candidate_rows", []) or []
        if isinstance(row, Mapping)
        and _bool_like(row.get("local_lean_compiled", False))
        and _bool_like(
            row.get("source_theorem_candidate_evidence_eligible", False)
        )
        and not _bool_like(
            row.get("diagnostic_helper_not_source_theorem", False)
        )
        and not _bool_like(row.get("support_candidate_not_source_theorem", False))
    ]
    if not compiled_exact_rows:
        return None
    context = _formalizer_candidate_exact_proof_search_context(
        manifest=manifest,
        diagnostics=compiled_exact_rows,
    )
    if not context:
        return None
    for runtime_authored_strategy_field in (
        "owner_subsystem",
        "repair_scope",
        "required_behavior",
        "acceptance_gate",
        "proof_body_generation_contract",
        "proof_search_role",
    ):
        context.pop(runtime_authored_strategy_field, None)
    context["external_proof_search_dispatch_eligible"] = False
    context["external_proof_search_dispatch_blockers"] = [
        "The exact candidate compiles, but independent whole-target semantic "
        "review must accept its mathematical meaning before prover search or "
        "source-theorem promotion."
    ]
    return {
        "feedback_type": "formal_target_semantic_review_required_feedback",
        "failure_classification": (
            "formal_target_semantic_review_required_before_proof_search"
        ),
        "source_manifest_id": str(manifest.get("manifest_id", "") or ""),
        "proofengineer_repair_context": context,
        "required_review": (
            "Independently compare the exact theorem statement and full Lean "
            "source with the question, TheoryDeveloper derivation, assumptions, "
            "quantifiers, conclusion, and semantic constraints."
        ),
        "proof_evidence_status": (
            "COMPILED_FORMAL_TARGET_REQUIRES_SEMANTIC_REVIEW_NOT_SOURCE_PROOF"
        ),
        "proof_evidence_boundary": FORMAL_TARGET_SEMANTIC_REVIEW_BOUNDARY,
    }


def _formalizer_environment_feedback_with_formal_source_grounding(
    feedback: Mapping[str, Any] | None,
    *,
    formal_source_retriever: Any | None = None,
) -> dict[str, Any]:
    """Attach bounded formal-source grounding to carried repair feedback."""

    payload = dict(feedback) if isinstance(feedback, Mapping) else {}
    payload = (
        _formalizer_environment_feedback_with_refreshed_validation_feedback(
            payload
        )
    )
    repair_context = (
        payload.get("proofengineer_repair_context", {})
        if isinstance(payload.get("proofengineer_repair_context", {}), Mapping)
        else {}
    )
    planner_action_work_order = (
        payload.get("formalization_gap_planner_action_work_order", {})
        if isinstance(
            payload.get("formalization_gap_planner_action_work_order", {}),
            Mapping,
        )
        else {}
    )
    if planner_action_work_order:
        repair_context = (
            _proofengineer_repair_context_with_planner_action_search_requests(
                repair_context,
                work_order=planner_action_work_order,
            )
        )
        payload["proofengineer_repair_context"] = repair_context
    if not repair_context:
        return payload
    payload["proofengineer_repair_context"] = (
        _proofengineer_repair_context_with_formal_source_grounding(
            repair_context,
            formal_source_retriever=formal_source_retriever,
        )
    )
    return payload


def _proofengineer_repair_context_with_planner_action_search_requests(
    context: Mapping[str, Any],
    *,
    work_order: Mapping[str, Any],
) -> dict[str, Any]:
    """Compile validated planner searches into the existing RAG grounding path."""

    payload = dict(context) if isinstance(context, Mapping) else {}
    search_requests = [
        dict(row)
        for row in work_order.get("search_requests", []) or []
        if isinstance(row, Mapping)
    ]
    query_seeds = [
        str(value).strip()
        for value in payload.get("retrieval_query_seeds", []) or []
        if str(value).strip()
    ]
    query_seeds.extend(
        str(row.get("query", "") or "").strip()
        for row in search_requests
        if str(row.get("query", "") or "").strip()
    )
    query_seeds = list(dict.fromkeys(query_seeds))
    if not query_seeds:
        return payload

    payload.setdefault(
        "context_kind",
        "formalization_gap_planner_action_execution",
    )
    payload.setdefault("owner_subsystem", "ProofEngineer")
    payload["planner_action_work_order_id"] = str(
        work_order.get("work_order_id", "") or ""
    )
    payload["retrieval_query_seeds"] = query_seeds
    payload["planner_search_requests"] = search_requests
    payload["planner_search_request_status"] = (
        "BOUND_TO_FORMAL_SOURCE_RETRIEVAL_NOT_PROOF_EVIDENCE"
    )
    return payload


def _formalizer_environment_feedback_with_refreshed_validation_feedback(
    feedback: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Keep exact validator observations available on carried pending tasks."""

    payload = dict(feedback) if isinstance(feedback, Mapping) else {}
    validation_errors = _feedback_text_values(payload.get("validation_errors", []))
    if not validation_errors:
        return payload
    existing = payload.get("formalizer_validation_feedback", {})
    if (
        isinstance(existing, Mapping)
        and list(existing.get("validation_error_messages", []) or [])
        == validation_errors
    ):
        return payload
    payload["formalizer_validation_feedback"] = (
        formalizer_validation_feedback_envelope(
            validation_errors,
            validation_label=str(payload.get("validation_label", "") or ""),
            retry_depth=int(
                payload.get("formalizer_packet_repair_retry_depth", 0) or 0
            ),
        )
    )
    return payload


def _feedback_text_values(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value] if value.strip() else []
    if isinstance(value, Mapping):
        return [json.dumps(value, sort_keys=True, default=str)]
    if isinstance(value, Iterable):
        return [str(item) for item in value if str(item).strip()]
    text = str(value)
    return [text] if text.strip() else []


def _formalizer_environment_feedback_formal_source_grounding_summary(
    feedback: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Summarize prompt-time formal-source grounding without serializing prompts."""

    if not isinstance(feedback, Mapping):
        return {}
    repair_context = feedback.get("proofengineer_repair_context", {})
    if not isinstance(repair_context, Mapping):
        return {}
    groups = [
        group
        for group in repair_context.get("formal_source_grounding_hits", []) or []
        if isinstance(group, Mapping)
    ]
    if not groups:
        return {}
    top_hit_names: list[str] = []
    n_hits = 0
    for group in groups:
        hits = [hit for hit in group.get("hits", []) or [] if isinstance(hit, Mapping)]
        n_hits += len(hits)
        for hit in hits:
            name = str(hit.get("name", "") or "").strip()
            if name and name not in top_hit_names:
                top_hit_names.append(name)
            if len(top_hit_names) >= 8:
                break
        if len(top_hit_names) >= 8:
            break
    return {
        "n_formal_source_grounding_query_groups": len(groups),
        "n_formal_source_grounding_hits": n_hits,
        "n_duplicate_formal_source_grounding_hits_omitted": sum(
            int(group.get("duplicate_hits_omitted", 0) or 0)
            for group in groups
        ),
        "query_roles": [
            str(group.get("query_role", "") or "")
            for group in groups[:5]
            if str(group.get("query_role", "") or "")
        ],
        "query_fingerprints": [
            str(group.get("query_fingerprint", "") or "")
            for group in groups[:5]
            if str(group.get("query_fingerprint", "") or "")
        ],
        "unknown_identifiers": [
            str(group.get("unknown_identifier", "") or "")
            for group in groups[:5]
            if str(group.get("unknown_identifier", "") or "")
        ],
        "top_hit_names": top_hit_names,
        "proof_evidence_status": (
            "FORMAL_SOURCE_RETRIEVAL_GROUNDING_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }


def _proofengineer_repair_context_with_formal_source_grounding(
    context: Mapping[str, Any],
    *,
    formal_source_retriever: Any | None = None,
) -> dict[str, Any]:
    """Run model/task-selected formal-source queries without treating hits as proof."""

    payload = dict(context) if isinstance(context, Mapping) else {}
    query_seeds = [
        str(seed).strip()
        for seed in payload.get("retrieval_query_seeds", []) or []
        if str(seed).strip()
    ]
    source_scope_ids = _proofengineer_formal_source_scope_ids(payload)
    if (
        not source_scope_ids
        and str(payload.get("context_kind", "") or "")
        == "task_bound_formal_source_grounding"
    ):
        source_scope_ids = (
            active_project_formal_source_scope_ids(
                getattr(
                    formal_source_retriever,
                    "lean_rag_source_topology",
                    (),
                )
            )
        )
        if source_scope_ids:
            payload["formal_source_scope_ids"] = list(source_scope_ids)
            payload["formal_source_scope_origin"] = (
                "retriever_active_project_topology_default"
            )
            payload["formal_source_scope_policy"] = (
                "active_project_plus_declared_dependencies_first"
            )
    semantic_query_role = (
        "initial_formalization_context"
        if str(payload.get("context_kind", "") or "")
        == "task_bound_formal_source_grounding"
        else "model_or_task_selected_query"
    )
    query_rows = _proofengineer_formal_source_query_rows(
        query_seeds=query_seeds,
        semantic_query_role=semantic_query_role,
    )
    existing_groups = [
        dict(group)
        for group in payload.get("formal_source_grounding_hits", []) or []
        if isinstance(group, Mapping)
    ]
    existing_groups_are_current = (
        existing_groups
        and _proofengineer_formal_source_grounding_matches_query_rows(
            existing_groups,
            query_rows=query_rows,
            source_scope_ids=source_scope_ids,
        )
    )
    if existing_groups and existing_groups_are_current:
        grounded = _proofengineer_repair_context_ordered_with_formal_source_grounding(
            payload,
            immediate_fields={"formal_source_grounding_hits": existing_groups},
        )
        return attach_ai4slt_proof_state_trace_rag(
            grounded,
            formal_source_retriever=formal_source_retriever,
        )
    if formal_source_retriever is None:
        if existing_groups and query_rows:
            payload.pop("formal_source_grounding_hits", None)
            payload["formal_source_grounding_status"] = (
                "stale_hits_removed_retriever_unavailable"
            )
        return attach_ai4slt_proof_state_trace_rag(payload)
    groups = _proofengineer_formal_source_grounding_hit_groups(
        formal_source_retriever,
        query_seeds=query_seeds,
        source_scope_ids=source_scope_ids,
        semantic_query_role=semantic_query_role,
    )
    if not groups:
        return attach_ai4slt_proof_state_trace_rag(
            payload,
            formal_source_retriever=formal_source_retriever,
        )
    trailing_fields: dict[str, Any] = {}
    trailing_fields["formal_source_grounding_policy"] = (
        "Formal-source retrieval hits are API/premise suggestions for the "
        "ProofEngineer loop, not proof evidence. Every selected declaration or "
        "replacement must still be checked by the configured local Lean/AXLE gate; "
        "if no verified replacement exists, emit a FORMAL_GAP naming the missing "
        "API/dependency."
    )
    trailing_fields["formal_source_grounding_status"] = (
        "retrieved_hits"
        if any(group.get("hits") for group in groups)
        else "retrieval_attempted_no_hits"
    )
    grounded = _proofengineer_repair_context_ordered_with_formal_source_grounding(
        payload,
        immediate_fields={"formal_source_grounding_hits": groups},
        trailing_fields=trailing_fields,
    )
    return attach_ai4slt_proof_state_trace_rag(
        grounded,
        formal_source_retriever=formal_source_retriever,
    )


def _proofengineer_repair_context_ordered_with_formal_source_grounding(
    context: Mapping[str, Any],
    *,
    immediate_fields: Mapping[str, Any],
    trailing_fields: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Keep compact prompt-visible grounding next to retrieval query seeds."""

    trailing_fields = trailing_fields or {}
    insert_after_key = "retrieval_query_seeds"
    ordered: dict[str, Any] = {}
    inserted = False
    grounding_keys = set(immediate_fields) | set(trailing_fields)
    for key, value in context.items():
        if key in grounding_keys:
            continue
        ordered[key] = value
        if key == insert_after_key:
            ordered.update(dict(immediate_fields))
            inserted = True
    if not inserted:
        ordered.update(dict(immediate_fields))
    ordered.update(dict(trailing_fields))
    return ordered


def _proofengineer_formal_source_grounding_hit_groups(
    formal_source_retriever: Any,
    *,
    query_seeds: Sequence[str],
    source_scope_ids: Sequence[str] = (),
    semantic_query_role: str = "model_or_task_selected_query",
    k: int = 2,
    max_groups: int = 3,
) -> list[dict[str, Any]]:
    query_rows = _proofengineer_formal_source_query_rows(
        query_seeds=query_seeds,
        semantic_query_role=semantic_query_role,
    )
    groups: list[dict[str, Any]] = []
    seen_queries: set[str] = set()
    seen_hit_keys: set[tuple[str, str, str, str]] = set()
    normalized_source_scopes = tuple(
        dict.fromkeys(
            str(value).strip()
            for value in source_scope_ids
            if str(value).strip()
        )
    )
    for row in query_rows:
        query = str(row.get("query", "") or "").strip()
        if not query or query in seen_queries:
            continue
        seen_queries.add(query)
        group: dict[str, Any] = {
            "query": query,
            "query_role": row.get("query_role", ""),
            "query_fingerprint": stable_hash(query),
            "proof_evidence_status": (
                "FORMAL_SOURCE_RETRIEVAL_GROUNDING_NOT_PROOF_EVIDENCE"
            ),
            "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
        }
        if row.get("unknown_identifier"):
            group["unknown_identifier"] = row["unknown_identifier"]
        if normalized_source_scopes:
            group["source_scope_ids"] = list(normalized_source_scopes)
            group["source_scope_semantics"] = (
                "main_retrieval_allowlist_with_anchor_scoped_support_corpora"
            )
        try:
            scoped_search = getattr(
                formal_source_retriever,
                "search_with_source_scope",
                None,
            )
            if normalized_source_scopes and callable(scoped_search):
                hits = scoped_search(
                    query,
                    source_scope_ids=normalized_source_scopes,
                    k=k,
                )
            else:
                hits = formal_source_retriever.search(query, k=k)
                if normalized_source_scopes:
                    raw_hits = list(hits)
                    allowed_source_ids = set(normalized_source_scopes)
                    hits = [
                        hit
                        for hit in raw_hits
                        if str(
                            getattr(
                                getattr(hit, "declaration", None),
                                "source_id",
                                "",
                            )
                            or ""
                        )
                        in allowed_source_ids
                    ]
                    group["source_scope_enforcement"] = (
                        "runtime_unscoped_fallback_filtered_by_source_allowlist"
                    )
                    group["n_out_of_scope_hits_dropped"] = (
                        len(raw_hits) - len(hits)
                    )
        except Exception as exc:  # pragma: no cover - defensive runtime path
            group["hits"] = []
            group["retrieval_error"] = type(exc).__name__ + ": " + str(exc)[:240]
        else:
            context_hit_limit = 2 if normalized_source_scopes else 1
            unique_hits, duplicate_hit_count = unique_formal_source_hit_payloads(
                [
                    _formal_source_hit_to_json(
                        hit,
                        formal_source_retriever=(
                            formal_source_retriever
                            if index < context_hit_limit
                            else None
                        ),
                    )
                    for index, hit in enumerate(hits)
                ],
                seen_hit_keys=seen_hit_keys,
            )
            group["hits"] = unique_hits
            if duplicate_hit_count:
                group["duplicate_hits_omitted"] = duplicate_hit_count
        groups.append(group)
        if len(groups) >= max_groups:
            break
    return groups


def _proofengineer_formal_source_query_rows(
    *,
    query_seeds: Sequence[str],
    semantic_query_role: str = "model_or_task_selected_query",
) -> list[dict[str, str]]:
    """Preserve model/task-selected query strings and their order exactly."""

    rows = [
        {
            "query": str(seed).strip(),
            "query_role": str(semantic_query_role).strip()
            or "model_or_task_selected_query",
            "unknown_identifier": "",
        }
        for seed in query_seeds
        if str(seed).strip()
    ]
    unique_rows: list[dict[str, str]] = []
    seen_queries: set[str] = set()
    for row in rows:
        query = row["query"]
        if query in seen_queries:
            continue
        seen_queries.add(query)
        unique_rows.append(row)
    return unique_rows


def _proofengineer_formal_source_grounding_matches_query_rows(
    groups: Sequence[Mapping[str, Any]],
    *,
    query_rows: Sequence[Mapping[str, Any]],
    source_scope_ids: Sequence[str],
    max_groups: int = 3,
) -> bool:
    """Reject carried declaration hits when the live Lean query has changed."""

    expected_rows = list(query_rows[: max(0, int(max_groups))])
    if not expected_rows:
        return True
    observed_rows = list(groups[: len(expected_rows)])
    if len(observed_rows) != len(expected_rows):
        return False
    expected_scopes = tuple(
        dict.fromkeys(
            str(value).strip()
            for value in source_scope_ids
            if str(value).strip()
        )
    )
    for observed, expected in zip(observed_rows, expected_rows, strict=True):
        query = str(expected.get("query", "") or "").strip()
        if str(observed.get("query_fingerprint", "") or "") != stable_hash(query):
            return False
        if str(observed.get("query_role", "") or "") != str(
            expected.get("query_role", "") or ""
        ):
            return False
        observed_scopes = tuple(
            str(value).strip()
            for value in observed.get("source_scope_ids", []) or []
            if str(value).strip()
        )
        if observed_scopes != expected_scopes:
            return False
    return True


def _proofengineer_formal_source_scope_ids(
    context: Mapping[str, Any],
) -> tuple[str, ...]:
    raw_scopes = context.get("formal_source_scope_ids", []) or []
    if isinstance(raw_scopes, str):
        raw_scopes = [raw_scopes]
    discovered: list[str] = [
        str(value).strip()
        for value in raw_scopes
        if str(value).strip()
    ]
    provenance_rows: list[Mapping[str, Any]] = []
    direct_provenance = context.get("source_theorem_target_provenance", {})
    if isinstance(direct_provenance, Mapping):
        provenance_rows.append(direct_provenance)
    for candidate in context.get("candidate_rerun_specs", []) or []:
        if not isinstance(candidate, Mapping):
            continue
        provenance = candidate.get("source_theorem_target_provenance", {})
        if isinstance(provenance, Mapping):
            provenance_rows.append(provenance)
    for provenance in provenance_rows:
        for key in ("source_id", "corpus_id", "formal_source_scope_id"):
            candidate = str(provenance.get(key, "") or "").strip()
            if candidate:
                discovered.append(candidate)
    return tuple(dict.fromkeys(discovered))


def _formalizer_lean_candidate_proof_state_subclaims(
    manifest: Mapping[str, Any],
    feedback: Mapping[str, Any],
) -> list[FormalSubclaim]:
    """Represent failed Formalizer Lean candidates as proof-state work items."""

    rows: list[FormalSubclaim] = []
    manifest_candidates: dict[str, Mapping[str, Any]] = {}
    manifest_candidate_rows = [
        candidate
        for candidate in manifest.get("candidate_rows", []) or []
        if isinstance(candidate, Mapping)
    ]
    for candidate in manifest_candidate_rows:
        candidate_key = str(candidate.get("candidate_id", "") or "").strip()
        if candidate_key:
            manifest_candidates.setdefault(candidate_key, candidate)
    diagnostics = [
        row
        for row in feedback.get("candidate_diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    for index, row in enumerate(diagnostics, start=1):
        candidate_id = str(row.get("candidate_id", "") or f"candidate_{index}")
        manifest_candidate = manifest_candidates.get(candidate_id, {})
        if not manifest_candidate and len(manifest_candidate_rows) == 1:
            manifest_candidate = manifest_candidate_rows[0]
        kernel_artifact_path = str(
            row.get("kernel_check_artifact_path", "")
            or manifest_candidate.get("kernel_check_artifact_path", "")
            or row.get("artifact_path", "")
            or manifest_candidate.get("artifact_path", "")
            or ""
        )
        artifact_path = str(
            row.get("proof_state_artifact_path", "")
            or manifest_candidate.get("proof_state_artifact_path", "")
            or row.get("target_lean_file", "")
            or manifest_candidate.get("target_lean_file", "")
            or kernel_artifact_path
        )
        lean_statement = str(
            row.get("lean_source_excerpt", "")
            or manifest_candidate.get("lean_source_excerpt", "")
            or ""
        )
        if artifact_path:
            try:
                path = Path(artifact_path)
                if path.exists():
                    lean_statement = path.read_text(encoding="utf-8")[:8000]
            except OSError:
                pass
        error_rows = [
            str(error)
            for error in row.get("precheck_errors", []) or []
            if str(error).strip()
        ]
        for key in ("local_lean_exit_status", "local_lean_stdout_excerpt", "local_lean_stderr_excerpt"):
            value = str(row.get(key, "") or "").strip()
            if value:
                error_rows.append(value[:500])
        local_lean_compiled = bool(
            row.get(
                "local_lean_compiled",
                manifest_candidate.get("local_lean_compiled", False),
            )
        )
        rows.append(
            FormalSubclaim(
                id="formalizer_lean_candidate:" + _safe_identifier(candidate_id),
                title="Formalizer Lean candidate proof-state repair: " + candidate_id,
                status="PROVED" if local_lean_compiled else "FAILED",
                claim=(
                    "Repair materialized Formalizer Lean candidate "
                    f"{candidate_id} from manifest {manifest.get('manifest_id', '')}"
                ),
                claim_type="lean_obligation",
                proof_obligation_id=candidate_id,
                lean_statement=lean_statement,
                formalization_status=(
                    "candidate_live_prover_inspection_requested"
                    if local_lean_compiled
                    else "candidate_needs_proofengineer_repair"
                ),
                verifier="ProofEngineerCandidateProofStateFeedback",
                verification_strength="diagnostic_only",
                kernel_verified=local_lean_compiled,
                errors=error_rows[:6],
                gap_reason=str(feedback.get("failure_classification", "") or ""),
                artifact_path=artifact_path or None,
                proof_dependencies=tuple(
                    str(seed)
                    for seed in (
                        feedback.get("proofengineer_repair_context", {})
                        if isinstance(
                            feedback.get("proofengineer_repair_context", {}),
                            Mapping,
                        )
                        else {}
                    ).get("retrieval_query_seeds", [])
                    or []
                    if str(seed).strip()
                ),
            )
        )
    return rows


def _formalizer_lean_candidate_live_prover_inspection_feedback(
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    """Build diagnostic feedback for LSP-ready candidates that need live inspection."""

    diagnostics: list[dict[str, Any]] = []
    for index, candidate in enumerate(
        manifest.get("candidate_rows", []) or [],
        start=1,
    ):
        if not isinstance(candidate, Mapping):
            continue
        live_request = (
            candidate.get("live_proof_state_request", {})
            if isinstance(candidate.get("live_proof_state_request", {}), Mapping)
            else {}
        )
        provider_preferences = tuple(
            str(value)
            for value in live_request.get("provider_preferences", ()) or ()
        )
        if "lean_lsp_mcp" not in provider_preferences:
            continue
        artifact_path = str(
            candidate.get("proof_state_artifact_path", "")
            or candidate.get("target_lean_file", "")
            or candidate.get("kernel_check_artifact_path", "")
            or candidate.get("artifact_path", "")
            or ""
        )
        if not artifact_path:
            continue
        diagnostics.append(
            {
                "candidate_id": str(
                    candidate.get("candidate_id", "") or f"candidate_{index}"
                ),
                "candidate_kind": str(candidate.get("candidate_kind", "") or ""),
                "source_field": str(candidate.get("source_field", "") or ""),
                "source_hash": str(candidate.get("source_hash", "") or ""),
                "artifact_path": str(candidate.get("artifact_path", "") or ""),
                "kernel_check_artifact_path": str(
                    candidate.get("kernel_check_artifact_path", "")
                    or candidate.get("artifact_path", "")
                    or ""
                ),
                "proof_state_artifact_path": artifact_path,
                "target_lean_file": str(
                    candidate.get("target_lean_file", "") or artifact_path
                ),
                "target_lean_line": int(candidate.get("target_lean_line", 0) or 0),
                "target_lean_column": int(
                    candidate.get("target_lean_column", 0) or 0
                ),
                "target_lean_declaration": str(
                    candidate.get("target_lean_declaration", "") or ""
                ),
                "lean_source": str(
                    candidate.get("lean_source", "")
                    or candidate.get("lean_source_excerpt", "")
                    or ""
                ),
                "lean_source_excerpt": str(
                    candidate.get("lean_source", "")
                    or candidate.get("lean_source_excerpt", "")
                    or ""
                ),
                "precheck_status": str(candidate.get("precheck_status", "") or ""),
                "precheck_errors": list(candidate.get("precheck_errors", []) or []),
                "local_lean_attempted": bool(
                    candidate.get("local_lean_attempted", False)
                ),
                "local_lean_compiled": bool(
                    candidate.get("local_lean_compiled", False)
                ),
                "local_lean_exit_status": str(
                    candidate.get("local_lean_exit_status", "") or ""
                ),
                "local_lean_stdout": str(
                    candidate.get("local_lean_stdout", "") or ""
                ),
                "local_lean_stderr": str(
                    candidate.get("local_lean_stderr", "") or ""
                ),
                "local_lean_stdout_excerpt": str(
                    candidate.get("local_lean_stdout", "") or ""
                ),
                "local_lean_stderr_excerpt": str(
                    candidate.get("local_lean_stderr", "") or ""
                ),
            }
        )
    return {
        "feedback_type": "formalizer_lean_candidate_live_prover_inspection",
        "failure_classification": "formalizer_live_prover_inspection_requested",
        "candidate_diagnostics": diagnostics,
        "proofengineer_repair_context": {
            "candidate_artifact_paths": [
                row["proof_state_artifact_path"] for row in diagnostics
            ],
            "available_observation_types": (
                "lean_diagnostic_messages",
                "lean_goal",
                "lean_state_search",
                "lean_multi_attempt",
                "local_lean_or_axle_rerun",
            ),
            "model_selects_tool_order": True,
            "boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
        },
        "proof_evidence_status": (
            "FORMALIZER_LEAN_CANDIDATE_LIVE_PROVER_INSPECTION_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
    }


def _formalizer_local_lean_observation_from_diagnostics(
    diagnostics: list[dict[str, Any]],
) -> dict[str, Any]:
    """Carry failed Lean tool observations without deriving a source strategy."""

    failed_diagnostics = [
        dict(row)
        for row in diagnostics
        if _formalizer_diagnostic_row_requires_feedback(row)
    ]
    if not failed_diagnostics:
        return {}
    diagnostic_classes: list[str] = []
    for row in failed_diagnostics:
        for key in ("local_lean_diagnostic_classes", "diagnostic_classes"):
            for value in row.get(key, []) or []:
                text = str(value).strip()
                if text and text not in diagnostic_classes:
                    diagnostic_classes.append(text)
        for diagnostic in row.get("diagnostics", []) or []:
            if not isinstance(diagnostic, Mapping):
                continue
            text = str(
                diagnostic.get("code", "")
                or diagnostic.get("class", "")
                or diagnostic.get("kind", "")
            ).strip()
            if text and text not in diagnostic_classes:
                diagnostic_classes.append(text)
    return formalizer_tool_observation_envelope(
        failed_diagnostics,
        tool_name="lean",
        producer="configured_local_lean_or_lsp",
        diagnostic_classes=diagnostic_classes,
    )


def _formalizer_diagnostic_row_requires_feedback(row: Mapping[str, Any]) -> bool:
    """Return true when a diagnostic row represents failed verifier/precheck work."""

    precheck_status = str(row.get("precheck_status", "") or "").strip()
    if precheck_status == "REJECTED_BY_RUNTIME_PRECHECK":
        return True
    if row.get("precheck_errors"):
        return True
    exit_status = str(row.get("local_lean_exit_status", "") or "").strip().lower()
    if exit_status and exit_status not in {"0", "ok", "success"}:
        return True
    if _bool_like(row.get("local_lean_attempted", False)):
        compiled_value = row.get("local_lean_compiled", None)
        if compiled_value is not None and not _bool_like(compiled_value):
            return True
    return False


def _formalizer_declared_lean_imports(row: Mapping[str, Any]) -> list[str]:
    raw_imports = row.get("lean_imports", row.get("target_imports", []))
    if not isinstance(raw_imports, list | tuple):
        return []
    return list(
        dict.fromkeys(
            str(value).strip()
            for value in raw_imports
            if str(value).strip()
        )
    )


def _formalizer_lean_candidate_sources(
    proposal_packet: Mapping[str, Any],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for index, row in enumerate(
        proposal_packet.get("source_to_bridge_premise_derivation_candidates", []) or [],
        start=1,
    ):
        if not isinstance(row, Mapping):
            continue
        source = str(
            row.get("premise_derivation_candidate_lean_source", "")
            or row.get("candidate_lean_source", "")
            or ""
        ).strip()
        if not source:
            continue
        raw_premise_names = row.get("premise_names", [])
        premise_names = [
            str(value).strip()
            for value in raw_premise_names
            if str(value).strip()
        ] if isinstance(raw_premise_names, list | tuple | set) else []
        premise_name = str(row.get("premise_name", "") or "").strip()
        candidate_id = (
            str(row.get("id", "") or "").strip()
            or str(row.get("candidate_request_id", "") or "").strip()
            or str(
                row.get("source_to_bridge_premise_derivation_candidate_request_id", "")
                or ""
            ).strip()
            or "_".join(premise_names)
            or premise_name
            or f"source_to_bridge_premise_candidate_{index}"
        )
        candidate_lean_declaration = str(
            row.get("premise_candidate_declaration_name", "") or ""
        ).strip()
        lean_imports = _formalizer_declared_lean_imports(row)
        rows.append(
            {
                "candidate_id": candidate_id,
                "candidate_kind": "source_to_bridge_premise_derivation_candidate",
                "source_field": "source_to_bridge_premise_derivation_candidates",
                "lean_source": source,
                "lean_imports": lean_imports,
                "candidate_lean_declaration": candidate_lean_declaration,
                "candidate_lean_declaration_source": (
                    "source_to_bridge_premise_derivation_candidates."
                    "premise_candidate_declaration_name"
                ),
                "candidate_metadata": {
                    "premise_name": premise_name,
                    "premise_names": premise_names,
                    "candidate_lean_declaration": candidate_lean_declaration,
                    "lean_imports": lean_imports,
                    "target_theorem_name": str(
                        row.get("target_theorem_name", "") or ""
                    ),
                    "target_lean_declaration": str(
                        row.get("target_lean_declaration", "") or ""
                    ),
                    "adapter_instantiation_group_id": str(
                        row.get("adapter_instantiation_group_id", "") or ""
                    ),
                },
            }
        )
    for index, row in enumerate(proposal_packet.get("formal_targets", []) or [], start=1):
        if not isinstance(row, Mapping):
            continue
        source = str(row.get("lean_statement_sketch", "") or "").strip()
        if not source:
            continue
        expected_status = str(row.get("expected_status", "") or "")
        if expected_status not in {"NEEDS_KERNEL_CHECK", "OPEN"}:
            continue
        if _formalizer_formal_target_should_skip_lean_candidate_materialization(
            row,
        ):
            continue
        candidate_id = (
            str(row.get("id", "") or "").strip()
            or f"formal_target_candidate_{index}"
        )
        provenance = (
            dict(row.get("source_theorem_target_provenance", {}) or {})
            if isinstance(
                row.get("source_theorem_target_provenance", {}),
                Mapping,
            )
            else {}
        )
        candidate_lean_declaration = str(
            row.get("candidate_lean_declaration", "") or ""
        ).strip()
        candidate_lean_declaration_source = (
            "formal_targets.candidate_lean_declaration"
            if candidate_lean_declaration
            else ""
        )
        formal_target_role = str(
            row.get("formal_target_role", "") or ""
        ).strip().upper()
        lean_imports = _formalizer_declared_lean_imports(row)
        if (
            not candidate_lean_declaration
            and _source_theorem_target_known_value(provenance) is True
        ):
            candidate_lean_declaration = str(
                provenance.get("target_lean_declaration", "") or ""
            ).strip()
            if candidate_lean_declaration:
                candidate_lean_declaration_source = (
                    "formal_targets.source_theorem_target_provenance."
                    "target_lean_declaration"
                )
        rows.append(
            {
                "candidate_id": candidate_id,
                "candidate_kind": "formal_target_lean_statement_sketch",
                "source_field": "formal_targets",
                "formal_target_role": formal_target_role,
                "lean_source": source,
                "lean_imports": lean_imports,
                "candidate_lean_declaration": candidate_lean_declaration,
                "candidate_lean_declaration_source": (
                    candidate_lean_declaration_source
                ),
                "candidate_metadata": {
                    "expected_status": expected_status,
                    "formal_target_role": formal_target_role,
                    "candidate_lean_declaration": candidate_lean_declaration,
                    "lean_imports": lean_imports,
                    "informal_source": str(row.get("informal_source", "") or ""),
                    "semantic_alignment_constraints": list(
                        row.get("semantic_alignment_constraints", []) or []
                    )
                    if isinstance(
                        row.get("semantic_alignment_constraints", []),
                        list | tuple | set,
                    )
                    else [],
                    "source_theorem_target_provenance": provenance,
                },
            }
        )
    return rows


def _formalizer_formal_target_should_skip_lean_candidate_materialization(
    row: Mapping[str, Any],
) -> bool:
    route = str(row.get("runtime_materialization_route", "") or "").strip()
    if route == "source_theorem_proof_body_adapter_bridge":
        return True
    return bool(row.get("skip_formalizer_lean_candidate_materialization", False))


def _run_formalizer_lean_candidate_local_check(
    *,
    artifact_path: Path,
    candidate_lean_declaration: str = "",
    lean_project: Path | None,
    lean_timeout: int,
) -> dict[str, Any]:
    return dict(
        run_lean_candidate_identity_probe(
            artifact_path=artifact_path,
            candidate_lean_declaration=candidate_lean_declaration,
            lean_project=lean_project,
            lean_timeout=lean_timeout,
        )
    )


def _runtime_formalizer_lean_candidate_client_tool_revision(
    *,
    proposal_agent: LLMFormalizerProofEngineerAgent,
    question: OpenResearchQuestion,
    task: AgentTask,
    blackboard: BlackboardState,
    theory_packet: Mapping[str, Any],
    environment_feedback: Mapping[str, Any],
    proof_bank_runtime_memory_summary: Mapping[str, Any],
    formal_source_retriever: Any | None,
    lean_candidate_root: Path,
    lean_candidate_local_lean: bool,
    lean_candidate_lean_project: Path | None,
    lean_candidate_lean_timeout: int,
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    """Run a same-context model edit/search/Lean loop for an accepted target."""

    config = getattr(proposal_agent, "config", None)
    provider = getattr(proposal_agent, "provider", None)
    if (
        not lean_candidate_local_lean
        or lean_candidate_lean_project is None
        or not Path(lean_candidate_lean_project).exists()
        or not bool(
            getattr(config, "use_client_tool_lean_candidate_revision", False)
        )
        or not callable(getattr(provider, "generate_client_tool_turn", None))
    ):
        return None
    binding = resolve_accepted_lean_candidate_revision_binding(
        question_id=question.id,
        artifacts=blackboard.artifacts,
        environment_feedback=environment_feedback,
        exact_target_statement_hash=_external_exact_target_statement_hash,
        target_statement_hash_algorithm=EXACT_TARGET_STATEMENT_HASH_ALGORITHM,
    )
    if binding is None:
        return None
    repair_context = binding.repair_context
    materialization_id = binding.materialization_id
    parent_packet_id = binding.parent_packet_id
    parent_packet = binding.parent_packet
    candidate_id = binding.candidate_id
    candidate_declaration = binding.candidate_lean_declaration
    source_field = binding.candidate_source_field
    artifact_path = binding.candidate_artifact_path
    expected_source_hash = binding.candidate_source_hash
    initial_source = binding.initial_source

    revision_root = (
        Path(lean_candidate_root)
        / _safe_identifier(question.id)
        / "client_tool_revision"
        / stable_hash(
            [task.task_id, materialization_id, candidate_id, expected_source_hash]
        )[:12]
    )
    candidate_metadata = binding.candidate_metadata

    def check_candidate(source: str) -> Mapping[str, Any]:
        source_hash = stable_hash(source)
        precheck_errors = _formalizer_lean_candidate_precheck_errors(
            source,
        )
        blocking_errors = _formalizer_lean_candidate_blocking_precheck_errors(
            precheck_errors
        )
        if blocking_errors:
            return {
                "source_hash": source_hash,
                "compiled": False,
                "precheck_errors": precheck_errors,
                "blocking_precheck_errors": blocking_errors,
                "local_lean_attempted": False,
                "local_lean_exit_status": "",
                "local_lean_stdout": "",
                "local_lean_stderr": "",
            }
        revision_root.mkdir(parents=True, exist_ok=True)
        path = revision_root / (
            _safe_identifier(candidate_id) + "_" + source_hash[:12] + ".lean"
        )
        path.write_text(source, encoding="utf-8")
        local_result = _run_formalizer_lean_candidate_local_check(
            artifact_path=path,
            candidate_lean_declaration=candidate_declaration,
            lean_project=Path(lean_candidate_lean_project),
            lean_timeout=lean_candidate_lean_timeout,
        )
        return {
            "source_hash": source_hash,
            "compiled": _bool_like(
                local_result.get("local_lean_compiled", False)
            ),
            "artifact_path": str(path),
            "precheck_errors": precheck_errors,
            "blocking_precheck_errors": blocking_errors,
            "local_lean_attempted": _bool_like(
                local_result.get("local_lean_attempted", False)
            ),
            "local_lean_source_compiled": _bool_like(
                local_result.get("local_lean_source_compiled", False)
            ),
            "local_lean_exit_status": str(
                local_result.get("local_lean_exit_status", "") or ""
            ),
            "local_lean_stdout": str(
                local_result.get("local_lean_stdout", "") or ""
            ),
            "local_lean_stderr": str(
                local_result.get("local_lean_stderr", "") or ""
            ),
            "candidate_identity_lean_checked": _bool_like(
                local_result.get("candidate_identity_lean_checked", False)
            ),
            "candidate_identity_lean_verified": _bool_like(
                local_result.get("candidate_identity_lean_verified", False)
            ),
            "candidate_identity_lean_stdout": str(
                local_result.get("candidate_identity_lean_stdout", "") or ""
            ),
            "candidate_identity_lean_stderr": str(
                local_result.get("candidate_identity_lean_stderr", "") or ""
            ),
            "local_lean_command": list(
                local_result.get("local_lean_command", []) or []
            ),
            "local_lean_project": str(lean_candidate_lean_project),
        }

    source_scope_ids = _proofengineer_formal_source_scope_ids(repair_context)

    def search_formal_environment(query: str, k: int) -> Any:
        if formal_source_retriever is None:
            return {
                "query": query,
                "hits": [],
                "retrieval_status": "formal_source_retriever_unavailable",
            }
        groups = _proofengineer_formal_source_grounding_hit_groups(
            formal_source_retriever,
            query_seeds=(query,),
            source_scope_ids=source_scope_ids,
            semantic_query_role="model_selected_lean_query",
            k=k,
            max_groups=1,
        )
        compact_groups = compact_formal_source_grounding_hits_for_prompt(groups)
        if not compact_groups:
            return {
                "query": query,
                "hits": [],
                "retrieval_status": "no_prompt_safe_formal_source_hits",
            }
        return {
            "query": query,
            **compact_groups[0],
            "retrieval_status": "prompt_safe_signature_hits",
        }

    revised_packet, loop_evidence = (
        proposal_agent.revise_lean_candidate_with_client_tools(
            question=question,
            theory_packet=theory_packet,
            parent_packet=parent_packet,
            candidate_id=candidate_id,
            candidate_source_field=source_field,
            candidate_lean_declaration=candidate_declaration,
            initial_source=initial_source,
            environment_feedback=environment_feedback,
            proof_bank_runtime_memory_summary=(
                proof_bank_runtime_memory_summary
            ),
            check_candidate=check_candidate,
            search_formal_environment=search_formal_environment,
        )
    )
    evidence = {
        **dict(loop_evidence),
        "created_at": datetime.now(timezone.utc).isoformat(),
        "question_id": question.id,
        "task_id": task.task_id,
        "parent_materialization_manifest_id": materialization_id,
        "parent_formalizer_packet_id": parent_packet_id,
        "parent_candidate_artifact_path": str(artifact_path),
        "parent_candidate_source_hash": expected_source_hash,
        "active_lean_project": str(lean_candidate_lean_project),
        "source_scope_ids": list(source_scope_ids),
    }
    evidence["artifact_id"] = (
        "formalizer_lean_candidate_client_tool_loop:"
        + stable_hash(evidence)[:20]
    )
    return revised_packet, evidence


def _formalizer_lean_candidate_precheck_errors(
    source: str,
) -> list[str]:
    text = str(source or "")
    if not text.strip():
        return ["empty Lean candidate source"]
    if len(text) > 20000:
        return ["Lean candidate source exceeds the 20000-character artifact boundary"]
    return []


def _formalizer_lean_candidate_blocking_precheck_errors(
    errors: Sequence[str],
) -> list[str]:
    """Return precheck errors that should prevent diagnostic artifact creation."""

    return [
        str(error)
        for error in errors
        if not _formalizer_lean_candidate_diagnostic_only_precheck_error(error)
    ]


def _formalizer_lean_candidate_diagnostic_only_precheck_error(error: str) -> bool:
    text = str(error or "")
    return bool(
        text.startswith("Lean parser/syntax error:")
        or text.startswith(
            "Lean candidate missing structured candidate_lean_declaration"
        )
        or text.startswith(
            "Lean candidate structured candidate_lean_declaration was not located"
        )
    )




def _source_theorem_target_known_value(provenance: object) -> bool | None:
    if not isinstance(provenance, Mapping):
        return None
    value = provenance.get("source_theorem_target_known")
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "yes", "1"}:
            return True
        if normalized in {"false", "no", "0"}:
            return False
    if isinstance(value, int) and value in {0, 1}:
        return bool(value)
    return None


def _critic_packet_validation_failure_bundle(
    *,
    task: AgentTask,
    question: OpenResearchQuestion,
    retrieval_manifest: Mapping[str, Any],
    theory_packet: Mapping[str, Any],
    simulation_manifest: Mapping[str, Any],
    algorithm_manifest: Mapping[str, Any],
    formalization_manifest: Mapping[str, Any],
    agenda: Sequence[Mapping[str, Any]],
    runtime_observations: Mapping[str, Any],
    exc: PacketValidationError,
) -> tuple[str, dict[str, Any], dict[str, Any], EnvironmentObservation, EvidenceLedgerEntry]:
    validation_errors = [str(error) for error in exc.errors if str(error)]
    failure_id = (
        "critic_validation_failure:"
        + stable_hash(
            [task.task_id, exc.validation_label, validation_errors, exc.history]
        )[:20]
    )
    rejected_candidate = (
        dict(exc.last_invalid_packet)
        if isinstance(exc.last_invalid_packet, Mapping)
        else {}
    )
    input_snapshot = {
        "retrieval_manifest": dict(retrieval_manifest),
        "theory_packet": dict(theory_packet),
        "simulation_manifest": dict(simulation_manifest),
        "algorithm_manifest": dict(algorithm_manifest),
        "formalization_manifest": dict(formalization_manifest),
        "critic_agenda": [
            dict(row) for row in agenda if isinstance(row, Mapping)
        ],
        "runtime_observations": (
            dict(runtime_observations)
            if isinstance(runtime_observations, Mapping)
            else {}
        ),
    }
    feedback = {
        "feedback_type": "critic_packet_validation_feedback",
        "feedback_source": "CriticEvaluator",
        "failure_classification": "critic_packet_validation_failed",
        "validation_label": exc.validation_label,
        "validation_errors": validation_errors,
        "attempts": exc.attempts,
        "last_attempt_summary": exc.history[-1] if exc.history else {},
        "rejected_candidate": rejected_candidate,
        "critic_input_snapshot": input_snapshot,
        "regeneration_contract": {
            "same_model": True,
            "full_packet_required": True,
            "runtime_edits_candidate": False,
        },
        "proof_evidence_status": (
            "CRITIC_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }
    failure_artifact = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeCriticEvaluatorValidationFailure",
        "failure_id": failure_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "question": _question_to_payload(question),
        "task_id": task.task_id,
        "validation_label": exc.validation_label,
        "failure_classification": "critic_packet_validation_failed",
        "validation_errors": validation_errors,
        "llm_json_repair_history": exc.history,
        "rejected_candidate": rejected_candidate,
        "critic_input_snapshot": input_snapshot,
        "learning_rows": [],
        "proof_evidence_status": (
            "CRITIC_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
        ),
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
        "boundary": (
            "This artifact records a rejected CriticEvaluator model packet and "
            "the exact validator observations. The same model must regenerate a "
            "complete packet; runtime does not edit it or choose a worker."
        ),
    }
    observation = EnvironmentObservation(
        observation_type="critic_packet_validation_failure",
        summary="; ".join(validation_errors)[:500],
        payload={
            "failure_id": failure_id,
            "failure_classification": "critic_packet_validation_failed",
            "validation_errors": validation_errors,
            "proof_evidence_status": (
                "CRITIC_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
            ),
        },
    )
    evidence = EvidenceLedgerEntry(
        evidence_id="evidence:" + stable_hash([task.task_id, failure_id])[:20],
        task_id=task.task_id,
        artifact_id=failure_id,
        evidence_type="critic_packet_validation_failure",
        status="VALIDATION_FAILED_RECORDED_NOT_PROOF_EVIDENCE",
        boundary=CRITIC_EVALUATOR_BOUNDARY,
        payload={
            "failure_classification": "critic_packet_validation_failed",
            "validation_errors": validation_errors,
            "attempts": exc.attempts,
            "proof_evidence_status": (
                "CRITIC_PACKET_VALIDATION_FAILURE_NOT_PROOF_EVIDENCE"
            ),
        },
    )
    return failure_id, failure_artifact, feedback, observation, evidence


def _critic_feedback_has_formalizer_packet_validation_escalation(
    feedback: Mapping[str, Any],
) -> bool:
    if not isinstance(feedback, Mapping):
        return False
    escalation = feedback.get("packet_validation_escalation", {})
    if not isinstance(escalation, Mapping):
        return False
    return str(escalation.get("escalation_kind", "") or "") in {
        "formalizer_repeated_packet_validation_loop",
        "formalizer_repeated_syntax_packet_validation_loop",
    }


def _runtime_formalization_gap_planner_bridge_rows_from_blackboard(
    blackboard: BlackboardState,
    *,
    question_id: str = "",
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    normalized_question_id = str(question_id or "").strip()
    for artifact in blackboard.artifacts.values():
        if not (
            isinstance(artifact, Mapping)
            and artifact.get("artifact_kind")
            == "RuntimeFormalizationGapPlannerBridge"
        ):
            continue
        question = artifact.get("question", {})
        artifact_question_id = (
            str(question.get("id", "") or "").strip()
            if isinstance(question, Mapping)
            else ""
        )
        if (
            normalized_question_id
            and artifact_question_id
            and artifact_question_id != normalized_question_id
        ):
            continue
        rows.append(_runtime_formalization_gap_planner_bridge_with_targets(artifact))
    rows.sort(key=lambda row: str(row.get("bridge_id", "") or ""))
    return rows


def _runtime_formalization_gap_planner_task_runtime_learning_rows(
    inputs: Mapping[str, Any],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []

    def extend_rows(raw_rows: Any) -> None:
        if not isinstance(raw_rows, Sequence) or isinstance(
            raw_rows,
            (str, bytes, bytearray),
        ):
            return
        for row in raw_rows:
            if isinstance(row, Mapping):
                rows.append(dict(row))

    def append_environment_feedback_row(raw_row: Mapping[str, Any]) -> None:
        input_summary = (
            raw_row.get("input_summary", {})
            if isinstance(raw_row.get("input_summary", {}), Mapping)
            else {}
        )
        legacy_route_contract_feedback = bool(
            str(raw_row.get("route_planner_contract_feedback_id", "") or "").strip()
        )
        route_revision_overlay_feedback = bool(
            str(
                raw_row.get("route_revision_overlay_dir", "")
                or input_summary.get("route_revision_overlay_dir", "")
                or raw_row.get("route_revision_overlay_manifest", "")
                or input_summary.get("route_revision_overlay_manifest", "")
                or ""
            ).strip()
        )
        if legacy_route_contract_feedback or route_revision_overlay_feedback or (
            _runtime_learning_memory_row_is_formal_gap_next_action_routing(
                raw_row,
                input_summary,
            )
        ):
            rows.append(dict(raw_row))

    runtime_learning_memory = inputs.get("runtime_learning_memory", {})
    if isinstance(runtime_learning_memory, Mapping):
        extend_rows(runtime_learning_memory.get("rows", []))
    architect_context = inputs.get("architect_context", {})
    if isinstance(architect_context, Mapping):
        architect_runtime_learning_memory = architect_context.get(
            "runtime_learning_memory",
            {},
        )
        if isinstance(architect_runtime_learning_memory, Mapping):
            extend_rows(architect_runtime_learning_memory.get("rows", []))
    environment_feedback = inputs.get("environment_feedback", {})
    if isinstance(environment_feedback, Mapping):
        append_environment_feedback_row(environment_feedback)
        for row in environment_feedback.get("high_priority_agenda", []) or []:
            if isinstance(row, Mapping):
                append_environment_feedback_row(row)

    deduped_rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        key = (
            str(row.get("route_planner_contract_feedback_id", "") or "").strip()
            or stable_hash(row)
        )
        if key in seen:
            continue
        seen.add(key)
        deduped_rows.append(dict(row))
    return deduped_rows


def _runtime_formalization_gap_planner_followup_architect_context(
    inputs: Mapping[str, Any],
    runtime_learning_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    architect_context = (
        dict(inputs.get("architect_context", {}))
        if isinstance(inputs.get("architect_context", {}), Mapping)
        else {}
    )
    rows = [dict(row) for row in runtime_learning_rows if isinstance(row, Mapping)]
    if not rows:
        return architect_context
    existing_memory = (
        architect_context.get("runtime_learning_memory", {})
        if isinstance(architect_context.get("runtime_learning_memory", {}), Mapping)
        else {}
    )
    row_limit = _runtime_learning_memory_context_row_limit(
        architect_context,
        existing_memory,
        default=max(20, len(rows)),
    )
    memory_context = _runtime_learning_memory_context_from_rows(
        rows,
        max_rows=row_limit,
    )
    architect_context["runtime_learning_memory"] = (
        _merge_runtime_learning_memory_context(
            existing_memory,
            memory_context,
        )
    )
    architect_context["runtime_learning_memory"]["handoff_boundary"] = (
        "FormalizationGapPlanner live follow-up runtime learning memory is "
        "orchestration memory only. It can repair route planning and target-prover "
        "replay, but it is not theorem proof evidence."
    )
    return architect_context


def _runtime_formalization_gap_planner_validated_contract_revision_artifact(
    task: AgentTask,
    blackboard: BlackboardState,
    *,
    question_id: str,
) -> tuple[dict[str, Any], list[str]]:
    context = (
        task.inputs.get("route_planner_contract_revision", {})
        if isinstance(task.inputs.get("route_planner_contract_revision", {}), Mapping)
        else {}
    )
    environment_feedback = (
        task.inputs.get("environment_feedback", {})
        if isinstance(task.inputs.get("environment_feedback", {}), Mapping)
        else {}
    )
    learning_feedback_ids = {
        str(row.get("route_planner_contract_feedback_id", "") or "")
        for row in _runtime_formalization_gap_planner_task_runtime_learning_rows(
            task.inputs
        )
        if str(row.get("route_planner_contract_feedback_id", "") or "").strip()
    }
    return validate_contract_revision_artifact(
        context=context,
        artifacts=blackboard.artifacts,
        question_id=question_id,
        environment_feedback=environment_feedback,
        learning_feedback_ids=learning_feedback_ids,
    )


def _runtime_formalization_gap_planner_contract_revision_binding_failure(
    task: AgentTask,
    *,
    question: OpenResearchQuestion,
    errors: Sequence[str],
) -> AgentStepResult:
    failure_id = (
        "runtime_formalization_gap_planner_contract_revision_binding_failure:"
        + stable_hash([task.task_id, question.id, list(errors)])[:20]
    )
    artifact = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeFormalizationGapPlannerContractRevisionBindingFailure",
        "failure_id": failure_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "task_id": task.task_id,
        "question": _question_to_payload(question),
        "errors": list(errors),
        "proof_evidence_status": (
            RUNTIME_FORMALIZATION_GAP_PLANNER_LIVE_ROUTE_PLANNER_CONTRACT_FEEDBACK_STATUS
        ),
        "proof_evidence_boundary": (
            RUNTIME_FORMALIZATION_GAP_PLANNER_LIVE_ROUTE_PLANNER_CONTRACT_REPAIR_BOUNDARY
        ),
    }
    return AgentStepResult(
        status="BLOCKED",
        rationale=(
            "FormalizationGapPlanner rejected an unbound or modified same-run "
            "contract-revision artifact before any provider or prover call."
        ),
        produced_artifacts={failure_id: artifact},
        observations=(
            EnvironmentObservation(
                observation_type=(
                    "formalization_gap_planner_contract_revision_binding_failure"
                ),
                summary="; ".join(str(error) for error in errors[:4]),
                payload={"errors": list(errors)},
            ),
        ),
        evidence_entries=(
            EvidenceLedgerEntry(
                evidence_id="evidence:" + stable_hash([task.task_id, failure_id])[:20],
                task_id=task.task_id,
                artifact_id=failure_id,
                evidence_type=(
                    "formalization_gap_planner_contract_revision_binding"
                ),
                status="CONTRACT_REVISION_BINDING_REJECTED_NOT_PROOF_EVIDENCE",
                boundary=(
                    RUNTIME_FORMALIZATION_GAP_PLANNER_LIVE_ROUTE_PLANNER_CONTRACT_REPAIR_BOUNDARY
                ),
                payload={"errors": list(errors)},
            ),
        ),
        failure_classification=(
            "formalization_gap_planner_contract_revision_binding_invalid"
        ),
    )


def _runtime_formalization_gap_planner_provider_retry_artifact(
    *,
    task: AgentTask,
    question_id: str,
    live_manifest: Mapping[str, Any],
    retry_attempt: int,
    max_provider_retries: int,
) -> dict[str, Any]:
    parent_manifest_id = str(live_manifest.get("manifest_id", "") or "")
    payload = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeFormalizationGapPlannerProviderRetry",
        "question_id": question_id,
        "parent_task_id": task.task_id,
        "parent_manifest_id": parent_manifest_id,
        "parent_manifest_fingerprint": stable_hash(dict(live_manifest)),
        "retry_attempt": max(1, int(retry_attempt)),
        "max_provider_retries": max(0, int(max_provider_retries)),
        "proof_evidence_status": (
            "FORMALIZATION_GAP_PLANNER_PROVIDER_RETRY_NOT_PROOF_EVIDENCE"
        ),
        "boundary": (
            "This artifact authorizes one bounded retry of the same provider-bound "
            "planning task after a response-free provider failure. It cannot alter "
            "the theorem target, handoff lineage, acceptance contract, or proof status."
        ),
    }
    retry_id = (
        "runtime_formalization_gap_planner_provider_retry:"
        + stable_hash(payload)[:20]
    )
    artifact = {**payload, "provider_retry_id": retry_id}
    artifact["binding_fingerprint"] = stable_hash(artifact)
    return artifact


def _runtime_formalization_gap_planner_validated_provider_retry_artifact(
    task: AgentTask,
    blackboard: BlackboardState,
    *,
    question_id: str,
) -> tuple[dict[str, Any], list[str]]:
    raw = task.inputs.get("route_planner_provider_retry", {})
    if raw in (None, {}, []):
        return {}, []
    if not isinstance(raw, Mapping):
        return {}, ["route_planner_provider_retry must be an object"]
    artifact = dict(raw)
    errors: list[str] = []
    retry_id = str(artifact.get("provider_retry_id", "") or "")
    binding_fingerprint = str(artifact.get("binding_fingerprint", "") or "")
    fingerprint_payload = dict(artifact)
    fingerprint_payload.pop("binding_fingerprint", None)
    if artifact.get("artifact_kind") != "RuntimeFormalizationGapPlannerProviderRetry":
        errors.append("provider retry artifact_kind is invalid")
    if str(artifact.get("question_id", "") or "") != question_id:
        errors.append("provider retry question_id does not match current task")
    retry_attempt = int(artifact.get("retry_attempt", 0) or 0)
    max_retries = int(artifact.get("max_provider_retries", 0) or 0)
    if retry_attempt <= 0 or retry_attempt > max_retries:
        errors.append("provider retry attempt exceeds its bounded retry contract")
    if not retry_id:
        errors.append("provider retry artifact is missing provider_retry_id")
    try:
        task_max_retries = int(task.inputs.get("max_provider_retries", -1))
    except (TypeError, ValueError):
        task_max_retries = -1
    if task_max_retries != max_retries:
        errors.append("provider retry task changed its bounded retry limit")
    if task.inputs.get("invoke_live_route_planner") is not True:
        errors.append("provider retry task disabled the bound live route planner")
    persisted = blackboard.artifacts.get(retry_id)
    if not isinstance(persisted, Mapping) or stable_hash(dict(persisted)) != stable_hash(
        artifact
    ):
        errors.append("provider retry artifact is missing or changed on the blackboard")
    if not binding_fingerprint or binding_fingerprint != stable_hash(
        fingerprint_payload
    ):
        errors.append("provider retry binding_fingerprint is invalid")
    parent_manifest_id = str(artifact.get("parent_manifest_id", "") or "")
    parent_manifest = blackboard.artifacts.get(parent_manifest_id)
    if not isinstance(parent_manifest, Mapping):
        errors.append("provider retry parent manifest is missing from the blackboard")
    else:
        if str(parent_manifest.get("task_id", "") or "") != str(
            artifact.get("parent_task_id", "") or ""
        ):
            errors.append("provider retry parent task lineage changed")
        if stable_hash(dict(parent_manifest)) != str(
            artifact.get("parent_manifest_fingerprint", "") or ""
        ):
            errors.append("provider retry parent manifest fingerprint changed")
        parent_question = (
            parent_manifest.get("question", {})
            if isinstance(parent_manifest.get("question", {}), Mapping)
            else {}
        )
        if str(parent_question.get("id", "") or "") != question_id:
            errors.append("provider retry parent manifest question changed")
        for task_key, parent_key in (
            ("provider", "provider_name"),
            ("model", "model"),
            ("model_tier", "model_tier"),
            ("max_tokens", "max_tokens"),
            (
                "max_estimated_prompt_input_tokens",
                "max_estimated_prompt_input_tokens",
            ),
            ("temperature", "temperature"),
            ("max_repair_attempts", "max_repair_attempts"),
            (
                "max_staged_followup_stage_calls",
                "max_staged_followup_stage_calls",
            ),
            (
                "max_route_requests_per_handoff",
                "max_route_requests_per_handoff",
            ),
            ("timeout_seconds", "timeout_seconds"),
        ):
            if stable_hash(task.inputs.get(task_key)) != stable_hash(
                parent_manifest.get(parent_key)
            ):
                errors.append(
                    f"provider retry task changed bound setting {task_key}"
                )
        parent_rows = [
            row
            for row in parent_manifest.get("rows", []) or []
            if isinstance(row, Mapping)
        ]
        parent_bridge_ids = sorted(
            {
                str(row.get("bridge_id", "") or "").strip()
                for row in parent_rows
                if str(row.get("bridge_id", "") or "").strip()
            }
        )
        parent_handoff_ids = sorted(
            {
                str(row.get("handoff_id", "") or "").strip()
                for row in parent_rows
                if str(row.get("handoff_id", "") or "").strip()
            }
        )
        task_environment_feedback = (
            task.inputs.get("environment_feedback", {})
            if isinstance(task.inputs.get("environment_feedback", {}), Mapping)
            else {}
        )
        retry_bridge_ids = sorted(
            {
                str(value).strip()
                for value in compact_string_list(
                    task_environment_feedback.get(
                        "formalization_gap_planner_bridge_ids",
                        [],
                    )
                )
                if str(value).strip()
            }
        )
        retry_handoff_ids = sorted(
            {
                str(value).strip()
                for value in compact_string_list(
                    task_environment_feedback.get(
                        "selected_handoff_ids",
                        [],
                    )
                )
                if str(value).strip()
            }
        )
        if retry_bridge_ids != parent_bridge_ids:
            errors.append("provider retry task changed bound bridge lineage")
        if retry_handoff_ids != parent_handoff_ids:
            errors.append("provider retry task changed bound handoff lineage")
        counts = (
            parent_manifest.get("counts", {})
            if isinstance(parent_manifest.get("counts", {}), Mapping)
            else {}
        )
        provider_failures = int(counts.get("provider_failures", 0) or 0) + int(
            counts.get("staged_followup_stage_provider_failures", 0) or 0
        )
        if provider_failures <= 0:
            errors.append("provider retry parent manifest records no provider failure")
        if parent_manifest.get("feedback_loop_recorded") is True:
            errors.append("provider retry parent already records a usable feedback loop")
    return artifact, sorted(set(errors))


def _runtime_formalization_gap_planner_provider_retry_binding_failure(
    task: AgentTask,
    *,
    question: OpenResearchQuestion,
    errors: Sequence[str],
) -> AgentStepResult:
    failure_id = (
        "runtime_formalization_gap_planner_provider_retry_binding_failure:"
        + stable_hash([task.task_id, question.id, list(errors)])[:20]
    )
    artifact = {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "RuntimeFormalizationGapPlannerProviderRetryBindingFailure",
        "failure_id": failure_id,
        "task_id": task.task_id,
        "question_id": question.id,
        "errors": list(errors),
        "proof_evidence_status": (
            "FORMALIZATION_GAP_PLANNER_PROVIDER_RETRY_NOT_PROOF_EVIDENCE"
        ),
    }
    return AgentStepResult(
        status="BLOCKED",
        rationale=(
            "FormalizationGapPlanner rejected a missing, mutated, cross-target, or "
            "unbounded provider-retry artifact before another provider call."
        ),
        produced_artifacts={failure_id: artifact},
        observations=(
            EnvironmentObservation(
                observation_type=(
                    "formalization_gap_planner_provider_retry_binding_failure"
                ),
                summary="; ".join(str(error) for error in errors[:4]),
                payload={"errors": list(errors)},
            ),
        ),
        failure_classification=(
            "formalization_gap_planner_provider_retry_binding_invalid"
        ),
    )


def _critic_agenda_has_formalization_gap_planner_handoff(
    agenda: Sequence[Mapping[str, Any]],
) -> bool:
    for row in agenda:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("id", "") or "") == "formal_gap:gap_planner_handoff":
            return True
        if str(row.get("route_stage", "") or "") == "gap_planner_handoff":
            return True
        if str(row.get("owner_subsystem", "") or "") == "FormalizationGapPlanner":
            return True
        if str(row.get("formalization_gap_planner_bridge_id", "") or "").strip():
            return True
        if row.get("formalization_gap_planner_execution_contexts"):
            return True
    return False


