        existing = seen_exact_semantic_work_order_by_key.get(key)
        if isinstance(existing, dict):
            _merge_exact_semantic_definition_work_order_candidate_metadata(
                existing,
                row,
            )
            return
        seen_exact_semantic_work_order_by_key[key] = row
        source_theorem_exact_semantic_definition_work_order_rows.append(row)

