def _runtime_learning_memory_should_pin_context_row(row: Mapping[str, Any]) -> bool:
    input_summary = row.get("input_summary", {})
    if not isinstance(input_summary, Mapping):
        input_summary = {}
    learning_task = str(
        row.get("learning_task", "") or input_summary.get("learning_task", "") or ""
    )
    trigger = _runtime_learning_row_trigger(row, input_summary)
    if _runtime_learning_memory_row_is_formal_gap_next_action_routing(
        row,
        input_summary,
    ):
        return True
    if learning_task in RUNTIME_LEARNING_MEMORY_ROUTE_CRITICAL_LEARNING_TASKS:
        return True
    if trigger in RUNTIME_LEARNING_MEMORY_ROUTE_CRITICAL_TRIGGERS:
        return True
    if _runtime_learning_memory_row_has_typechecked_exact_semantic_definition_candidate(
        row,
        input_summary,
    ):
        return True
    if _runtime_learning_memory_context_row_is_exact_semantic_definition_repair_task(
        row,
        input_summary,
    ):
        return True
    return _runtime_learning_memory_row_requires_candidate_materialization(
        row,
        input_summary,
    )


def _runtime_learning_memory_context_row_is_exact_semantic_definition_repair_task(
    row: Mapping[str, Any],
    input_summary: Mapping[str, Any],
) -> bool:
    placeholder = str(
        row.get("placeholder_symbol", "")
        or input_summary.get("placeholder_symbol", "")
        or ""
    ).strip()
    if not placeholder:
        return False
    learning_task = str(
        row.get("learning_task", "") or input_summary.get("learning_task", "") or ""
    )
    proof_evidence_status = str(
        row.get("proof_evidence_status", "")
        or input_summary.get("proof_evidence_status", "")
        or ""
    )
    runtime_queue_status = str(
        row.get("runtime_queue_status", "")
        or input_summary.get("runtime_queue_status", "")
        or ""
    )
    trigger = _runtime_learning_row_trigger(row, input_summary)
    if learning_task.startswith("source_theorem_exact_semantic_definition_"):
        return True
    if runtime_queue_status in {
        "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_REPAIR",
        "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_CANDIDATE_REVIEW",
        "TYPECHECKED_EXACT_DEFINITION_CANDIDATE_REVIEW_REQUIRED",
        "PENDING_EXACT_SEMANTIC_DEFINITION_LOCAL_LEAN_CHECK",
        "PENDING_SOURCE_TO_BRIDGE_ADAPTER_OBJECT_SEMANTIC_DEFINITION",
    }:
        return True
    if trigger in {
        "EXACT_SOURCE_SEMANTIC_DEFINITION_WORK_ORDER",
        "EXACT_SOURCE_SEMANTIC_DEFINITION_SOURCE_LOOKUP",
        "EXACT_SOURCE_SEMANTIC_DEFINITION_LEAN_REPAIR_EXECUTION",
        "EXACT_SEMANTIC_DEFINITION_AUTHORING_CANDIDATE_MATERIALIZED",
        "EXACT_SEMANTIC_DEFINITION_LEAN_IMPORT_ENVIRONMENT_REPAIR",
        "EXACT_SEMANTIC_DEFINITION_LEAN_ENVIRONMENT_PREFLIGHT",
        "SOURCE_TO_BRIDGE_ADAPTER_OBJECT_SEMANTIC_DEFINITION_WORK_ORDER",
    }:
        return True
    if proof_evidence_status in {
        "WORK_ORDER_NOT_PROOF_EVIDENCE",
        "SOURCE_LOOKUP_NOT_PROOF_EVIDENCE",
        "DEFINITION_CLOSURE_WORK_ORDER_NOT_PROOF_EVIDENCE",
        "DEFINITION_CLOSURE_REVIEW_PACKET_NOT_PROOF_EVIDENCE",
        "EXACT_SEMANTIC_DEFINITION_PROOFENGINEER_BRIDGE_NOT_PROOF_EVIDENCE",
        "EXACT_SEMANTIC_DEFINITION_LEAN_REPAIR_EXECUTION_NOT_SOURCE_THEOREM_PROOF",
        "EXACT_SEMANTIC_DEFINITION_AUTHORING_CANDIDATE_MATERIALIZATION_NOT_PROOF_EVIDENCE",
        "EXACT_SEMANTIC_DEFINITION_LEAN_ENVIRONMENT_REPAIR_TASK_NOT_PROOF_EVIDENCE",
        "EXACT_SEMANTIC_DEFINITION_LEAN_ENVIRONMENT_REPAIR_EXECUTION_NOT_PROOF_EVIDENCE",
        "ADAPTER_OBJECT_SEMANTIC_DEFINITION_WORK_ORDER_NOT_PROOF_EVIDENCE",
    } and (
        "semantic_definition" in learning_task
        or "semantic_definition" in trigger.lower()
        or runtime_queue_status.startswith("PENDING_")
    ):
        return True
    return False


def _runtime_learning_memory_context_exact_semantic_definition_repair_priority(
    row: Mapping[str, Any],
    input_summary: Mapping[str, Any],
) -> int:
    if not _runtime_learning_memory_context_row_is_exact_semantic_definition_repair_task(
        row,
        input_summary,
    ):
        return 0
    learning_task = str(
        row.get("learning_task", "") or input_summary.get("learning_task", "") or ""
    )
    proof_evidence_status = str(
        row.get("proof_evidence_status", "")
        or input_summary.get("proof_evidence_status", "")
        or ""
    )
    runtime_queue_status = str(
        row.get("runtime_queue_status", "")
        or input_summary.get("runtime_queue_status", "")
        or ""
    )
    environment_repair_status = str(
        row.get("environment_repair_status", "")
        or input_summary.get("environment_repair_status", "")
        or ""
    ).strip()
    semantic_status = str(
        row.get("semantic_definition_typecheck_evidence_status", "")
        or input_summary.get("semantic_definition_typecheck_evidence_status", "")
        or ""
    ).strip()
    artifact_path = str(
        row.get("definition_only_candidate_artifact_path", "")
        or row.get("candidate_artifact_path", "")
        or input_summary.get("definition_only_candidate_artifact_path", "")
        or input_summary.get("candidate_artifact_path", "")
        or ""
    ).strip()
    if environment_repair_status:
        return 96
    if (
        artifact_path
        or semantic_status
        or runtime_queue_status
        in {
            "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_REPAIR",
            "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_CANDIDATE_REVIEW",
            "TYPECHECKED_EXACT_DEFINITION_CANDIDATE_REVIEW_REQUIRED",
            "PENDING_EXACT_SEMANTIC_DEFINITION_LOCAL_LEAN_CHECK",
        }
        or (
            learning_task
            in {
                "source_theorem_exact_semantic_definition_work_order",
                "source_theorem_exact_semantic_definition_source_lookup",
                "source_theorem_exact_semantic_definition_closure_work_order",
                "source_theorem_exact_semantic_definition_closure_review_packet",
                "source_theorem_exact_semantic_definition_proofengineer_bridge",
            }
            and proof_evidence_status != (
                "ADAPTER_OBJECT_SEMANTIC_DEFINITION_WORK_ORDER_NOT_PROOF_EVIDENCE"
            )
        )
    ):
        return 92
    if "lean_environment" in learning_task or runtime_queue_status == "LAKEFILE_MISSING":
        return 89
    return 88


def _runtime_learning_memory_context_exact_semantic_definition_repair_pin_stage(
    row: Mapping[str, Any],
    input_summary: Mapping[str, Any],
) -> str:
    return (
        _runtime_learning_row_trigger(row, input_summary).strip()
        or str(
            row.get("runtime_queue_status", "")
            or input_summary.get("runtime_queue_status", "")
            or ""
        ).strip()
        or str(
            row.get("proof_evidence_status", "")
            or input_summary.get("proof_evidence_status", "")
            or ""
        ).strip()
        or str(
            row.get("learning_task", "")
            or input_summary.get("learning_task", "")
            or ""
        ).strip()
        or "unspecified"
    )


def _runtime_learning_memory_row_has_typechecked_exact_semantic_definition_candidate(
    row: Mapping[str, Any],
    input_summary: Mapping[str, Any],
) -> bool:
    """Return whether row carries a local-Lean checked semantic definition candidate."""

    nested_candidate = row.get(
        "source_theorem_exact_semantic_definition_typechecked_candidate",
        input_summary.get("source_theorem_exact_semantic_definition_typechecked_candidate", {}),
    )
    if not isinstance(nested_candidate, Mapping):
        nested_candidate = {}
    semantic_status = str(
        row.get("semantic_definition_typecheck_evidence_status", "")
        or input_summary.get("semantic_definition_typecheck_evidence_status", "")
        or nested_candidate.get("semantic_definition_typecheck_evidence_status", "")
        or ""
    )
    local_compiled = bool(
        row.get("local_definition_lean_compiled", False)
        or input_summary.get("local_definition_lean_compiled", False)
        or nested_candidate.get("local_definition_lean_compiled", False)
    )
    artifact_path = str(
        row.get("definition_only_candidate_artifact_path", "")
        or input_summary.get("definition_only_candidate_artifact_path", "")
        or nested_candidate.get("definition_only_candidate_artifact_path", "")
        or ""
    ).strip()
    if local_compiled and (artifact_path or semantic_status):
        return True
    return (
        semantic_status
        in _SOURCE_THEOREM_EXACT_SEMANTIC_DEFINITION_TYPECHECKED_STATUSES
    )


def _runtime_llm_topology_enabled_agent_rows(
    topology: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    agents = topology.get("llm_agents", [])
    if not isinstance(agents, list):
        return []
    return [
        row
        for row in agents
        if isinstance(row, Mapping) and bool(row.get("enabled", False))
    ]


def _runtime_llm_topology_provider_counts_from_agent_rows(
    topology: Mapping[str, Any],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in _runtime_llm_topology_enabled_agent_rows(topology):
        provider = str(row.get("provider_name", "") or "").strip().lower()
        if provider:
            counts[provider] = counts.get(provider, 0) + 1
    return dict(sorted(counts.items()))


def _runtime_llm_topology_model_tier_counts_from_agent_rows(
    topology: Mapping[str, Any],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in _runtime_llm_topology_enabled_agent_rows(topology):
        tier = str(row.get("model_tier", "") or "").strip().lower()
        if tier:
            counts[tier] = counts.get(tier, 0) + 1
    return dict(sorted(counts.items()))


def _runtime_llm_topology_row_is_live_generator(row: Mapping[str, Any]) -> bool:
    if not bool(row.get("enabled", False)):
        return False
    provider = normalize_generator_provider_name(row.get("provider_name", ""))
    backend_provider = normalize_generator_provider_name(
        row.get("backend_provider_name", "")
    )
    return is_live_generator_backend(provider, backend_provider)


def _runtime_llm_topology_live_generator_rows(
    topology: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    return [
        row
        for row in _runtime_llm_topology_enabled_agent_rows(topology)
        if _runtime_llm_topology_row_is_live_generator(row)
    ]


def _runtime_llm_topology_live_generator_count(
    topology: Mapping[str, Any],
) -> int:
    return len(_runtime_llm_topology_live_generator_rows(topology))


def _runtime_llm_proposal_packet_provider(packet: Mapping[str, Any]) -> str:
    return normalize_generator_provider_name(
        packet.get("provider", "") or packet.get("provider_name", "")
    )


def _runtime_llm_proposal_packet_backend_provider(packet: Mapping[str, Any]) -> str:
    return normalize_generator_provider_name(
        packet.get("backend_provider", "") or packet.get("backend_provider_name", "")
    )


def _runtime_llm_proposal_packet_live_generator(packet: Mapping[str, Any]) -> bool:
    provider = _runtime_llm_proposal_packet_provider(packet)
    backend_provider = _runtime_llm_proposal_packet_backend_provider(packet)
    return is_live_generator_backend(provider, backend_provider)


_GENERATED_SANDBOX_EXECUTION_FEEDBACK_TYPES = frozenset(
    {
        "algorithm_sandbox_execution_feedback",
        "generated_simulation_sandbox_execution_feedback",
    }
)


def _generated_sandbox_execution_feedback_snapshot(
    feedback: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Return the ID-bearing sandbox feedback without semantic-review overlays."""

    if not isinstance(feedback, Mapping):
        return {}
    nested = feedback.get("source_execution_feedback", {})
    candidates = (
        nested if isinstance(nested, Mapping) else {},
        feedback,
    )
    for candidate in candidates:
        feedback_type = str(candidate.get("feedback_type", "") or "").strip()
        if (
            feedback_type not in _GENERATED_SANDBOX_EXECUTION_FEEDBACK_TYPES
            or not str(candidate.get("feedback_id", "") or "").strip()
        ):
            continue
        snapshot_keys = (
            "feedback_id",
            "feedback_type",
            "algorithm_sandbox_manifest_id",
            "simulation_manifest_id",
            "failure_classification",
            "prototypes",
            "generated_simulation_prototypes",
            "boundary",
        )
        return {
            key: deepcopy(candidate[key])
            for key in snapshot_keys
            if key in candidate
        }
    return {}


def _generated_code_review_feedback_with_source_execution_snapshot(
    *,
    prior_feedback: Mapping[str, Any] | None,
    review_feedback: Mapping[str, Any],
) -> dict[str, Any]:
    """Make the current review authoritative without discarding prior observations."""

    prior = deepcopy(dict(prior_feedback)) if isinstance(prior_feedback, Mapping) else {}
    merged = deepcopy(dict(review_feedback))
    merged["observation_status"] = "CURRENT_ACTIVE_OBSERVATION"
    source_execution_feedback = _generated_sandbox_execution_feedback_snapshot(
        prior
    )
    if source_execution_feedback:
        merged["source_execution_feedback"] = source_execution_feedback
    if prior:
        prior_history = prior.pop("superseded_observations", [])
        prior.pop("observation_time_contract", None)
        prior["observation_status"] = (
            "SUPERSEDED_BY_SUBSEQUENT_CANDIDATE_REVIEW"
        )
        history = [
            deepcopy(dict(row))
            for row in prior_history
            if isinstance(row, Mapping)
        ]
        history.append(
            {
                "observation_status": "SUPERSEDED_BY_SUBSEQUENT_CANDIDATE_REVIEW",
                "superseded_feedback_id": str(prior.get("feedback_id", "") or ""),
                "superseded_feedback_type": str(
                    prior.get("feedback_type", "") or ""
                ),
                "superseded_failure_classification": str(
                    prior.get("failure_classification", "") or ""
                ),
                "observation": prior,
            }
        )
        merged["superseded_observations"] = history
    merged["observation_time_contract"] = {
        "top_level_observation_is_current": True,
        "superseded_observations_are_historical_only": True,
        "historical_error_is_not_an_active_blocker_unless_reobserved": True,
        "complete_history_preserved": True,
    }
    return merged


def _annotate_generated_sandbox_prototype_provenance(
    prototype: Mapping[str, Any],
    *,
    proposal_packet: Mapping[str, Any] | None,
    repair_feedback: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    annotated = dict(prototype)
    packet = proposal_packet if isinstance(proposal_packet, Mapping) else {}
    annotated["source_llm_proposal_id"] = str(packet.get("packet_id", "") or "")
    annotated["source_llm_proposal_agent"] = str(packet.get("source_agent", "") or "")
    annotated["source_llm_proposal_provider"] = (
        _runtime_llm_proposal_packet_provider(packet) if packet else ""
    )
    annotated["source_llm_proposal_backend_provider"] = (
        _runtime_llm_proposal_packet_backend_provider(packet) if packet else ""
    )
    annotated["source_llm_proposal_model"] = str(packet.get("model", "") or "")
    annotated["source_llm_proposal_model_tier"] = str(
        packet.get("model_tier", "") or ""
    )
    annotated["source_llm_proposal_live_generator"] = (
        _runtime_llm_proposal_packet_live_generator(packet) if packet else False
    )
    annotated["prototype_artifact_id"] = _generated_sandbox_prototype_artifact_id(
        annotated
    )
    feedback = repair_feedback if isinstance(repair_feedback, Mapping) else {}
    source_execution_feedback = _generated_sandbox_execution_feedback_snapshot(
        feedback
    )
    if source_execution_feedback:
        lineage_feedback: Mapping[str, Any] = source_execution_feedback
    else:
        lineage_feedback = feedback
    feedback_id = str(lineage_feedback.get("feedback_id", "") or "").strip()
    parent_manifest_id = str(
        lineage_feedback.get("algorithm_sandbox_manifest_id", "")
        or lineage_feedback.get("simulation_manifest_id", "")
        or ""
    ).strip()
    parent_rows = lineage_feedback.get("prototypes", [])
    if not isinstance(parent_rows, list) or not parent_rows:
        parent_rows = lineage_feedback.get(
            "generated_simulation_prototypes", []
        )
    if not isinstance(parent_rows, list):
        parent_rows = []
    parent_artifact_ids = [
        str(row.get("prototype_artifact_id", "") or "").strip()
        for row in parent_rows
        if isinstance(row, Mapping)
        and str(row.get("prototype_artifact_id", "") or "").strip()
    ]
    parent_script_hashes = [
        str(row.get("script_hash", "") or "").strip()
        for row in parent_rows
        if isinstance(row, Mapping)
        and str(row.get("script_hash", "") or "").strip()
    ]
    if feedback_id and parent_manifest_id and parent_artifact_ids:
        annotated["repair_lineage"] = {
            "schema_version": 1,
            "artifact_kind": "GeneratedSandboxRepairLineage",
            "feedback_id": feedback_id,
            "feedback_type": str(
                lineage_feedback.get("feedback_type", "") or ""
            ),
            "feedback_failure_classification": str(
                lineage_feedback.get("failure_classification", "") or ""
            ),
            "parent_manifest_id": parent_manifest_id,
            "parent_prototype_artifact_ids": list(dict.fromkeys(parent_artifact_ids)),
            "parent_script_hashes": list(dict.fromkeys(parent_script_hashes)),
            "child_prototype_artifact_id": annotated["prototype_artifact_id"],
            "child_script_hash": _generated_sandbox_prototype_script_hash(annotated),
            "child_proposal_id": annotated["source_llm_proposal_id"],
            "feedback_supplied_to_generator": True,
            "lineage_contract_complete": True,
            "semantic_review_execution_id": str(
                feedback.get("semantic_review_execution_id", "") or ""
            ),
            "semantic_review_packet_id": str(
                feedback.get("semantic_review_packet_id", "") or ""
            ),
            "semantic_review_packet_hash": str(
                feedback.get("semantic_review_packet_hash", "") or ""
            ),
            "semantic_review_feedback_supplied_to_generator": bool(
                str(feedback.get("semantic_review_execution_id", "") or "")
                and str(feedback.get("semantic_review_packet_id", "") or "")
            ),
            "boundary": (
                "This lineage records which failed generated artifact and runtime "
                "feedback were supplied to the next LLM proposal. It is execution "
                "provenance, not statistical or theorem proof evidence."
            ),
        }
    return annotated


def _generated_sandbox_prototype_script_hash(row: Mapping[str, Any]) -> str:
    script_hash = str(row.get("script_hash", "") or "").strip()
    if script_hash:
        return script_hash
    code_excerpt = str(row.get("code_excerpt", "") or "")
    return stable_hash(code_excerpt) if code_excerpt else ""


def _generated_sandbox_prototype_artifact_id(row: Mapping[str, Any]) -> str:
    scope_id = str(
        row.get("simulation_id", "")
        or row.get("estimator_id", "")
        or "generated_sandbox"
    )
    identity = {
        "executor": str(row.get("executor", "") or ""),
        "scope_id": scope_id,
        "script_hash": _generated_sandbox_prototype_script_hash(row),
        "source_llm_proposal_id": str(
            row.get("source_llm_proposal_id", "") or ""
        ),
    }
    if not identity["script_hash"]:
        identity["missing_code_identity"] = stable_hash(
            {
                "status": str(row.get("prototype_status", "") or ""),
                "reason": str(row.get("reason", "") or ""),
                "spec": row.get("spec", {}),
            }
        )
    return "generated_sandbox_prototype:" + stable_hash(identity)[:20]


def _generated_sandbox_feedback_id(
    *,
    feedback_type: str,
    source_manifest_id: str,
    failure_classification: str,
    prototype_rows: Sequence[Mapping[str, Any]],
) -> str:
    snapshot = [
        {
            "prototype_artifact_id": _generated_sandbox_prototype_artifact_id(row),
            "script_hash": _generated_sandbox_prototype_script_hash(row),
            "prototype_status": str(row.get("prototype_status", "") or ""),
            "smoke_passed": row.get("smoke_passed"),
            "metric_gate_errors": list(_str_tuple(row.get("metric_gate_errors", []))),
            "safety_errors": list(_str_tuple(row.get("safety_errors", []))),
            "returncode": row.get("returncode"),
            "stderr_summary_hash": stable_hash(
                str(row.get("stderr_summary", "") or "")
            ),
            "result_parse_error": str(row.get("result_parse_error", "") or ""),
        }
        for row in list(prototype_rows)[:5]
        if isinstance(row, Mapping)
    ]
    return "generated_sandbox_feedback:" + stable_hash(
        [
            feedback_type,
            source_manifest_id,
            failure_classification,
            snapshot,
        ]
    )[:20]


def _generated_sandbox_row_executed(row: Mapping[str, Any]) -> bool:
    return str(row.get("prototype_status", "") or "") in {
        "EXECUTED",
        "FAILED_METRIC_GATE",
    }


def _generated_sandbox_row_execution_attempted(row: Mapping[str, Any]) -> bool:
    return str(row.get("prototype_status", "") or "") in {
        "EXECUTED",
        "FAILED",
        "FAILED_METRIC_GATE",
    }


def _generated_sandbox_row_live_generated(row: Mapping[str, Any]) -> bool:
    provider = normalize_generator_provider_name(
        row.get("source_llm_proposal_provider", "")
    )
    backend_provider = normalize_generator_provider_name(
        row.get("source_llm_proposal_backend_provider", "") or ""
    )
    return (
        row.get("source_llm_proposal_live_generator") is True
        and is_live_generator_backend(provider, backend_provider)
    )


def _runtime_artifacts_with_generated_sandbox_live_provenance(
    artifacts: Mapping[str, Any],
) -> dict[str, Any]:
    proposal_packets = _runtime_llm_proposal_packets_by_id(artifacts)
    live_topology_by_subsystem = _runtime_live_generator_topology_by_subsystem(
        artifacts
    )
    enriched: dict[str, Any] = {}
    for artifact_id, artifact in artifacts.items():
        if not isinstance(artifact, Mapping):
            enriched[artifact_id] = artifact
            continue
        kind = str(artifact.get("artifact_kind", "") or "")
        if kind == "RuntimeAlgorithmSandboxManifest":
            enriched[artifact_id] = _generated_sandbox_manifest_with_live_provenance(
                artifact,
                proposal_packets=proposal_packets,
                live_topology_by_subsystem=live_topology_by_subsystem,
                subsystem="AlgorithmEngineer",
                proposal_id_keys=("llm_algorithm_engineer_proposal_id",),
                prototype_key="prototypes",
                generated_executor="generated_python_sandbox",
                missing_statuses={"MODEL_CODE_REQUIRED_BUT_MISSING"},
            )
        elif kind == "RuntimeSimulationManifest":
            enriched[artifact_id] = _generated_sandbox_manifest_with_live_provenance(
                artifact,
                proposal_packets=proposal_packets,
                live_topology_by_subsystem=live_topology_by_subsystem,
                subsystem="SimulationEngineer",
                proposal_id_keys=("llm_simulation_engineer_proposal_id",),
                prototype_key="generated_simulation_sandbox_prototypes",
                generated_executor="generated_simulation_sandbox",
                missing_statuses={"GENERATED_SIMULATION_CODE_REQUIRED_BUT_MISSING"},
            )
        else:
            enriched[artifact_id] = artifact
    return enriched


def _runtime_llm_proposal_packets_by_id(
    artifacts: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    proposal_kinds = {
        "ArchitectCoordinatorProposalPacket",
        "SimulationEngineerProposalPacket",
        "AlgorithmEngineerProposalPacket",
        "FormalizerProofEngineerProposalPacket",
        "CriticEvaluatorProposalPacket",
    }
    proposal_source_agents = {
        "LLMArchitectCoordinatorAgent",
        "LLMSimulationEngineerAgent",
        "LLMAlgorithmEngineerAgent",
        "LLMFormalizerProofEngineerAgent",
        "LLMCriticEvaluatorAgent",
    }
    packets: dict[str, Mapping[str, Any]] = {}
    for artifact_id, artifact in artifacts.items():
        if not isinstance(artifact, Mapping):
            continue
        kind = str(artifact.get("artifact_kind", "") or "")
        source_agent = str(artifact.get("source_agent", "") or "")
        if kind not in proposal_kinds and source_agent not in proposal_source_agents:
            continue
        packet_id = str(artifact.get("packet_id", "") or artifact_id or "").strip()
        if not packet_id:
            continue
        if not (
            source_agent or artifact.get("provider") or artifact.get("provider_name")
        ):
            continue
        packets[packet_id] = artifact
    return packets


def _runtime_live_generator_topology_by_subsystem(
    artifacts: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    rows: dict[str, Mapping[str, Any]] = {}
    for artifact in artifacts.values():
        if not isinstance(artifact, Mapping):
            continue
        if str(artifact.get("artifact_kind", "") or "") != (
            "RuntimeLLMTopologyManifest"
        ):
            continue
        agents = artifact.get("llm_agents", [])
        if not isinstance(agents, list):
            continue
        for row in agents:
            if not isinstance(row, Mapping):
                continue
            subsystem = str(row.get("subsystem", "") or "").strip()
            if subsystem and _runtime_llm_topology_row_is_live_generator(row):
                rows[subsystem] = row
    return rows


def _generated_sandbox_manifest_with_live_provenance(
    manifest: Mapping[str, Any],
    *,
    proposal_packets: Mapping[str, Mapping[str, Any]],
    live_topology_by_subsystem: Mapping[str, Mapping[str, Any]],
    subsystem: str,
    proposal_id_keys: tuple[str, ...],
    prototype_key: str,
    generated_executor: str,
    missing_statuses: set[str],
) -> Mapping[str, Any]:
    rows = manifest.get(prototype_key, [])
    if not isinstance(rows, list) or not rows:
        return manifest
    proposal_id = ""
    for key in proposal_id_keys:
        proposal_id = str(manifest.get(key, "") or "").strip()
        if proposal_id:
            break
    proposal_packet = proposal_packets.get(proposal_id, {})
    topology_row = live_topology_by_subsystem.get(subsystem, {})
    if not proposal_packet and not topology_row:
        return manifest
    enriched_rows: list[Any] = []
    changed = False
    for row in rows:
        if not isinstance(row, Mapping):
            enriched_rows.append(row)
            continue
        if not _generated_sandbox_row_needs_provenance(
            row,
            generated_executor=generated_executor,
            missing_statuses=missing_statuses,
        ):
            enriched_rows.append(row)
            continue
        enriched_row = _generated_sandbox_row_with_live_provenance(
            row,
            proposal_packet=proposal_packet,
            topology_row=topology_row,
        )
        changed = changed or enriched_row is not row
        enriched_rows.append(enriched_row)
    if not changed:
        return manifest
    enriched_manifest = dict(manifest)
    enriched_manifest[prototype_key] = enriched_rows
    return enriched_manifest


def _generated_sandbox_row_needs_provenance(
    row: Mapping[str, Any],
    *,
    generated_executor: str,
    missing_statuses: set[str],
) -> bool:
    return (
        str(row.get("executor", "") or "") == generated_executor
        or str(row.get("prototype_status", "") or "") in missing_statuses
    )


def _generated_sandbox_row_with_live_provenance(
    row: Mapping[str, Any],
    *,
    proposal_packet: Mapping[str, Any],
    topology_row: Mapping[str, Any],
) -> Mapping[str, Any]:
    if _generated_sandbox_row_live_generated(row):
        return row
    row_backend = normalize_generator_provider_name(
        row.get("source_llm_proposal_backend_provider", "")
    )
    if row_backend:
        return row
    provider = normalize_generator_provider_name(
        row.get("source_llm_proposal_provider", "")
    ) or _runtime_llm_proposal_packet_provider(proposal_packet)
    backend_provider = _runtime_llm_proposal_packet_backend_provider(proposal_packet)
    topology_provider = normalize_generator_provider_name(
        topology_row.get("provider_name", "")
    )
    topology_backend = normalize_generator_provider_name(
        topology_row.get("backend_provider_name", "")
    )
    if (
        provider
        and not backend_provider
        and topology_provider == provider
        and is_live_generator_backend(topology_provider, topology_backend)
    ):
        proposal_model = str(proposal_packet.get("model", "") or "").strip()
        topology_model = str(topology_row.get("model", "") or "").strip()
        if not proposal_model or not topology_model or proposal_model == topology_model:
            backend_provider = topology_backend
    if not is_live_generator_backend(provider, backend_provider):
        return row
    enriched = dict(row)
    enriched.setdefault(
        "source_llm_proposal_id", str(proposal_packet.get("packet_id", "") or "")
    )
    enriched.setdefault(
        "source_llm_proposal_agent", str(proposal_packet.get("source_agent", "") or "")
    )
    enriched["source_llm_proposal_provider"] = provider
    enriched["source_llm_proposal_backend_provider"] = backend_provider
    enriched.setdefault(
        "source_llm_proposal_model", str(proposal_packet.get("model", "") or "")
    )
    enriched.setdefault(
        "source_llm_proposal_model_tier",
        str(proposal_packet.get("model_tier", "") or ""),
    )
    enriched["source_llm_proposal_live_generator"] = True
    if not _runtime_llm_proposal_packet_backend_provider(proposal_packet):
        enriched["source_llm_proposal_backend_inferred_from_topology"] = True
    return enriched


def _generated_sandbox_live_counts_from_rows(
    rows: Any,
    *,
    generated_executor: str,
) -> Counter[str]:
    counts: Counter[str] = Counter()
    if not isinstance(rows, list):
        return counts
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("executor", "") or "") != generated_executor:
            continue
        if not _generated_sandbox_row_live_generated(row):
            continue
        if _generated_sandbox_row_executed(row):
            counts["executed"] += 1
        if row.get("smoke_passed") is True:
            counts["passed"] += 1
        if row.get("mechanical_estimator_invocation_verified") is True:
            counts["mechanical_estimator_invocation_verified"] += 1
        if str(row.get("prototype_status", "") or "") == "FAILED_METRIC_GATE":
            counts["metric_gate_failed"] += 1
        if str(row.get("prototype_status", "") or "") == (
            "REJECTED_UNSAFE_GENERATED_CODE"
        ):
            counts["unsafe_rejected"] += 1
        counts.update(
            _generated_sandbox_metric_contract_counts_from_row(row)
        )
    return counts


def _generated_sandbox_metric_contract_counts_from_row(
    row: Mapping[str, Any],
) -> Counter[str]:
    counts: Counter[str] = Counter()
    contracts = row.get("metric_contracts", [])
    if isinstance(contracts, list):
        counts["typed_metric_contracts_declared"] += sum(
            1 for contract in contracts if isinstance(contract, Mapping)
        )
        counts["typed_metric_contracts_authority_bound"] += sum(
            1
            for contract in contracts
            if isinstance(contract, Mapping)
            and str(
                contract.get("authority_requirement_fingerprint", "") or ""
            ).strip()
        )
    authority_required = bool(
        row.get("metric_requirement_authority_required", False)
    )
    authority_validated = bool(
        row.get("metric_requirement_authority_validated", False)
    )
    if authority_required:
        counts["typed_metric_contract_artifacts_authority_required"] += 1
    if authority_validated:
        counts["typed_metric_contract_artifacts_authority_validated"] += 1
    if str(row.get("prototype_status", "") or "") == (
        "METRIC_REQUIREMENT_AUTHORITY_REJECTED"
    ):
        counts["typed_metric_contract_artifacts_authority_rejected"] += 1
    evaluation = row.get("metric_contract_evaluation", {})
    if not isinstance(evaluation, Mapping):
        return counts
    n_contracts = _generated_metric_contract_evaluation_count(row, "n_contracts")
    if n_contracts <= 0:
        return counts
    counts["typed_metric_contract_artifacts_evaluated"] += 1
    counts["typed_metric_contracts_evaluated"] += n_contracts
    counts["typed_metric_contracts_passed"] += (
        _generated_metric_contract_evaluation_count(row, "n_passed")
    )
    counts["typed_metric_contracts_failed"] += (
        _generated_metric_contract_evaluation_count(row, "n_failed")
    )
    if evaluation.get("all_required_passed") is True:
        counts["typed_metric_contract_artifacts_all_required_passed"] += 1
        if authority_validated or evaluation.get(
            "metric_requirement_authority_validated"
        ) is True:
            counts[
                "typed_metric_contract_artifacts_authority_validated_all_required_passed"
            ] += 1
    else:
        counts["typed_metric_contract_artifacts_with_required_failure"] += 1
    return counts


def _generated_sandbox_metric_contract_counts_from_rows(
    rows: Any,
    *,
    generated_executor: str,
) -> Counter[str]:
    counts: Counter[str] = Counter()
    if not isinstance(rows, list):
        return counts
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("executor", "") or "") != generated_executor:
            continue
        counts.update(_generated_sandbox_metric_contract_counts_from_row(row))
    return counts


def _runtime_llm_topology_summary(topology: Mapping[str, Any]) -> dict[str, Any]:
    """Compact manifest-level LLM provenance summary.

    The full topology artifact remains authoritative, but these top-level fields
    prevent static replay runs from being mistaken for live generator evidence.
    """

    counts = topology.get("counts", {})
    if not isinstance(counts, Mapping):
        counts = {}
    counts_provider_counts = {
        str(provider): int(count)
        for provider, count in dict(counts.get("enabled_by_provider", {}) or {}).items()
    }
    counts_model_tier_counts = {
        str(tier): int(count)
        for tier, count in dict(counts.get("enabled_by_model_tier", {}) or {}).items()
    }
    agent_rows_available = isinstance(topology.get("llm_agents"), list)
    row_provider_counts = _runtime_llm_topology_provider_counts_from_agent_rows(
        topology
    )
    row_model_tier_counts = _runtime_llm_topology_model_tier_counts_from_agent_rows(
        topology
    )
    enabled_provider_counts = (
        row_provider_counts if agent_rows_available else counts_provider_counts
    )
    enabled_model_tier_counts = (
        row_model_tier_counts if agent_rows_available else counts_model_tier_counts
    )
    n_enabled = (
        len(_runtime_llm_topology_enabled_agent_rows(topology))
        if agent_rows_available
        else int(counts.get("llm_agents_enabled", 0) or 0)
    )
    n_static = int(enabled_provider_counts.get("static", 0) or 0)
    live_rows = _runtime_llm_topology_live_generator_rows(topology)
    n_live = (
        len(live_rows)
        if agent_rows_available
        else 0
    )
    return {
        "artifact_kind": "RuntimeLLMTopologySummary",
        "policy_status": str(topology.get("policy_status", "") or ""),
        "policy_ok": str(topology.get("policy_status", "") or "") == "OK",
        "policy_violations": list(topology.get("policy_violations", []) or []),
        "enabled_provider_counts": dict(sorted(enabled_provider_counts.items())),
        "enabled_model_tier_counts": dict(sorted(enabled_model_tier_counts.items())),
        "n_llm_agents_enabled": n_enabled,
        "n_live_generator_agents_enabled": n_live,
        "live_generator_subsystems": sorted(
            str(row.get("subsystem", "") or "")
            for row in live_rows
            if str(row.get("subsystem", "") or "").strip()
        ),
        "n_static_generator_agents_enabled": n_static,
        "all_enabled_llm_agents_static": bool(n_enabled > 0 and n_enabled == n_static),
        "unsupported_generator_backends_enabled": int(
            counts.get("unsupported_generator_backends_enabled", 0) or 0
        ),
        "anthropic_model_tier_mismatches": int(
            counts.get("anthropic_model_tier_mismatches", 0) or 0
        ),
        "anthropic_serious_model_tier_mismatches": int(
            counts.get("anthropic_serious_model_tier_mismatches", 0) or 0
        ),
        "subsystem_model_tier_policy_mismatches": int(
            counts.get("subsystem_model_tier_policy_mismatches", 0) or 0
        ),
        "contextual_model_tier_policy_mismatches": int(
            counts.get("contextual_model_tier_policy_mismatches", 0) or 0
        ),
        "boundary": (
            "This is runtime generator provenance only. Static generators and live "
            "LLM proposals are not theorem proof, simulation evidence, or code "
            "execution evidence."
        ),
    }


def _llm_topology_policy_violations(agents: list[dict[str, Any]]) -> list[str]:
    violations: list[str] = []
    for row in agents:
        if not row.get("enabled"):
            continue
        unsupported = _unsupported_generator_providers(row)
        if unsupported:
            violations.append(
                f"{row.get('subsystem')} uses unsupported generator provider(s): "
                + ", ".join(sorted(unsupported))
            )
        mismatch = _anthropic_model_tier_mismatch(row)
        if mismatch:
            violations.append(mismatch)
        serious_mismatch = _anthropic_serious_model_tier_mismatch(row)
        if serious_mismatch:
            violations.append(serious_mismatch)
        subsystem_tier_mismatch = _subsystem_model_tier_mismatch(row)
        if subsystem_tier_mismatch:
            violations.append(subsystem_tier_mismatch)
        contextual_tier_mismatch = _contextual_model_tier_mismatch(row)
        if contextual_tier_mismatch:
            violations.append(contextual_tier_mismatch)
    return violations


def _has_unsupported_generator_provider(row: Mapping[str, Any]) -> bool:
    return bool(_unsupported_generator_providers(row))


def _unsupported_generator_providers(row: Mapping[str, Any]) -> set[str]:
    allowed = set(SUPPORTED_GENERATOR_PROVIDERS)
    providers = {
        str(row.get("provider_name", "") or "").strip().lower(),
        str(row.get("backend_provider_name", "") or "").strip().lower(),
    }
    providers.discard("")
    return {provider for provider in providers if provider not in allowed}


def _anthropic_model_tier_mismatch(row: Mapping[str, Any]) -> str:
    providers = {
        str(row.get("provider_name", "") or "").strip().lower(),
        str(row.get("backend_provider_name", "") or "").strip().lower(),
    }
    if "anthropic" not in providers:
        return ""
    return claude_model_tier_mismatch(
        str(row.get("model", "") or "").strip(),
        str(row.get("model_tier", "") or "").strip().lower(),
        subject=str(row.get("subsystem", "") or "").strip(),
    )


def _anthropic_serious_model_tier_mismatch(row: Mapping[str, Any]) -> str:
    if not str(row.get("serious_model_tier", "") or "").strip():
        return ""
    providers = {
        str(row.get("provider_name", "") or "").strip().lower(),
        str(row.get("backend_provider_name", "") or "").strip().lower(),
    }
    if "anthropic" not in providers:
        return ""
    return claude_model_tier_mismatch(
        str(row.get("serious_model", "") or "").strip(),
        str(row.get("serious_model_tier", "") or "").strip().lower(),
        subject=f"{str(row.get('subsystem', '') or '').strip()} serious workspace",
    )


def _subsystem_model_tier_mismatch(row: Mapping[str, Any]) -> str:
    expected = str(row.get("expected_model_tier", "") or "").strip().lower()
    configured = str(row.get("model_tier", "") or "").strip().lower()
    if not expected or expected == "auto":
        return ""
    if configured == expected:
        return ""
    return (
        f"{row.get('subsystem')} expected model_tier {expected} by "
        f"AI Statistician LLM subsystem policy but is configured with "
        f"{configured or 'missing'}"
    )


def _contextual_model_tier_mismatch(row: Mapping[str, Any]) -> str:
    expected = str(
        row.get("expected_serious_model_tier", "") or ""
    ).strip().lower()
    configured = str(row.get("serious_model_tier", "") or "").strip().lower()
    if not expected or configured == expected:
        return ""
    return (
        f"{row.get('subsystem')} serious workspace expected model_tier "
        f"{expected} by AI Statistician contextual LLM policy but is configured "
        f"with {configured or 'missing'}"
    )


def _llm_agent_topology_row(
    subsystem: str,
    agent: Any | None,
    *,
    role: str,
) -> dict[str, Any]:
    expected_model_tier = llm_subsystem_expected_model_tier(subsystem)
    if agent is None:
        return {
            "subsystem": subsystem,
            "enabled": False,
            "provider_name": "",
            "backend_provider_name": "",
            "model": "",
            "model_tier": expected_model_tier,
            "expected_model_tier": expected_model_tier,
            "role": role,
            "generator_only": True,
            "acts_in_environment": False,
        }
    config = getattr(agent, "config", None)
    provider = getattr(agent, "provider", None)
    provider_name = str(getattr(config, "provider_name", "") or getattr(provider, "provider_name", "") or "")
    config_model_tier = str(
        getattr(config, "model_tier", "") or expected_model_tier
    )
    requested_model = str(getattr(config, "model", "") or "")
    resolved_model = resolve_generator_model(
        provider_name=provider_name,
        requested_model=requested_model,
        model_tier=config_model_tier,
    )
    row = {
        "subsystem": subsystem,
        "enabled": True,
        "provider_name": provider_name,
        "backend_provider_name": str(getattr(provider, "provider_name", provider_name) or ""),
        "model": resolved_model,
        "configured_model": requested_model,
        "model_tier": config_model_tier,
        "expected_model_tier": expected_model_tier,
        "role": role,
        "generator_only": True,
        "acts_in_environment": False,
        "max_tokens": int(getattr(config, "max_tokens", 0) or 0),
        "temperature": float(getattr(config, "temperature", 0.0) or 0.0),
    }
    if subsystem == "TheoryDeveloper":
        serious_model_tier = str(
            getattr(config, "serious_model_tier", "")
            or AI_STATISTICIAN_LLM_CONTEXTUAL_MODEL_TIER_POLICY.get(
                "TheoryDeveloper:serious", ""
            )
        )
        row.update(
            {
                "serious_model": resolve_generator_model(
                    provider_name=provider_name,
                    requested_model=str(
                        getattr(config, "serious_model", "") or ""
                    ),
                    model_tier=serious_model_tier,
                ),
                "configured_serious_model": str(
                    getattr(config, "serious_model", "") or ""
                ),
                "serious_model_tier": serious_model_tier,
                "expected_serious_model_tier": (
                    AI_STATISTICIAN_LLM_CONTEXTUAL_MODEL_TIER_POLICY.get(
                        "TheoryDeveloper:serious", ""
                    )
                ),
                "serious_max_tokens": int(
                    getattr(config, "serious_max_tokens", 0) or 0
                ),
            }
        )
    return row


def _implementation_gaps(
    packet: Any,
    procedures: list[CandidateProcedure],
    *,
    require_generated_adapter: bool = False,
) -> list[dict[str, Any]]:
    if not isinstance(packet, Mapping):
        return []
    registered_ids = {row.id for row in procedures}
    registered_algorithms = {row.algorithm for row in procedures}
    gaps: list[dict[str, Any]] = []
    for row in packet.get("estimator_specs", []) or []:
        if not isinstance(row, Mapping):
            continue
        estimator_id = str(row.get("id") or row.get("name") or "").strip()
        if not estimator_id:
            continue
        if (
            not require_generated_adapter
            and (
                estimator_id in registered_ids
                or estimator_id in registered_algorithms
            )
        ):
            continue
        gaps.append(
            {
                "estimator_id": estimator_id,
                "status": (
                    "REQUIRES_GENERATED_ALGORITHM_ENGINEER_ADAPTER"
                    if require_generated_adapter
                    else "REQUIRES_ALGORITHM_ENGINEER_ADAPTER"
                ),
                "reason": (
                    "Agentic execution requires this LLM estimator spec to pass "
                    "through generated code, sandbox execution, and independent "
                    "semantic review. DGP-based statistical-performance gates belong "
                    "to the downstream SimulationEngineer experiment. A registered "
                    "template cannot satisfy this generated-artifact evidence gate."
                    if require_generated_adapter
                    else "LLM estimator spec has no registered executable algorithm "
                    "in this runtime slice."
                ),
            }
        )
    return gaps


def _critic_repair_round(context: Mapping[str, Any]) -> int:
    loop = context.get("runtime_feedback_loop")
    if not isinstance(loop, Mapping):
        return 0
    try:
        return max(0, int(loop.get("critic_repair_round", 0) or 0))
    except (TypeError, ValueError):
        return 0


def _unique_runtime_artifact_id(
    blackboard: BlackboardState,
    artifact_id: str,
    *,
    task_id: str,
) -> str:
    if artifact_id not in blackboard.artifacts:
        return artifact_id
    return f"{artifact_id}:runtime_revision:{stable_hash(task_id)[:8]}"


def _effective_critic_repair_rounds(
    context: Mapping[str, Any],
    config: ResearchAgentRuntimeConfig,
) -> int:
    configured = max(0, int(config.max_critic_repair_rounds))
    policy = _architect_runtime_plan(context).get("iteration_policy", {})
    if not isinstance(policy, Mapping):
        return configured
    try:
        architect_max = int(policy.get("max_repair_rounds", configured) or configured)
    except (TypeError, ValueError):
        return configured
    return max(0, min(configured, architect_max))


def _critic_should_reroute_to_theory(
    *,
    agenda: list[dict[str, Any]],
    formalization_manifest: Mapping[str, Any],
    critic_round: int,
    max_critic_repair_rounds: int,
    formal_verification_policy: str,
) -> bool:
    if critic_round >= max_critic_repair_rounds:
        return False
    formal_required = (
        _normalized_formal_verification_policy(formal_verification_policy)
        == "required"
    )
    formal_counts = formalization_manifest.get("counts", {}) if isinstance(formalization_manifest, Mapping) else {}
    if formal_required:
        if int(formal_counts.get("formal_gap", 0) or 0) > 0:
            return True
        if int(formal_counts.get("proof_state_route_revisions", 0) or 0) > 0:
            return True
        if int(formal_counts.get("kernel_verified", 0) or 0) == 0 and int(formal_counts.get("proved", 0) or 0) > 0:
            return True
    for row in agenda:
        agenda_id = str(row.get("id", ""))
        if agenda_id.startswith("simulation:theory_revision"):
            return True
        if formal_required and agenda_id.startswith(("formal_gap:", "proof_feedback:")):
            return True
    return False


def _critic_evidence_contract_decision(
    *,
    critic_control: Mapping[str, Any],
    formalization_manifest: Mapping[str, Any],
    should_repair: bool,
) -> dict[str, Any]:
    """Classify terminal critic status under the Architect evidence contract."""

    contract = (
        critic_control.get("evidence_contract", {})
        if isinstance(critic_control, Mapping)
        else {}
    )
    if not isinstance(contract, Mapping):
        contract = {}
    policy = (
        str(contract.get("formal_verification_policy", "") or "optional")
        .strip()
        .lower()
    )
    if policy not in {"required", "optional", "advisory"}:
        policy = "optional"
    counts = (
        formalization_manifest.get("counts", {})
        if isinstance(formalization_manifest, Mapping)
        and isinstance(formalization_manifest.get("counts", {}), Mapping)
        else {}
    )
    formal_gaps = _int_like(counts.get("formal_gap", 0))
    kernel_verified = _int_like(counts.get("kernel_verified", 0))
    full_theorem_proved = _bool_like(
        formalization_manifest.get("full_frontier_theorem_proved", False)
        if isinstance(formalization_manifest, Mapping)
        else False
    )
    formal_satisfied = bool(
        formal_gaps <= 0 and (full_theorem_proved or kernel_verified > 0)
    )
    if should_repair:
        final_status = "REROUTE_REQUIRED_BEFORE_FINAL"
        runtime_status = "REVISE"
        failure_classification = ""
    elif policy == "required" and not formal_satisfied:
        final_status = "FORMAL_REQUIRED_BLOCKED"
        runtime_status = "BLOCKED"
        failure_classification = "formal_required_unverified"
    elif policy == "advisory":
        final_status = "RESEARCH_CANDIDATE_ACCEPTED_FORMAL_ADVISORY"
        runtime_status = "ACCEPTED"
        failure_classification = ""
    elif policy == "optional" and not formal_satisfied:
        final_status = "RESEARCH_CANDIDATE_ACCEPTED_WITH_FORMAL_GAPS"
        runtime_status = "ACCEPTED"
        failure_classification = ""
    else:
        final_status = "FORMAL_CONTRACT_SATISFIED"
        runtime_status = "ACCEPTED"
        failure_classification = ""
    return {
        "formal_verification_policy": policy,
        "recommended_research_path": str(
            contract.get("recommended_research_path", "") or ""
        ),
        "formal_required_for_final": _bool_like(
            contract.get("formal_required_for_final", policy == "required")
        ),
        "simulation_required_for_final": _bool_like(
            contract.get("simulation_required_for_final", False)
        ),
        "must_disclose_formal_gaps": _bool_like(
            contract.get("must_disclose_formal_gaps", True)
        ),
        "formal_gaps": formal_gaps,
        "kernel_verified": kernel_verified,
        "full_frontier_theorem_proved": full_theorem_proved,
        "formal_satisfied": formal_satisfied,
        "runtime_status": runtime_status,
        "final_acceptance_status": final_status,
        "failure_classification": failure_classification,
        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
    }


def _critic_should_route_to_formalizer_proofengineer(
    *,
    agenda: list[dict[str, Any]],
    formalization_manifest: Mapping[str, Any],
) -> bool:
    """Keep unresolved proof-repair work explicit after theory repair budget."""

    proof_bank_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(formalization_manifest, Mapping)
        and isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    formalizer_modes = {
        "source_theorem_diagnostic_helper_bridge_or_blocker",
        "source_to_bridge_premise_derivation_required",
        "source_theorem_exact_semantic_definition_structural_reformulation",
        "source_theorem_exact_semantic_definition_repair",
        "source_theorem_exact_candidate_materialization_required",
        "source_theorem_exact_proof_body_repair",
        "source_theorem_proof_body_adapter_required",
        "source_theorem_exact_semantics_or_theorem_promotion",
        "source_theorem_semantic_primitive_closure",
        "theorem_level_reduction_closure",
    }
    mode = str(
        proof_bank_summary.get("recommended_formalizer_target_mode", "") or ""
    ).strip()
    if mode in formalizer_modes:
        return True
    if _bool_like(
        proof_bank_summary.get("source_to_bridge_premise_derivation_required")
    ):
        return True
    if _bool_like(
        proof_bank_summary.get("source_theorem_exact_semantic_definition_repair_required")
    ):
        return True
    if _bool_like(
        proof_bank_summary.get("source_theorem_exact_proof_body_repair_required")
    ):
        return True
    if _bool_like(
        proof_bank_summary.get("source_theorem_proof_body_adapter_required")
    ):
        return True
    formal_counts = (
        formalization_manifest.get("counts", {})
        if isinstance(formalization_manifest, Mapping)
        and isinstance(formalization_manifest.get("counts", {}), Mapping)
        else {}
    )
    has_open_formal_work = int(formal_counts.get("formal_gap", 0) or 0) > 0
    if not has_open_formal_work:
        return False
    for row in agenda:
        owner = str(row.get("owner_subsystem", "") or "")
        agenda_id = str(row.get("id", "") or "")
        trigger = str(row.get("trigger", "") or "")
        if (
            "Formalizer" in owner
            or "ProofEngineer" in owner
            or agenda_id.startswith(("formal_gap:", "proof_feedback:"))
            or trigger.startswith(("SOURCE_THEOREM_", "SOURCE_TO_BRIDGE_"))
        ):
            return True
    return False


def _formalization_manifest_with_runtime_memory_summary(
    formalization_manifest: Mapping[str, Any],
    context: Mapping[str, Any],
) -> Mapping[str, Any]:
    memory = (
        context.get("runtime_learning_memory", {})
        if isinstance(context, Mapping)
        else {}
    )
    if not (
        isinstance(formalization_manifest, Mapping)
        and isinstance(memory, Mapping)
        and memory.get("artifact_kind") == "RuntimeLearningMemoryContext"
    ):
        return formalization_manifest
    proof_bank_obligation_catalog = [
        row
        for row in formalization_manifest.get(
            "registered_proof_bank_obligation_catalog", []
        )
        or []
        if isinstance(row, Mapping)
    ]
    theorem_goals = [
        row
        for row in formalization_manifest.get("deterministic_theorem_goals", [])
        or []
        if isinstance(row, Mapping)
    ]
    catalog_ids = tuple(
        str(row.get("obligation_id", "") or "").strip()
        for row in proof_bank_obligation_catalog
        if str(row.get("obligation_id", "") or "").strip()
    )
    memory_kernel_verified_ids = (
        _runtime_learning_memory_kernel_verified_proof_obligation_ids(
            context,
            catalog_ids=catalog_ids,
        )
    )
    memory_prioritized_ids, _off_catalog_ids, _rejected_ids = (
        _runtime_learning_memory_proof_obligation_ids(
            context,
            catalog_ids=catalog_ids,
        )
    )
    runtime_summary = _formalizer_proof_bank_runtime_memory_summary(
        context=context,
        proof_bank_obligation_catalog=proof_bank_obligation_catalog,
        theorem_goals=theorem_goals,  # type: ignore[arg-type]
        memory_kernel_verified_proof_obligation_ids=memory_kernel_verified_ids,
        memory_prioritized_proof_obligation_ids=memory_prioritized_ids,
    )
    existing_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    merged_manifest = dict(formalization_manifest)
    merged_manifest["proof_bank_runtime_memory_summary"] = {
        **dict(existing_summary),
        **runtime_summary,
    }
    return merged_manifest


def _critic_formal_blocker_resource_requests(
    *,
    formalization_manifest: Mapping[str, Any],
    agenda: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Turn formal blocker rows into typed retriever/prover resource requests."""

    if not isinstance(formalization_manifest, Mapping):
        return []
    target_ids = [
        str(row.get("id", "") or "").strip()
        for row in formalization_manifest.get("deterministic_theorem_goals", []) or []
        if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
    ]
    request_rows: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_request(
        *,
        source: str,
        blocker_kind: str,
        blocker: str,
        next_owner: str,
        target_ids_override: Sequence[Any] = (),
    ) -> None:
        blocker = blocker.strip()
        blocker_kind = blocker_kind.strip() or "formal_blocker"
        if not blocker:
            return
        fingerprint = stable_hash([source, blocker_kind, blocker, next_owner])[:20]
        if fingerprint in seen:
            return
        seen.add(fingerprint)
        request_rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": source,
                "blocker_kind": blocker_kind,
                "blocker": blocker,
                "next_owner": next_owner.strip() or "Formalizer/ProofEngineer",
                "target_ids": [
                    str(value).strip()
                    for value in (target_ids_override or target_ids)
                    if str(value).strip()
                ],
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids_override or target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Retrieve or identify a verified local declaration/import, "
                    "formalize a smaller semantic primitive, or keep the theorem as "
                    "FORMAL_GAP with the exact missing API/definition named. Do not "
                    "emit an executable candidate that reuses an unresolved blocker."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )

    for row in formalization_manifest.get("llm_formalizer_gap_taxonomy", []) or []:
        if not isinstance(row, Mapping):
            continue
        add_request(
            source="llm_formalizer_gap_taxonomy",
            blocker_kind=str(row.get("kind", "") or ""),
            blocker=str(row.get("gap", "") or ""),
            next_owner=str(row.get("next_owner", "") or ""),
        )

    proof_bank_memory_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    if proof_bank_memory_summary.get(
        "source_theorem_candidate_materialization_required", False
    ):
        materialization_targets = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required_target_names",
                [],
            )
            or []
            if str(value).strip()
        ]
        materialization_target_ids = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required_target_ids",
                [],
            )
            or []
            if str(value).strip()
        ]
        materialization_statuses = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_required_statuses",
                [],
            )
            or []
            if str(value).strip()
        ]
        missing_symbols = [
            str(value).strip()
            for value in proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_missing_formal_symbols",
                [],
            )
            or []
            if str(value).strip()
        ]
        materialization_contract = str(
            proof_bank_memory_summary.get(
                "source_theorem_candidate_materialization_contract", ""
            )
            or ""
        ).strip()
        blocker_parts = [
            materialization_contract
            or (
                "Materialize an exact source-theorem Lean candidate artifact "
                "before signature probes or proof-body execution can run."
            ),
        ]
        if materialization_statuses:
            blocker_parts.append(
                "signature_probe_statuses="
                + ", ".join(materialization_statuses[:4])
            )
        if missing_symbols:
            blocker_parts.append(
                "missing_formal_symbols=" + ", ".join(missing_symbols[:8])
            )
        add_request(
            source="proof_bank_runtime_memory_summary",
            blocker_kind="SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED",
            blocker="; ".join(blocker_parts),
            next_owner="Formalizer/ProofEngineer/LeanProver",
            target_ids_override=materialization_target_ids
            or materialization_targets,
        )

    for row in agenda:
        if not isinstance(row, Mapping):
            continue
        trigger = str(row.get("trigger", "") or "")
        agenda_id = str(row.get("id", "") or "")
        owner = str(row.get("owner_subsystem", "") or "")
        if not (
            agenda_id.startswith("formal_gap:")
            or trigger.startswith(("SOURCE_", "FORMAL_GAP", "POST_RUNTIME_PROOF"))
            or "ProofEngineer" in owner
            or "LeanProver" in owner
        ):
            continue
        add_request(
            source="critic_next_action_agenda",
            blocker_kind=trigger or agenda_id,
            blocker=str(row.get("action", "") or ""),
            next_owner=owner,
            target_ids_override=[
                str(value).strip()
                for value in row.get("target_ids", []) or []
                if str(value).strip()
            ],
        )

    return request_rows[:FORMAL_BLOCKER_RESOURCE_REQUEST_LIMIT]


def _formal_blocker_resource_request_queries(
    blocker: str,
    *,
    blocker_kind: str,
    target_ids: Sequence[Any],
) -> list[str]:
    target_text = " ".join(str(value).strip() for value in target_ids if str(value).strip())
    base = " ".join(part for part in (blocker_kind, blocker, target_text) if part).strip()
    queries: list[str] = []
    if base:
        queries.append(base)
    identifier_pattern = re.compile(
        r"`([^`]+)`|\b([A-Za-z_][A-Za-z0-9_'.]*\.[A-Za-z0-9_'.]+)\b"
    )
    for match in identifier_pattern.finditer(blocker):
        identifier = str(match.group(1) or match.group(2) or "").strip()
        query = f"{identifier} Lean declaration" if identifier else ""
        if query and query not in queries:
            queries.append(query)
    for phrase in re.findall(r"\b[A-Z][A-Za-z0-9_]*(?:[A-Z][A-Za-z0-9_]*)+\b", blocker):
        query = f"{phrase} Lean definition"
        if query not in queries:
            queries.append(query)
    return queries[:5]


def _lean_import_modules_from_artifact_path(artifact_path: str) -> list[str]:
    path_text = str(artifact_path or "").strip()
    if not path_text:
        return []
    path = Path(path_text)
    if not path.exists() or not path.is_file():
        return []
    try:
        source = path.read_text(encoding="utf-8")
    except OSError:
        return []
    imports: list[str] = []
    seen: set[str] = set()
    for line in source.splitlines()[:80]:
        match = re.match(r"^\s*import\s+(?P<modules>.+?)\s*$", line)
        if not match:
            continue
        for module in match.group("modules").split():
            module = module.strip()
            if module and module not in seen:
                seen.add(module)
                imports.append(module)
    return imports[:8]


def _formal_blocker_resource_requests_from_source_theorem_proof_body_adapter_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Convert adapter bridge residuals into typed prover/RAG work requests."""

    if not isinstance(feedback, Mapping):
        return []
    diagnostics = [
        row
        for row in feedback.get("diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    if not diagnostics:
        return []
    default_targets = [
        str(value).strip()
        for value in feedback.get("target_names", []) or []
        if str(value).strip()
    ]
    rows: list[dict[str, Any]] = []
    for diagnostic in diagnostics[:4]:
        if _bool_like(diagnostic.get("adapter_kernel_verified", False)):
            continue
        target_ids = [
            str(value).strip()
            for value in [
                diagnostic.get("target_theorem_name", ""),
                *default_targets,
            ]
            if str(value).strip()
        ]
        target_ids = list(dict.fromkeys(target_ids))
        failure = str(diagnostic.get("failure_classification", "") or "").strip()
        artifact_path = str(
            diagnostic.get("adapter_candidate_artifact_path", "") or ""
        ).strip()
        declaration = str(diagnostic.get("adapter_declaration_name", "") or "").strip()
        diagnostic_lines = [
            str(value)
            for value in diagnostic.get("diagnostics", []) or []
            if str(value).strip()
        ]
        diagnostic_text = "\n".join(diagnostic_lines)
        unavailable_import = str(
            diagnostic.get("unavailable_import", "") or ""
        ).strip()
        candidate_imports = [
            str(value).strip()
            for value in diagnostic.get("adapter_candidate_imports", []) or []
            if str(value).strip()
        ]
        exact_import_prefixes = [unavailable_import] if unavailable_import else []
        candidate_import_prefixes = list(dict.fromkeys(candidate_imports))
        candidate_import_source = (
            "adapter_candidate_imports" if candidate_import_prefixes else ""
        )
        if (
            not exact_import_prefixes
            and not candidate_import_prefixes
            and failure == "adapter_lean_import_environment_missing"
        ):
            candidate_import_prefixes = _lean_import_modules_from_artifact_path(
                artifact_path
            )
            if candidate_import_prefixes:
                candidate_import_source = "adapter_candidate_artifact_imports"
        import_requests: list[tuple[str, bool]] = [
            (module, True)
            for module in list(dict.fromkeys(exact_import_prefixes))[:2]
        ]
        if not import_requests:
            import_requests = [
                (module, False)
                for module in list(dict.fromkeys(candidate_import_prefixes))[:4]
            ]
        if import_requests:
            for module, exact_unavailable in import_requests:
                blocker_kind = (
                    "source_theorem_proof_body_adapter_unavailable_import"
                    if exact_unavailable
                    else "source_theorem_proof_body_adapter_candidate_import_resolution"
                )
                blocker = (
                    f"{module} unavailable import while checking source-theorem "
                    "proof-body adapter"
                    if exact_unavailable
                    else f"{module} appears in a source-theorem proof-body "
                    "adapter candidate whose import diagnostic was truncated"
                )
                if declaration:
                    blocker += f" `{declaration}`"
                if artifact_path and not exact_unavailable:
                    blocker += f" at {artifact_path}"
                fingerprint = stable_hash(
                    [
                        "critic_source_theorem_proof_body_adapter_feedback",
                        blocker_kind,
                        module,
                        exact_unavailable,
                        target_ids,
                        "" if exact_unavailable else artifact_path,
                    ]
                )[:20]
                formal_source_queries = [
                    f"{module} Lean import",
                    *_formal_blocker_resource_request_queries(
                        blocker,
                        blocker_kind=blocker_kind,
                        target_ids=target_ids,
                    ),
                ]
                rows.append(
                    {
                        "request_id": (
                            f"formal_blocker_resource_request:{fingerprint}"
                        ),
                        "source": (
                            "critic_source_theorem_proof_body_adapter_feedback"
                        ),
                        "blocker_kind": blocker_kind,
                        "blocker": blocker,
                        "next_owner": "Formalizer/ProofEngineer/LeanProver",
                        "target_ids": target_ids,
                        "unavailable_import": module if exact_unavailable else "",
                        "candidate_import": "" if exact_unavailable else module,
                        "unavailable_import_exact": exact_unavailable,
                        "import_resolution_source": (
                            "adapter_unavailable_import_diagnostic"
                            if exact_unavailable
                            else candidate_import_source
                        ),
                        "adapter_candidate_artifact_paths": (
                            [artifact_path] if artifact_path else []
                        ),
                        "adapter_declaration_name": declaration,
                        "formal_source_queries": list(
                            dict.fromkeys(formal_source_queries)
                        )[:5],
                        "recommended_tools": [
                            "formal_source_retriever",
                            "lean_lsp_mcp_when_configured",
                            "local_lean_or_axle",
                        ],
                        "required_resolution": (
                            "Replace the unavailable adapter import with a verified "
                            "local import/declaration, derive a smaller source-to-bridge "
                            "primitive, or keep the adapter/source theorem as FORMAL_GAP. "
                            "Do not repeat the unresolved import."
                            if exact_unavailable
                            else (
                                "Use formal-source retrieval, Lean LSP/MCP, or local "
                                "Lean to determine whether this candidate import is "
                                "available in the configured project and recover the "
                                "exact unavailable module before retrying the adapter."
                            )
                        ),
                        "proof_evidence_status": (
                            "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                        ),
                        "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
                    }
                )
            continue
        blocker_parts = [
            "Source-theorem proof-body adapter did not produce kernel-verified "
            "adapter evidence"
        ]
        if failure:
            blocker_parts.append(f"failure_classification={failure}")
        if declaration:
            blocker_parts.append(f"adapter_declaration={declaration}")
        if artifact_path:
            blocker_parts.append(f"artifact={artifact_path}")
        if diagnostic_lines:
            blocker_parts.append("diagnostic=" + diagnostic_lines[0][:320])
        blocker = "; ".join(blocker_parts)
        fingerprint = stable_hash(
            [
                "critic_source_theorem_proof_body_adapter_feedback",
                failure or "source_theorem_proof_body_adapter_unverified",
                target_ids,
                artifact_path,
                declaration,
            ]
        )[:20]
        rows.append(
            {
                "request_id": f"formal_blocker_resource_request:{fingerprint}",
                "source": "critic_source_theorem_proof_body_adapter_feedback",
                "blocker_kind": (
                    failure or "source_theorem_proof_body_adapter_unverified"
                ),
                "blocker": blocker,
                "next_owner": "Formalizer/ProofEngineer/LeanProver",
                "target_ids": target_ids,
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=(
                        failure or "source_theorem_proof_body_adapter_unverified"
                    ),
                    target_ids=target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Strengthen the source-to-bridge adapter by deriving bridge "
                    "premises from exact source hypotheses, retrieve/prove any "
                    "missing smaller primitive, rerun local Lean/AXLE, or keep the "
                    "source theorem as FORMAL_GAP with the adapter blocker named."
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_exact_semantic_definition_repair_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Convert exact semantic-definition review blockers into typed RAG/prover work."""

    if not isinstance(feedback, Mapping):
        return []
    if not feedback.get("source_theorem_exact_semantic_definition_repair_required"):
        return []
    default_targets = [
        str(value).strip()
        for value in feedback.get("target_names", []) or []
        if str(value).strip()
    ]
    diagnostics = [
        row
        for row in feedback.get("diagnostics", []) or []
        if isinstance(row, Mapping)
    ]
    if not diagnostics:
        diagnostics = [
            {
                "target_theorem_name": target,
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                ),
            }
            for target in default_targets[:3]
        ] or [
            {
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                )
            }
        ]
    rows: list[dict[str, Any]] = []
    for diagnostic in diagnostics[:8]:
        target_ids = [
            str(value).strip()
            for value in [
                diagnostic.get("target_theorem_name", ""),
                *default_targets,
            ]
            if str(value).strip()
        ]
        target_ids = list(dict.fromkeys(target_ids))
        failure = str(diagnostic.get("failure_classification", "") or "").strip()
        trigger = str(diagnostic.get("trigger", "") or "").strip()
        placeholder_symbol = str(
            diagnostic.get("placeholder_symbol", "") or ""
        ).strip()
        gate = str(diagnostic.get("proof_body_gate_status", "") or "").strip()
        runtime_queue_status = str(
            diagnostic.get("runtime_queue_status", "") or ""
        ).strip()
        environment_repair_status = str(
            diagnostic.get("environment_repair_status", "") or ""
        ).strip()
        candidate_lean_project_hint = str(
            diagnostic.get("candidate_lean_project_hint", "") or ""
        ).strip()
        candidate_source_file = str(
            diagnostic.get("candidate_source_file", "") or ""
        ).strip()
        unavailable_module_prefix = str(
            diagnostic.get("unavailable_module_prefix", "") or ""
        ).strip()
        recommended_next_action = str(
            diagnostic.get("recommended_next_action", "") or ""
        ).strip()
        recommended_commands = [
            str(value).strip()
            for value in diagnostic.get("recommended_commands", []) or []
            if str(value).strip()
        ]
        definition_only_candidate_path = str(
            diagnostic.get("definition_only_candidate_artifact_path", "") or ""
        ).strip()
        nested_typechecked_candidate = diagnostic.get(
            "source_theorem_exact_semantic_definition_typechecked_candidate",
            {},
        )
        if not isinstance(nested_typechecked_candidate, Mapping):
            nested_typechecked_candidate = {}
        if not definition_only_candidate_path:
            definition_only_candidate_path = str(
                nested_typechecked_candidate.get(
                    "definition_only_candidate_artifact_path", ""
                )
                or ""
            ).strip()
        candidate_path = str(
            diagnostic.get("candidate_artifact_path", "")
            or nested_typechecked_candidate.get("candidate_artifact_path", "")
            or definition_only_candidate_path
            or ""
        ).strip()
        semantic_blockers = [
            str(value).strip()
            for value in diagnostic.get("semantic_alignment_blockers", []) or []
            if str(value).strip()
        ]
        adapter_ids = [
            str(value).strip()
            for value in (
                diagnostic.get(
                    "kernel_verified_source_theorem_proof_body_adapter_ids",
                    [],
                )
                or feedback.get(
                    "kernel_verified_source_theorem_proof_body_adapter_ids",
                    [],
                )
                or []
            )
            if str(value).strip()
        ]
        blocker_parts = [
            "Exact source-theorem proof-body execution is blocked until exact "
            "semantic definitions are reviewed, imported, or kernel-verified"
        ]
        if placeholder_symbol:
            blocker_parts.append(f"placeholder_symbol={placeholder_symbol}")
        if failure:
            blocker_parts.append(f"failure_classification={failure}")
        if gate:
            blocker_parts.append(f"proof_body_gate_status={gate}")
        if runtime_queue_status:
            blocker_parts.append(f"runtime_queue_status={runtime_queue_status}")
        if environment_repair_status:
            blocker_parts.append(
                f"environment_repair_status={environment_repair_status}"
            )
        if unavailable_module_prefix:
            blocker_parts.append(
                f"unavailable_module_prefix={unavailable_module_prefix}"
            )
        if candidate_lean_project_hint:
            blocker_parts.append(
                f"candidate_lean_project_hint={candidate_lean_project_hint}"
            )
        if candidate_source_file:
            blocker_parts.append(f"candidate_source_file={candidate_source_file}")
        if recommended_next_action:
            blocker_parts.append(
                f"recommended_next_action={recommended_next_action}"
            )
        if candidate_path:
            blocker_parts.append(f"candidate_artifact={candidate_path}")
        if recommended_commands:
            blocker_parts.append(
                "recommended_commands=" + ", ".join(recommended_commands[:3])
            )
        if semantic_blockers:
            blocker_parts.append(
                "semantic_alignment_blockers="
                + ", ".join(semantic_blockers[:4])
            )
        if adapter_ids:
            blocker_parts.append(
                "verified_adapter_context_ids=" + ", ".join(adapter_ids[:4])
            )
        blocker = "; ".join(blocker_parts)
        blocker_kind = (
            environment_repair_status
            or failure
            or trigger
            or "source_theorem_exact_semantic_definition_repair_required"
        )
        fingerprint = stable_hash(
            [
                "critic_source_theorem_exact_semantic_definition_repair_feedback",
                blocker_kind,
                placeholder_symbol,
                gate,
                environment_repair_status,
                unavailable_module_prefix,
                candidate_lean_project_hint,
                candidate_source_file,
                target_ids,
                semantic_blockers,
            ]
        )[:20]
        request_id = f"formal_blocker_resource_request:{fingerprint}"
        rows.append(
            {
                "request_id": request_id,
                "request_fingerprint": fingerprint,
                "source": (
                    "critic_source_theorem_exact_semantic_definition_repair_feedback"
                ),
                "blocker_kind": blocker_kind,
                "failure_classification": failure,
                "trigger": trigger,
                "placeholder_symbol": placeholder_symbol,
                "proof_body_gate_status": gate,
                "runtime_queue_status": runtime_queue_status,
                "environment_repair_status": environment_repair_status,
                "candidate_lean_project_hint": candidate_lean_project_hint,
                "candidate_source_file": candidate_source_file,
                "unavailable_module_prefix": unavailable_module_prefix,
                "recommended_next_action": recommended_next_action,
                "recommended_commands": recommended_commands,
                "blocker": blocker,
                "next_owner": "TheoryDeveloper/Formalizer/ProofEngineer/LeanProver",
                "target_ids": target_ids,
                "candidate_artifact_path": candidate_path,
                "definition_only_candidate_artifact_path": (
                    definition_only_candidate_path
                ),
                "semantic_alignment_blockers": semantic_blockers,
                "verified_adapter_context_ids": adapter_ids[:5],
                "formal_source_queries": _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids,
                ),
                "recommended_tools": [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ],
                "required_resolution": (
                    "Repair the selected Lean project/source-root/import-prefix "
                    "mapping for this exact semantic definition before retrying "
                    "proof-body tactics. A verified adapter may be consumed as "
                    "context, but source-theorem proof evidence requires local "
                    "Lean/AXLE verification of the exact declaration."
                    if environment_repair_status
                    else (
                        "Resolve the exact source-theorem semantic definitions and "
                        "target provenance before retrying proof-body tactics. A verified "
                        "adapter may be consumed as context, but source-theorem proof "
                        "evidence requires local Lean/AXLE verification of the exact "
                        "declaration."
                    )
                ),
                "proof_evidence_status": (
                    "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                ),
                "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
            }
        )
    return rows


def _formal_blocker_resource_requests_from_feedback(
    feedback: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    """Carry prior typed blocker requests across repair loops."""

    if not isinstance(feedback, Mapping):
        return []
    return _merge_formal_blocker_resource_requests(
        [
            row
            for row in feedback.get("formal_blocker_resource_requests", []) or []
            if isinstance(row, Mapping)
        ]
    )


def _formal_blocker_target_ids_from_manifest_and_diagnostics(
    manifest: Mapping[str, Any],
    diagnostics: Sequence[Mapping[str, Any]],
) -> list[str]:
    question = (
        manifest.get("question", {})
        if isinstance(manifest.get("question", {}), Mapping)
        else {}
    )
    explicit_target_ids = list(
        dict.fromkeys(
            target_id
            for source_row in (manifest, *diagnostics)
            if isinstance(source_row, Mapping)
            for target_id in _source_theorem_explicit_target_ids_from_row(source_row)
        )
    )
    deterministic_goal_ids = [
        str(row.get("id", "") or "").strip()
        for row in manifest.get("deterministic_theorem_goals", []) or []
        if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
    ]
    diagnostic_target_names = [
        str(row.get("target_lean_declaration", "") or "").strip()
        for row in diagnostics
        if isinstance(row, Mapping)
        and str(row.get("target_lean_declaration", "") or "").strip()
    ]
    question_target_ids = [
        str(question.get("id", "") or "").strip()
    ] if str(question.get("id", "") or "").strip() else []
    return list(
        dict.fromkeys(
            explicit_target_ids
            or deterministic_goal_ids
            or diagnostic_target_names
            or question_target_ids
        )
    )


def _exact_semantic_formal_blocker_request_key(
    row: Mapping[str, Any],
) -> tuple[str, tuple[str, ...]] | None:
    if (
        str(row.get("source", "") or "")
        != "critic_source_theorem_exact_semantic_definition_repair_feedback"
    ):
        return None
    placeholder_symbol = str(row.get("placeholder_symbol", "") or "").strip()
    if not placeholder_symbol:
        return None
    target_ids = tuple(
        str(value).strip()
        for value in row.get("target_ids", []) or []
        if str(value).strip()
    )
    return (placeholder_symbol, target_ids)


def _exact_semantic_formal_blocker_requests_overlap(
    existing: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    existing_key = _exact_semantic_formal_blocker_request_key(existing)
    candidate_key = _exact_semantic_formal_blocker_request_key(candidate)
    if existing_key is None or candidate_key is None:
        return False
    existing_placeholder, existing_targets = existing_key
    candidate_placeholder, candidate_targets = candidate_key
    if existing_placeholder != candidate_placeholder:
        return False
    return (
        existing_targets == candidate_targets
        or not existing_targets
        or not candidate_targets
    )


def _exact_semantic_formal_blocker_request_is_stronger(
    existing: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    existing_score = _exact_semantic_environment_repair_evidence_score(existing)
    candidate_score = _exact_semantic_environment_repair_evidence_score(candidate)
    if candidate_score != existing_score:
        return candidate_score > existing_score
    existing_key = _exact_semantic_formal_blocker_request_key(existing)
    candidate_key = _exact_semantic_formal_blocker_request_key(candidate)
    existing_targets = existing_key[1] if existing_key is not None else ()
    candidate_targets = candidate_key[1] if candidate_key is not None else ()
    return bool(candidate_targets) and not existing_targets


def _dedupe_exact_semantic_formal_blocker_resource_requests(
    requests: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    rows = [dict(row) for row in requests if isinstance(row, Mapping)]
    retained: list[dict[str, Any]] = []
    for row in rows:
        if _exact_semantic_formal_blocker_request_key(row) is None:
            retained.append(row)
            continue
        existing_index = next(
            (
                index
                for index, existing in enumerate(retained)
                if _exact_semantic_formal_blocker_requests_overlap(existing, row)
            ),
            None,
        )
        if existing_index is None:
            retained.append(row)
            continue
        existing = retained[existing_index]
        if _exact_semantic_formal_blocker_request_is_stronger(existing, row):
            retained[existing_index] = row
    return retained


def _merge_formal_blocker_resource_requests(
    *request_groups: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Normalize, fill defaults, and deduplicate formal blocker requests."""

    merged: list[dict[str, Any]] = []
    seen: set[str] = set()
    for group in request_groups:
        for row in group or []:
            if not isinstance(row, Mapping):
                continue
            blocker = str(row.get("blocker", "") or "").strip()
            blocker_kind = str(row.get("blocker_kind", "") or "").strip()
            request_id = str(row.get("request_id", "") or "").strip()
            if not blocker and not request_id:
                continue
            source = str(row.get("source", "") or "").strip() or "formal_blocker"
            next_owner = (
                str(row.get("next_owner", "") or "").strip()
                or "Formalizer/ProofEngineer"
            )
            target_ids = [
                str(value).strip()
                for value in row.get("target_ids", []) or []
                if str(value).strip()
            ]
            if not blocker_kind:
                blocker_kind = "formal_blocker"
            if not request_id:
                request_id = (
                    "formal_blocker_resource_request:"
                    + stable_hash([source, blocker_kind, blocker, next_owner])[:20]
                )
            fingerprint = stable_hash([request_id, source, blocker_kind, blocker])[:20]
            if fingerprint in seen:
                continue
            seen.add(fingerprint)
            formal_source_queries = [
                str(query).strip()
                for query in row.get("formal_source_queries", []) or []
                if str(query).strip()
            ]
            if not formal_source_queries and blocker:
                formal_source_queries = _formal_blocker_resource_request_queries(
                    blocker,
                    blocker_kind=blocker_kind,
                    target_ids=target_ids,
                )
            recommended_tools = [
                str(tool).strip()
                for tool in row.get("recommended_tools", []) or []
                if str(tool).strip()
            ]
            if not recommended_tools:
                recommended_tools = [
                    "formal_source_retriever",
                    "proof_search",
                    "lean_lsp_mcp_when_configured",
                    "local_lean_or_axle",
                ]
            merged.append(
                {
                    **dict(row),
                    "request_id": request_id,
                    "source": source,
                    "blocker_kind": blocker_kind,
                    "blocker": blocker,
                    "next_owner": next_owner,
                    "target_ids": target_ids,
                    "formal_source_queries": formal_source_queries[:5],
                    "recommended_tools": list(dict.fromkeys(recommended_tools)),
                    "required_resolution": str(
                        row.get("required_resolution", "") or ""
                    )
                    or (
                        "Retrieve or identify a verified local declaration/import, "
                        "formalize a smaller semantic primitive, or keep the theorem "
                        "as FORMAL_GAP with the exact missing resource named."
                    ),
                    "proof_evidence_status": (
                        "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
                    ),
                    "proof_evidence_boundary": KERNEL_PROOF_BOUNDARY,
                }
            )
            if len(merged) >= FORMAL_BLOCKER_RESOURCE_REQUEST_LIMIT:
                return _dedupe_exact_semantic_formal_blocker_resource_requests(merged)
    return _dedupe_exact_semantic_formal_blocker_resource_requests(merged)


def _compact_agenda_item(row: Mapping[str, Any]) -> dict[str, Any]:
    compact = {
        "id": str(row.get("id", "")),
        "owner_subsystem": str(row.get("owner_subsystem", "")),
        "trigger": str(row.get("trigger", "")),
        "action": str(row.get("action", "")),
        "acceptance_gate": str(row.get("acceptance_gate", "")),
        "priority": str(row.get("priority", "")),
    }
    for key in (
        "target_ids",
        "runtime_queue_status",
        "source_to_bridge_metadata_blocker_status",
        "source_to_bridge_metadata_blocker_kind",
        "diagnostic_helper_candidate_ids",
        "source_formalizer_packet_id",
        "recommended_formalizer_target_mode",
        "failure_classifications",
        "proof_body_gate_statuses",
        "semantic_alignment_blockers",
    ):
        if key in row:
            compact[key] = row.get(key)
    return compact


def _compact_formal_subclaim_feedback(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "id": str(row.get("id", "")),
        "claim_type": str(row.get("claim_type", "")),
        "status": str(row.get("status", "")),
        "kernel_verified": _bool_like(row.get("kernel_verified", False)),
        "gap_reason": str(row.get("gap_reason", "")),
        "errors": list(row.get("errors", []) or [])[:3],
        "proof_dependencies": list(row.get("proof_dependencies", []) or [])[:5],
    }


def _architect_runtime_plan(context: Mapping[str, Any]) -> dict[str, Any]:
    plan = context.get("architect_runtime_plan")
    if isinstance(plan, Mapping):
        return dict(plan)
    contract = context.get("runtime_requested_evidence_contract")
    if isinstance(contract, Mapping) and contract:
        return {
            "subsystem_execution_plan": [],
            "evidence_contract": dict(contract),
            "evidence_gates": [
                {
                    "artifact_kind": "runtime requested evidence contract",
                    "required_evidence": (
                        "follow formal_verification_policy and "
                        "recommended_research_path until an Architect packet "
                        "overrides them"
                    ),
                    "not_evidence": (
                        "requested policy/path is orchestration control, not "
                        "proof, simulation, or implementation evidence"
                    ),
                }
            ],
            "boundary": (
                "Runtime requested evidence contract is orchestration control "
                "metadata. It does not prove or validate any statistical claim "
                "and must not replace live Architect reasoning in capability "
                "evaluations."
            ),
        }
    return {}


def _architect_subsystem_plan(context: Mapping[str, Any], subsystem: str) -> dict[str, Any]:
    plan = _architect_runtime_plan(context)
    for row in plan.get("subsystem_execution_plan", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("subsystem", "")).strip() == subsystem:
            return dict(row)
    return {}


def _architect_acceptance_gate(
    context: Mapping[str, Any],
    subsystem: str,
    default: str,
) -> str:
    row = _architect_subsystem_plan(context, subsystem)
    gate = str(row.get("acceptance_gate", "")).strip()
    return gate or default


def _architect_expected_artifacts(
    context: Mapping[str, Any],
    subsystem: str,
    default: tuple[str, ...],
) -> tuple[str, ...]:
    row = _architect_subsystem_plan(context, subsystem)
    artifacts = [
        str(item).strip()
        for item in row.get("expected_artifacts", []) or []
        if str(item).strip()
    ]
    return tuple(artifacts) if artifacts else default


def _architect_control_payload(context: Mapping[str, Any], subsystem: str) -> dict[str, Any]:
    plan = _architect_runtime_plan(context)
    row = deepcopy(_architect_subsystem_plan(context, subsystem))
    if not plan and not row:
        return {}
    evidence_gates = [
        deepcopy(dict(item))
        for item in plan.get("evidence_gates", []) or []
        if isinstance(item, Mapping)
    ]
    iteration_policy = plan.get("iteration_policy", {})
    retrieval_strategy = plan.get("retrieval_strategy", {})
    problem_analysis = plan.get("problem_analysis", {})
    knowledge_bank_plan = plan.get("stat_knowledge_bank_plan", {})
    fair_comparison_plan = plan.get("literature_fair_comparison_plan", [])
    evidence_contract = plan.get("evidence_contract", {})
    if not isinstance(evidence_contract, Mapping):
        evidence_contract = {}
    return {
        "architect_coordinator_proposal_id": str(
            context.get("architect_coordinator_proposal_id", "")
        ),
        "subsystem": subsystem,
        "subsystem_plan": deepcopy(row),
        "acceptance_gate": str(row.get("acceptance_gate", "")).strip(),
        "expected_artifacts": [
            str(item).strip()
            for item in row.get("expected_artifacts", []) or []
            if str(item).strip()
        ],
        "evidence_gates": evidence_gates,
        "iteration_policy": deepcopy(dict(iteration_policy)) if isinstance(iteration_policy, Mapping) else {},
        "retrieval_strategy": deepcopy(dict(retrieval_strategy)) if isinstance(retrieval_strategy, Mapping) else {},
        "problem_analysis": deepcopy(dict(problem_analysis)) if isinstance(problem_analysis, Mapping) else {},
        "stat_knowledge_bank_plan": deepcopy(dict(knowledge_bank_plan)) if isinstance(knowledge_bank_plan, Mapping) else {},
        "literature_fair_comparison_plan": [
            deepcopy(dict(item))
            for item in fair_comparison_plan
            if isinstance(item, Mapping)
        ],
        "evidence_contract": deepcopy(dict(evidence_contract)),
        "formal_verification_policy": str(
            evidence_contract.get("formal_verification_policy", "") or ""
        ),
        "recommended_research_path": str(
            evidence_contract.get("recommended_research_path", "") or ""
        ),
        "formal_required_for_final": _bool_like(
            evidence_contract.get("formal_required_for_final", False)
        ),
        "boundary": str(plan.get("boundary", "")),
    }


def _runtime_environment_feedback_with_architect_directive(
    *,
    context: Mapping[str, Any],
    subsystem: str,
    feedback: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    payload = dict(feedback) if isinstance(feedback, Mapping) else {}
    empirical_evaluation_phase = str(
        context.get("empirical_evaluation_phase", "") or ""
    ).strip()
    if empirical_evaluation_phase:
        payload.setdefault(
            "empirical_evaluation_phase",
            empirical_evaluation_phase,
        )
    runtime_task = context.get("runtime_task", {})
    if isinstance(runtime_task, Mapping) and runtime_task:
        payload.setdefault("runtime_task", dict(runtime_task))
    requested_contract = context.get("runtime_requested_evidence_contract", {})
    if isinstance(requested_contract, Mapping) and requested_contract:
        payload.setdefault("runtime_requested_evidence_contract", dict(requested_contract))
    architect_contract = context.get("architect_evidence_contract", {})
    if isinstance(architect_contract, Mapping) and architect_contract:
        payload.setdefault("architect_evidence_contract", dict(architect_contract))
    control = _architect_control_payload(context, subsystem)
    if not control:
        return payload
    evidence_contract = control.get("evidence_contract", {})
    if isinstance(evidence_contract, Mapping) and evidence_contract:
        payload.setdefault("architect_evidence_contract", dict(evidence_contract))
    for key in (
        "formal_verification_policy",
        "recommended_research_path",
        "formal_required_for_final",
    ):
        if control.get(key) not in (None, "", [], {}):
            payload.setdefault(f"architect_{key}", control.get(key))
    if control.get("acceptance_gate"):
        payload.setdefault(
            "architect_subsystem_acceptance_gate",
            str(control.get("acceptance_gate", "")),
        )
    return payload


def _runtime_algorithm_sandbox_feedback_from_learning_memory(
    architect_context: Mapping[str, Any],
    question_id: str,
) -> dict[str, Any]:
    feedback = _runtime_feedback_from_learning_memory(
        architect_context,
        question_id,
        learning_task="algorithm_sandbox_execution_feedback",
        feedback_type="algorithm_sandbox_execution_feedback",
    )
    if feedback:
        return _runtime_environment_feedback_with_theory_trace_downstream_alignment(
            feedback,
            architect_context,
            question_id,
            target_consumer_subsystem="AlgorithmEngineer",
        )
    feedback = _runtime_coding_agent_capability_feedback_from_learning_memory(
        architect_context,
        question_id,
        target_component="algorithm",
        capability_ids=(
            "generated_algorithm_code_executed_locally",
            "generated_algorithm_failure_feedback_closed",
        ),
    )
    if feedback:
        return _runtime_environment_feedback_with_theory_trace_downstream_alignment(
            feedback,
            architect_context,
            question_id,
            target_consumer_subsystem="AlgorithmEngineer",
        )
    feedback = _runtime_coding_agent_component_gate_feedback_from_learning_memory(
        architect_context,
        question_id,
        target_component="algorithm",
    )
    return _runtime_environment_feedback_with_theory_trace_downstream_alignment(
        feedback,
        architect_context,
        question_id,
        target_consumer_subsystem="AlgorithmEngineer",
    )


