def _runtime_formalizer_lean_candidate_revision_max_attempts(
    context: Mapping[str, Any],
    environment_feedback: Mapping[str, Any] | None = None,
) -> int:
    configured = _runtime_positive_int_from_contract_sources(
        (context, environment_feedback),
        key="capability_eval_formalizer_lean_candidate_revision_max_attempts",
    )
    if configured > 0:
        return configured
    return _runtime_positive_int_from_contract_sources(
        (context, environment_feedback),
        key=(
            "capability_eval_formalizer_lean_candidate_repair_"
            "yield_to_gap_planner_after_attempts"
        ),
    )


def _runtime_context_with_reset_candidate_regenerations(
    context: Mapping[str, Any],
) -> dict[str, Any]:
    updated = dict(context)
    loop = context.get("runtime_feedback_loop", {})
    if not isinstance(loop, Mapping):
        return updated
    reset_loop = dict(loop)
    for key in (
        "algorithm_engineer_generated_code_repair_attempts_used",
        "algorithm_engineer_generated_code_repair_turns",
        "algorithm_engineer_generated_code_repair_theory_packet_id",
        "simulation_evaluator_generated_code_repair_attempts_used",
        "simulation_evaluator_generated_code_repair_turns",
        "simulation_evaluator_generated_code_repair_theory_packet_id",
    ):
        reset_loop.pop(key, None)
    updated["runtime_feedback_loop"] = reset_loop
    return updated


def _runtime_algorithm_engineer_candidate_regenerations_used(
    context: Mapping[str, Any],
    *,
    theory_packet_id: str = "",
) -> int:
    loop = context.get("runtime_feedback_loop", {})
    if not isinstance(loop, Mapping):
        return 0
    regeneration_theory_packet_id = str(
        loop.get(
            "algorithm_engineer_generated_code_repair_theory_packet_id",
            "",
        )
        or ""
    )
    if (
        theory_packet_id
        and regeneration_theory_packet_id
        and regeneration_theory_packet_id != theory_packet_id
    ):
        return 0
    for key in (
        "algorithm_engineer_generated_code_repair_attempts_used",
        "algorithm_engineer_generated_code_repair_turns",
    ):
        try:
            return max(0, int(loop.get(key, 0) or 0))
        except (TypeError, ValueError):
            continue
    return 0


def _runtime_simulation_evaluator_candidate_regenerations_used(
    context: Mapping[str, Any],
    *,
    theory_packet_id: str = "",
) -> int:
    loop = context.get("runtime_feedback_loop", {})
    if not isinstance(loop, Mapping):
        return 0
    regeneration_theory_packet_id = str(
        loop.get(
            "simulation_evaluator_generated_code_repair_theory_packet_id",
            "",
        )
        or ""
    )
    if (
        theory_packet_id
        and regeneration_theory_packet_id
        and regeneration_theory_packet_id != theory_packet_id
    ):
        return 0
    for key in (
        "simulation_evaluator_generated_code_repair_attempts_used",
        "simulation_evaluator_generated_code_repair_turns",
    ):
        try:
            return max(0, int(loop.get(key, 0) or 0))
        except (TypeError, ValueError):
            continue
    return 0


def _runtime_requires_generated_simulation_code(
    context: Mapping[str, Any],
    environment_feedback: Mapping[str, Any] | None = None,
) -> bool:
    return _runtime_context_contract_flag(
        context,
        subsystem="SimulationEvaluator",
        flag="capability_eval_requires_generated_simulation_code",
    ) or _runtime_environment_feedback_contract_flag(
        environment_feedback,
        flag="capability_eval_requires_generated_simulation_code",
    )


def _runtime_generated_simulation_sandbox_passed_observed(
    blackboard: BlackboardState,
    *,
    question_id: str = "",
    theory_packet_id: str = "",
    algorithm_sandbox_manifest_id: str = "",
    algorithm_sandbox_manifest_hash: str = "",
) -> bool:
    for artifact in blackboard.artifacts.values():
        if not isinstance(artifact, Mapping):
            continue
        if artifact.get("artifact_kind") != "RuntimeSimulationManifest":
            continue
        if artifact.get("confirmatory_empirical_evidence_eligible") is False:
            continue
        if question_id:
            artifact_question = artifact.get("question", {})
            artifact_question_id = (
                str(artifact_question.get("id", "") or "")
                if isinstance(artifact_question, Mapping)
                else ""
            )
            if artifact_question_id and artifact_question_id != question_id:
                continue
        artifact_packet_id = str(artifact.get("theory_packet_id", "") or "")
        if theory_packet_id and artifact_packet_id != theory_packet_id:
            continue
        if algorithm_sandbox_manifest_id or algorithm_sandbox_manifest_hash:
            receipt = artifact.get("upstream_algorithm_handoff_receipt", {})
            if not (
                isinstance(receipt, Mapping)
                and (
                    not algorithm_sandbox_manifest_id
                    or str(
                        receipt.get("algorithm_sandbox_manifest_id", "") or ""
                    )
                    == algorithm_sandbox_manifest_id
                )
                and (
                    not algorithm_sandbox_manifest_hash
                    or str(
                        receipt.get("algorithm_sandbox_manifest_hash", "") or ""
                    )
                    == algorithm_sandbox_manifest_hash
                )
                and receipt.get("mechanical_estimator_invocation_verified")
                is True
            ):
                continue
        if int(artifact.get("n_generated_simulation_sandbox_passed", 0) or 0) > 0:
            return True
        for row in artifact.get("generated_simulation_sandbox_prototypes", []) or []:
            if not isinstance(row, Mapping):
                continue
            if (
                str(row.get("executor", "") or "")
                == "generated_simulation_sandbox"
                and row.get("prototype_status") == "EXECUTED"
                and row.get("smoke_passed") is True
            ):
                return True
    return False


def _implementation_gap_estimator_ids(
    implementation_gaps: Iterable[Mapping[str, Any]],
) -> set[str]:
    ids: set[str] = set()
    for row in implementation_gaps:
        if not isinstance(row, Mapping):
            continue
        estimator_id = str(row.get("estimator_id", "") or "").strip()
        if estimator_id:
            ids.add(estimator_id)
    return ids


def _runtime_generated_algorithm_sandbox_passed_manifest_id(
    blackboard: BlackboardState,
    *,
    question_id: str = "",
    theory_packet_id: str = "",
    required_estimator_ids: Iterable[str] = (),
) -> str:
    required_ids = {
        str(row).strip()
        for row in required_estimator_ids
        if str(row).strip()
    }
    for artifact in blackboard.artifacts.values():
        if not isinstance(artifact, Mapping):
            continue
        if artifact.get("artifact_kind") != "RuntimeAlgorithmSandboxManifest":
            continue
        if question_id:
            artifact_question = artifact.get("question", {})
            artifact_question_id = (
                str(artifact_question.get("id", "") or "")
                if isinstance(artifact_question, Mapping)
                else ""
            )
            if artifact_question_id and artifact_question_id != question_id:
                continue
        artifact_packet_id = str(artifact.get("theory_packet_id", "") or "")
        if theory_packet_id and artifact_packet_id != theory_packet_id:
            continue
        passed_ids: set[str] = set()
        for row in artifact.get("prototypes", []) or []:
            if not isinstance(row, Mapping):
                continue
            if (
                str(row.get("executor", "") or "") == "generated_python_sandbox"
                and row.get("prototype_status") == "EXECUTED"
                and row.get("smoke_passed") is True
            ):
                estimator_id = str(row.get("estimator_id", "") or "").strip()
                if estimator_id:
                    passed_ids.add(estimator_id)
        if required_ids and not required_ids.issubset(passed_ids):
            continue
        if passed_ids or int(artifact.get("n_passed", 0) or 0) > 0:
            return str(artifact.get("manifest_id", "") or "")
    return ""


def _runtime_generated_simulation_required_before_formalization(
    *,
    context: Mapping[str, Any],
    environment_feedback: Mapping[str, Any] | None,
    blackboard: BlackboardState,
    question: OpenResearchQuestion,
    theory_packet_id: str,
    algorithm_sandbox_manifest_id: str = "",
    algorithm_sandbox_manifest_hash: str = "",
) -> bool:
    if not _runtime_requires_generated_simulation_code(
        context,
        environment_feedback,
    ):
        return False
    return not _runtime_generated_simulation_sandbox_passed_observed(
        blackboard,
        question_id=question.id,
        theory_packet_id=theory_packet_id,
        algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
        algorithm_sandbox_manifest_hash=algorithm_sandbox_manifest_hash,
    )


def _generated_simulation_required_before_formalization_feedback(
    *,
    question: OpenResearchQuestion,
    theory_packet_id: str,
    simulation_manifest_id: str,
    algorithm_sandbox_manifest_id: str,
) -> dict[str, Any]:
    return {
        "feedback_type": "coding_agent_generated_code_capability_feedback",
        "capability_id": "generated_simulation_code_executed_locally",
        "target_component": "simulation",
        "failure_classification": "integrated_coding_agent_capability_gap",
        "target_behavior": (
            "Produce a safe generated simulation_code_drafts entry and let "
            "AgentRuntime execute it locally before formalization."
        ),
        "success_metric": (
            "n_generated_simulation_sandbox_executed>0 and "
            "n_generated_simulation_sandbox_passed>0"
        ),
        "runtime_requested_evidence_contract": {
            "capability_eval_requires_generated_simulation_code": True
        },
        "input_summary": {
            "question_id": question.id,
            "theory_packet_id": theory_packet_id,
            "previous_simulation_manifest_id": simulation_manifest_id,
            "algorithm_sandbox_manifest_id": algorithm_sandbox_manifest_id,
            "blocker": (
                "AlgorithmEngineer completed, but the capability-eval contract "
                "still has no passing generated simulation sandbox evidence for "
                "this theory packet."
            ),
        },
        "proof_evidence_status": (
            "CODING_AGENT_CAPABILITY_FEEDBACK_NOT_PROOF_EVIDENCE"
        ),
        "boundary": (
            "This feedback is an orchestration contract. It is not simulation "
            "evidence, algorithm evidence, or theorem proof evidence until the "
            "current AgentRuntime records generated simulation sandbox execution."
        ),
    }


def _generated_simulation_required_before_formalization_task(
    *,
    question: OpenResearchQuestion,
    packet_id: str,
    simulation_manifest_id: str,
    algorithm_sandbox_manifest_id: str,
    architect_context: Mapping[str, Any],
    n_runs: int,
    seed: int,
) -> AgentTask:
    capability_feedback = (
        _generated_simulation_required_before_formalization_feedback(
            question=question,
            theory_packet_id=packet_id,
            simulation_manifest_id=simulation_manifest_id,
            algorithm_sandbox_manifest_id=algorithm_sandbox_manifest_id,
        )
    )
    feedback = dict(capability_feedback)
    context = dict(architect_context)
    context = _runtime_context_with_environment_feedback_contract(
        context,
        feedback,
        subsystem="SimulationEvaluator",
    )
    context["previous_simulation_manifest_id"] = simulation_manifest_id
    context["previous_algorithm_sandbox_manifest_id"] = algorithm_sandbox_manifest_id
    context["algorithm_sandbox_manifest_id"] = algorithm_sandbox_manifest_id
    context[
        "confirmatory_simulation_requires_accepted_algorithm_handoff"
    ] = True
    return AgentTask(
        task_id=(
            f"simulation-required:{question.id}:"
            f"{stable_hash([packet_id, simulation_manifest_id, algorithm_sandbox_manifest_id])[:8]}"
        ),
        owner_subsystem="SimulationEvaluator",
        objective=(
            "Run required LLM-generated simulation-code stress-test evidence "
            "before formalization."
        ),
        inputs={
            "question": _question_to_payload(question),
            "theory_packet_id": packet_id,
            "algorithm_sandbox_manifest_id": algorithm_sandbox_manifest_id,
            "architect_context": context,
            "environment_feedback": feedback,
            "n_runs": n_runs,
            "seed": seed,
        },
        allowed_tools=(
            "model_backend",
            "research_simulator",
            "python",
            "filesystem_sandbox",
        ),
        expected_artifacts=_architect_expected_artifacts(
            context,
            "SimulationEvaluator",
            ("simulation_manifest", "implementation_gap_manifest"),
        ),
        acceptance_gate=_architect_acceptance_gate(
            context,
            "SimulationEvaluator",
            "generated simulation draft executes safely before formalization",
        ),
        stop_condition="required generated simulation capability evidence recorded",
    )

def _latest_artifact(blackboard: BlackboardState, prefix: str) -> dict[str, Any]:
    for key in reversed(list(blackboard.artifacts.keys())):
        if key.startswith(prefix) and isinstance(blackboard.artifacts[key], dict):
            return dict(blackboard.artifacts[key])
    return {}


def _artifact_by_id_or_latest(
    blackboard: BlackboardState,
    artifact_id: str,
    prefix: str,
) -> dict[str, Any]:
    if artifact_id:
        artifact = blackboard.artifacts.get(artifact_id, {})
        return dict(artifact) if isinstance(artifact, Mapping) else {}
    return _latest_artifact(blackboard, prefix)


def _algorithm_proposal_for_estimator(
    proposal_packet: Mapping[str, Any] | None,
    estimator_id: str,
) -> dict[str, Any]:
    if not isinstance(proposal_packet, Mapping):
        return {}
    for row in proposal_packet.get("implementation_targets", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("estimator_id", "")) == estimator_id:
            return dict(row)
    return {}


def _algorithm_code_draft_for_estimator(
    proposal_packet: Mapping[str, Any] | None,
    estimator_id: str,
) -> dict[str, Any]:
    if not isinstance(proposal_packet, Mapping):
        return {}
    for row in proposal_packet.get("sandbox_code_drafts", []) or []:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("estimator_id", "")) == estimator_id:
            return dict(row)
    return {}


def _formalization_manifest_source_to_bridge_metadata_blocker(
    formalization_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(formalization_manifest, Mapping):
        return {}
    proof_bank_memory_summary = (
        formalization_manifest.get("proof_bank_runtime_memory_summary", {})
        if isinstance(
            formalization_manifest.get("proof_bank_runtime_memory_summary", {}),
            Mapping,
        )
        else {}
    )
    target_mode = str(
        proof_bank_memory_summary.get("recommended_formalizer_target_mode", "")
        or ""
    ).strip()
    diagnostic_helper_bridge_mode = (
        target_mode == "source_theorem_diagnostic_helper_bridge_or_blocker"
        or bool(
            proof_bank_memory_summary.get(
                "formalizer_diagnostic_helper_integration_required",
                False,
            )
        )
    )
    helper_rows = [
        dict(row)
        for row in proof_bank_memory_summary.get(
            "formalizer_diagnostic_helper_memory",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    helper_candidate_ids = [
        str(row.get("candidate_id", "") or "").strip()
        for row in helper_rows
        if str(row.get("candidate_id", "") or "").strip()
    ]
    gap_rows: list[dict[str, Any]] = []
    for key in ("llm_formalizer_gap_taxonomy", "gap_taxonomy"):
        raw_rows = formalization_manifest.get(key, [])
        if isinstance(raw_rows, list | tuple):
            gap_rows.extend(dict(row) for row in raw_rows if isinstance(row, Mapping))
    blocker_gap_rows: list[dict[str, str]] = []
    for row in gap_rows:
        gap = str(row.get("gap", "") or "").strip()
        kind = str(row.get("kind", "") or "").strip()
        next_owner = str(row.get("next_owner", "") or "").strip()
        text = f"{kind} {gap} {next_owner}".lower()
        if (
            kind == "source_to_bridge_metadata_blocker"
            or (
                "source-binding" in text
                and "source_to_bridge_premise_derivation" in text
            )
            or (
                "source-to-bridge" in text
                and "metadata" in text
                and "semantic anchor" in text
            )
        ):
            blocker_gap_rows.append(
                {
                    "gap": gap,
                    "kind": kind or "source_to_bridge_metadata_blocker",
                    "next_owner": next_owner,
                }
            )
    blocker_status = str(
        formalization_manifest.get(
            "llm_formalizer_diagnostic_helper_bridge_blocker_status",
            "",
        )
        or formalization_manifest.get("diagnostic_helper_bridge_blocker_status", "")
        or ""
    ).strip()
    candidate_rows = [
        dict(row)
        for row in formalization_manifest.get(
            "llm_formalizer_source_to_bridge_premise_derivation_candidates",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    work_order_rows = [
        dict(row)
        for row in formalization_manifest.get(
            "source_to_bridge_premise_derivation_work_orders",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    diagnostics = [
        dict(row)
        for row in proof_bank_memory_summary.get(
            "source_to_bridge_premise_derivation_diagnostics",
            [],
        )
        or []
        if isinstance(row, Mapping)
    ]
    has_source_to_bridge_candidate_request = bool(candidate_rows or work_order_rows)
    if not has_source_to_bridge_candidate_request:
        for row in diagnostics:
            if (
                str(
                    row.get(
                        "source_to_bridge_premise_derivation_candidate_request_id",
                        "",
                    )
                    or ""
                ).strip()
                or isinstance(
                    row.get("source_to_bridge_premise_derivation_candidate_request"),
                    Mapping,
                )
                or str(
                    row.get(
                        "source_to_bridge_grouped_premise_derivation_candidate_request_id",
                        "",
                    )
                    or ""
                ).strip()
                or isinstance(
                    row.get(
                        "source_to_bridge_grouped_premise_derivation_candidate_request"
                    ),
                    Mapping,
                )
            ):
                has_source_to_bridge_candidate_request = True
                break
    inferred_from_helper_memory = (
        diagnostic_helper_bridge_mode
        and bool(helper_rows)
        and not has_source_to_bridge_candidate_request
    )
    if not (blocker_status or blocker_gap_rows or inferred_from_helper_memory):
        return {}
    target_ids = [
        str(value).strip()
        for value in proof_bank_memory_summary.get("remaining_theorem_goal_ids", [])
        or []
        if str(value).strip()
    ]
    if not target_ids:
        target_ids = [
            str(row.get("id", "") or "").strip()
            for row in formalization_manifest.get("deterministic_theorem_goals", [])
            or []
            if isinstance(row, Mapping) and str(row.get("id", "") or "").strip()
        ]
    return {
        "status": (
            blocker_status
            or "SOURCE_TO_BRIDGE_METADATA_BLOCKER_INFERRED_FROM_DIAGNOSTIC_HELPER_MEMORY"
        ),
        "recommended_formalizer_target_mode": target_mode,
        "target_ids": target_ids,
        "diagnostic_helper_candidate_ids": list(dict.fromkeys(helper_candidate_ids)),
        "blocker_gaps": blocker_gap_rows[:5],
        "source_formalizer_packet_id": str(
            formalization_manifest.get(
                "llm_formalizer_proof_engineer_proposal_id",
                "",
            )
            or ""
        ),
        "formalization_manifest_id": str(
            formalization_manifest.get("manifest_id", "") or ""
        ),
    }


def _source_to_bridge_metadata_blocker_agenda_item(
    *,
    blocker: Mapping[str, Any],
    fallback_target_ids: list[str],
) -> dict[str, Any]:
    target_ids = [
        str(value).strip()
        for value in blocker.get("target_ids", []) or []
        if str(value).strip()
    ] or [value for value in fallback_target_ids if value]
    helper_ids = [
        str(value).strip()
        for value in blocker.get("diagnostic_helper_candidate_ids", []) or []
        if str(value).strip()
    ]
    return {
        "id": "formal_gap:source_to_bridge_metadata_authoring",
        "owner_subsystem": "TheoryDeveloper/SourceBindingMetadata/Formalizer",
        "trigger": "SOURCE_TO_BRIDGE_METADATA_BLOCKER",
        "action": (
            "author or retrieve exact source-to-bridge premise-derivation "
            "candidate request metadata: premise names, exact source theorem "
            "binders, adapter object names requiring source instantiation, "
            "semantic anchor binders, and required anchor references before "
            "asking Formalizer for executable "
            "source_to_bridge_premise_derivation_candidates"
        ),
        "acceptance_gate": (
            "proof_bank_runtime_memory_summary exposes a "
            "source_to_bridge_premise_derivation_candidate_request or "
            "source_to_bridge_grouped_premise_derivation_candidate_request "
            "with source-binding metadata, exact_source_theorem_binders, "
            "premise_semantic_anchor_binders, and "
            "required_semantic_anchor_reference_names"
        ),
        "target_ids": target_ids,
        "diagnostic_helper_candidate_ids": helper_ids,
        "source_to_bridge_metadata_blocker_status": str(
            blocker.get("status", "") or ""
        ),
        "source_to_bridge_metadata_blocker_kind": (
            "source_to_bridge_metadata_blocker"
        ),
        "source_formalizer_packet_id": str(
            blocker.get("source_formalizer_packet_id", "") or ""
        ),
        "formalization_manifest_id": str(
            blocker.get("formalization_manifest_id", "") or ""
        ),
        "recommended_formalizer_target_mode": str(
            blocker.get("recommended_formalizer_target_mode", "") or ""
        ),
        "blocker_gaps": [
            dict(row)
            for row in blocker.get("blocker_gaps", []) or []
            if isinstance(row, Mapping)
        ],
        "runtime_queue_status": "PENDING_SOURCE_TO_BRIDGE_METADATA_AUTHORING",
        "priority": "high",
        "proof_boundary": KERNEL_PROOF_BOUNDARY,
        "boundary": (
            "Source-to-bridge metadata authoring is orchestration context only. "
            "It can unblock a later premise-derivation candidate request, but it "
            "is not theorem proof evidence and does not certify any helper as "
            "source-theorem proof."
        ),
    }


