def _deterministic_theorem_closure_proposal_packet(
    *,
    question: OpenResearchQuestion,
    theorem_goals: list[TheoremGoal],
    proof_bank_runtime_memory_summary: Mapping[str, Any],
) -> dict[str, Any]:
    target_goal_ids = [
        str(row).strip()
        for row in proof_bank_runtime_memory_summary.get("remaining_theorem_goal_ids", []) or []
        if str(row).strip()
    ] or [_theorem_goal_id(row) for row in theorem_goals if _theorem_goal_id(row)]
    verified_bridge_ids = [
        str(row).strip()
        for row in proof_bank_runtime_memory_summary.get(
            "memory_kernel_verified_proof_obligation_ids",
            [],
        )
        or []
        if str(row).strip()
    ]
    target_rows: list[dict[str, Any]] = []
    for goal_id in target_goal_ids:
        safe_goal = _safe_identifier(goal_id or "frontier_theorem")
        target_rows.append(
            {
                "id": f"{safe_goal}_reduction_closure",
                "informal_source": (
                    "Connect the runtime-memory kernel-verified proof-bank bridge "
                    "obligations to the remaining frontier theorem goal."
                ),
                "lean_statement_sketch": "",
                "target_lean_declaration": "",
                "candidate_generation_required": True,
                "candidate_generation_request": {
                    "request_kind": "llm_theorem_reduction_closure_candidate",
                    "target_theorem_goal_ids": [goal_id],
                    "verified_bridge_obligation_ids": verified_bridge_ids,
                    "required_output": (
                        "A complete exact Lean declaration candidate preserving "
                        "the theorem goal and assumptions, followed by unchanged "
                        "local Lean/LSP compiler feedback."
                    ),
                    "forbidden_runtime_substitution": (
                        "Python runtime must not generate a theorem, tactic, "
                        "placeholder proof, grammar rewrite, or proof-bank body."
                    ),
                },
                "semantic_alignment_constraints": [
                    "Do not strengthen assumptions beyond the source theorem.",
                    "Preserve the theorem goal semantics; bridge obligations are subclaims only.",
                    "Do not treat this work order or sketch as proof evidence until local Lean/AXLE checks it.",
                ],
                "expected_status": "FORMAL_GAP",
            }
        )
    packet_id = (
        "formalizer_proposal:"
        + stable_hash(
            {
                "source_agent": "DeterministicTheoremClosureWorkOrderSeed",
                "question_id": question.id,
                "target_goal_ids": target_goal_ids,
                "verified_bridge_ids": verified_bridge_ids,
            }
        )[:24]
    )
    return {
        "schema_version": RUNTIME_SCHEMA_VERSION,
        "artifact_kind": "FormalizerProofEngineerProposalPacket",
        "packet_id": packet_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "source_agent": "DeterministicTheoremClosureWorkOrderSeed",
        "provider": "deterministic",
        "model": "runtime_memory_theorem_closure_work_order_seed",
        "model_tier": "none",
        "question": _question_to_payload(question),
        "proof_evidence_status": "DETERMINISTIC_THEOREM_CLOSURE_PACKET_NOT_PROOF_EVIDENCE",
        "proof_evidence_boundary": FORMALIZER_BOUNDARY,
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
        "formal_targets": target_rows,
        "lemma_dependency_plan": [
            {
                "from": "kernel_verified_proof_bank_bridge_memory",
                "to": ",".join(target_goal_ids),
                "role": "theorem-level reduction work order",
                "risk": "source theorem may still require missing formal primitives or semantic alignment",
            }
        ],
        "retrieval_queries": [
            {
                "query": "theorem-level reduction closure for verified proof-bank bridge obligations",
                "target_library": "LeanRAG",
                "purpose": "find source theorem primitives and reusable Lean reductions",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local_lean", "lean_lsp_mcp", "formal_source_retriever"],
            "tactic_or_certificate_hints": [],
            "kernel_check_plan": [
                "materialize a Lean theorem-level reduction with no sorry",
                "run local Lean or AXLE before claiming proof evidence",
            ],
            "known_blockers": [
                "the full source theorem may still need source-specific semantic primitives or dependencies",
            ],
        },
        "proof_bank_obligation_requests": [],
        "gap_taxonomy": [
            {
                "gap": "theorem-level reduction closure still needs a Lean proof",
                "kind": "proof_search",
                "next_owner": "ProofEngineer/LeanProver",
            }
        ],
        "critic_findings": [
            {
                "critic": "proof_boundary_critic",
                "finding": (
                    "All registered bridge obligations are memory-kernel-verified, "
                    "but the frontier theorem is not proved until the reduction closes."
                ),
                "reroute_if_confirmed": "FormalizationEvaluator",
            }
        ],
        "next_actions": [
            {
                "owner_agent": "ProofEngineer/LeanProver",
                "action": "prove the theorem-level reduction closure or record exact blockers",
                "acceptance_gate": "local Lean/AXLE kernel verifies the intended reduction with no sorry",
            }
        ],
    }


def _formalizer_pseudo_formal_work_order_rows(
    *,
    proposal_packet: Mapping[str, Any],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    proposal_id = str(proposal_packet.get("packet_id", "") or "")
    for packet_index, packet in enumerate(
        proposal_packet.get("pseudo_formal_proof_packets", []) or [],
        start=1,
    ):
        if not isinstance(packet, Mapping):
            continue
        normalized_packet = normalize_pseudo_formal_packet(packet)
        packet_validation_errors = validate_pseudo_formal_packet(normalized_packet)
        if packet_validation_errors:
            validation_feedback = formalizer_validation_feedback_envelope(
                packet_validation_errors,
                validation_label="Pseudo-formal proof packet",
                invalid_packet=normalized_packet,
            )
            source_packet_id = str(
                normalized_packet.get("packet_id", "")
                or f"pseudo_formal_packet:{packet_index}"
            )
            quarantine_row = {
                "schema_version": RUNTIME_SCHEMA_VERSION,
                "artifact_kind": "PseudoFormalizerWorkOrder",
                "row_id": "pseudo_formal_work_order:"
                + stable_hash(
                    [
                        proposal_id,
                        packet_index,
                        source_packet_id,
                        packet_validation_errors,
                    ]
                )[:16],
                "source_packet_id": source_packet_id,
                "source_theorem_id": str(
                    normalized_packet.get("theorem_id", "") or ""
                ),
                "source_artifact_id": str(
                    normalized_packet.get("source_artifact_id", "") or ""
                ),
                "source_block_id": f"pseudo_formal_packet_validation:{packet_index}",
                "source_block_type": "packet_validation_quarantine",
                "source_block_conclusion": (
                    "Pseudo-formal packet failed local validation before block "
                    "routing; repair PF/BV decomposition before downstream work."
                ),
                "block_depth": 1,
                "dependency_scope": PSEUDO_FORMAL_DEFAULT_DEPENDENCY_SCOPE,
                "dependency_ids": [],
                "scope_parent_id": "",
                "inherited_scope": [],
                "source_anchors": [
                    {
                        "kind": "packet_validation",
                        "id": source_packet_id,
                        "excerpt": "; ".join(packet_validation_errors[:3])[:300],
                    }
                ],
                "faithfulness_status": "unchecked",
                "faithfulness_repair_status": "unavailable",
                "block_verification": {
                    "verdict": "not_run",
                    "reason": "pseudo-formal packet failed local validation",
                },
                "bv_calibration": {
                    "strictness_threshold": (
                        PSEUDO_FORMAL_DEFAULT_CALIBRATION_STRICTNESS
                    ),
                    "aggregation_rule": "parallel_pessimistic_aggregation",
                    "pessimistic_acceptance": True,
                    "rollout_count": 0,
                },
                "row_kind": PSEUDO_FORMAL_PACKET_VALIDATION_QUARANTINE_ROW_KIND,
                "target_lane": PSEUDO_FORMAL_TARGET_LANE_FORMAL_GAP,
                "pseudo_formal_method_contract_id": (
                    PSEUDO_FORMAL_VERIFICATION_METHOD_CONTRACT_ID
                ),
                "pseudo_formal_method_name": (
                    "pseudo_formalization_plus_block_verification"
                ),
                "pseudo_formal_pipeline_stage": PSEUDO_FORMAL_BLOCK_ROUTING_METHOD_STAGE,
                "pseudo_formal_upstream_pipeline_stages": [],
                "reason": (
                    "pseudo-formal packet validation failed: "
                    + "; ".join(packet_validation_errors[:3])
                ),
                "validation_errors": packet_validation_errors,
                "formalizer_validation_feedback": validation_feedback,
                "model_owned_repair_required": True,
                "runtime_selected_mathematical_content": False,
                "source_formalizer_proposal_id": proposal_id,
                "source_pseudo_formal_packet_index": packet_index,
                "proof_evidence_status": PSEUDO_FORMALIZATION_NOT_PROOF_EVIDENCE,
                "proof_evidence_boundary": PSEUDO_FORMALIZATION_PROOF_BOUNDARY,
                "kernel_verified": False,
                "source_theorem_kernel_verified": False,
                "runtime_queue_status": _pseudo_formal_runtime_queue_status(
                    {"target_lane": PSEUDO_FORMAL_TARGET_LANE_FORMAL_GAP}
                ),
                "runtime_queue_boundary": (
                    "This queue row quarantines an invalid pseudo-formal proof "
                    "packet. It is validation feedback only, not theorem proof "
                    "evidence; target-prover kernel replay is required before "
                    "any proof promotion."
                ),
            }
            rows.append(quarantine_row)
            continue
        for row in pseudo_formal_block_work_order_rows(normalized_packet):
            runtime_row = {
                "schema_version": RUNTIME_SCHEMA_VERSION,
                "artifact_kind": "PseudoFormalizerWorkOrder",
                **dict(row),
                "learning_task": PSEUDO_FORMAL_BLOCK_ROUTING_LEARNING_TASK,
                "source_pseudo_formal_work_order_id": str(
                    row.get("row_id", "") or ""
                ),
                "work_order_id": str(row.get("row_id", "") or ""),
                "source_formalizer_proposal_id": proposal_id,
                "source_pseudo_formal_packet_index": packet_index,
                "proof_evidence_status": PSEUDO_FORMALIZATION_NOT_PROOF_EVIDENCE,
                "proof_evidence_boundary": PSEUDO_FORMALIZATION_PROOF_BOUNDARY,
                "kernel_verified": False,
                "source_theorem_kernel_verified": False,
                "runtime_queue_status": _pseudo_formal_runtime_queue_status(row),
                "runtime_queue_boundary": (
                    "This queue row was exported from a pseudo-formal proof block. "
                    "It is routing and decomposition feedback only, not theorem "
                    "proof evidence; target-prover kernel replay is required before "
                    "any proof promotion."
                ),
            }
            rows.append(runtime_row)
    return rows


def _pseudo_formal_runtime_queue_status(row: Mapping[str, Any]) -> str:
    target_lane = str(row.get("target_lane", "") or "")
    return PSEUDO_FORMAL_BLOCK_ROUTING_QUEUE_STATUS_BY_TARGET_LANE.get(
        target_lane,
        PSEUDO_FORMAL_BLOCK_ROUTING_QUEUE_STATUS_BY_TARGET_LANE[
            PSEUDO_FORMAL_TARGET_LANE_FORMAL_GAP
        ],
    )


def _pseudo_formal_work_order_row_kind(row: Mapping[str, Any]) -> str:
    return str(
        row.get("row_kind", "")
        or row.get("pseudo_formal_row_kind", "")
        or ""
    ).strip()


def _pseudo_formal_work_order_is_routable(row: Mapping[str, Any]) -> bool:
    row_kind = _pseudo_formal_work_order_row_kind(row)
    return row_kind not in PSEUDO_FORMAL_NON_ROUTABLE_WORK_ORDER_ROW_KINDS


