def _runtime_learning_row_with_surface_targets(row: Mapping[str, Any]) -> dict[str, Any]:
    normalized = _runtime_learning_row_with_source_to_bridge_declaration_contract(row)
    learning_task = str(normalized.get("learning_task", "") or "")
    normalized.setdefault("schema_version", RUNTIME_SCHEMA_VERSION)
    normalized.setdefault("artifact_kind", "RuntimeLearningRow")
    target_theorem_name = str(normalized.get("target_theorem_name", "") or "")
    input_summary = normalized.get("input_summary", {})
    if not target_theorem_name and isinstance(input_summary, Mapping):
        target_theorem_name = str(input_summary.get("target_theorem_name", "") or "")
    target_ids = list(
        _runtime_row_string_values(normalized, "target_ids", "target_id")
    )
    if not target_ids and target_theorem_name:
        target_ids = [target_theorem_name]
    target_theorem_goal_ids = list(
        _runtime_row_string_values(normalized, "target_theorem_goal_ids")
    )
    local_formalizer_candidate_scope_only = (
        learning_task == "formalizer_lean_candidate_kernel_feedback"
        and not target_theorem_goal_ids
    )
    if (
        not target_theorem_name
        and len(target_ids) == 1
        and not local_formalizer_candidate_scope_only
    ):
        target_theorem_name = target_ids[0]
    if target_theorem_name and not str(
        normalized.get("target_theorem_name", "") or ""
    ).strip():
        normalized["target_theorem_name"] = target_theorem_name
    if target_ids and not normalized.get("target_ids"):
        normalized["target_ids"] = target_ids
    row_boundary = str(
        normalized.get("proof_boundary", "")
        or normalized.get("proof_evidence_boundary", "")
        or normalized.get("boundary", "")
        or normalized.get("evidence_boundary", "")
        or normalized.get("runtime_evidence_boundary", "")
        or ""
    ).strip()
    input_summary_boundary = ""
    if isinstance(input_summary, Mapping):
        input_summary_boundary = str(
            input_summary.get("proof_boundary", "")
            or input_summary.get("proof_evidence_boundary", "")
            or input_summary.get("boundary", "")
            or ""
        ).strip()
    default_boundary = (
        row_boundary
        or input_summary_boundary
        or "Runtime learning rows are repair and routing memory for later "
        "LLM/coding/prover work. They are not proof, simulation, generated-code, "
        "or verifier evidence unless separately recorded in the evidence ledger "
        "with a dedicated verifier gate."
    )
    if not str(normalized.get("proof_evidence_status", "") or "").strip():
        normalized["proof_evidence_status"] = (
            "RUNTIME_NEXT_ACTION_LEARNING_NOT_PROOF_EVIDENCE"
            if learning_task
            in {"next_action_routing", "generated_next_action_routing"}
            else "RETRIEVAL_CONTEXT_LEARNING_NOT_PROOF_EVIDENCE"
            if learning_task == "retrieval_to_theory_context"
            else "CRITIC_FEEDBACK_LEARNING_NOT_PROOF_EVIDENCE"
            if learning_task == "simulation_algorithm_formalization_feedback"
            else "RUNTIME_LEARNING_ROW_NOT_PROOF_EVIDENCE"
        )
    if not str(normalized.get("proof_evidence_boundary", "") or "").strip():
        normalized["proof_evidence_boundary"] = default_boundary
    if not any(
        str(normalized.get(key, "") or "").strip()
        for key in (
            "boundary",
            "memory_boundary",
            "routing_boundary",
            "evidence_boundary",
            "feedback_boundary",
        )
    ):
        normalized["boundary"] = default_boundary
    return normalized


def _normalize_runtime_learning_rows(rows: Sequence[Any]) -> list[Any]:
    return [
        _runtime_learning_row_with_surface_targets(row)
        if isinstance(row, Mapping)
        else row
        for row in rows
    ]


def _runtime_recommended_commands(row: Mapping[str, Any]) -> list[str]:
    raw_commands = row.get("recommended_commands", [])
    if not raw_commands and str(row.get("recommended_command", "") or "").strip():
        raw_commands = [str(row.get("recommended_command", "") or "")]
    if isinstance(raw_commands, str):
        raw_iterable: Any = [raw_commands]
    else:
        raw_iterable = raw_commands or []
    return [str(command) for command in raw_iterable if str(command).strip()]


