def _runtime_learning_rows(results: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for result in results:
        artifacts = result.get("blackboard", {}).get("artifacts", {})
        if not isinstance(artifacts, Mapping):
            continue
        for artifact in artifacts.values():
            if not isinstance(artifact, Mapping):
                continue
            artifact_kind = str(artifact.get("artifact_kind", "") or "")
            if artifact_kind not in {
                "RuntimeCriticEvaluatorManifest",
                "RuntimeFormalizationManifest",
                "RuntimeFormalizerValidationFailure",
                "RuntimeFormalizerCapabilityContractFailure",
                "RuntimeFormalizerLeanCandidateMaterialization",
                "RuntimeFormalizerLeanCandidateProofStateFeedbackManifest",
                "RuntimeFormalizerProofStateRoutingManifest",
                "RuntimeFormalizationGapPlannerLiveRoutePlannerManifest",
                "RuntimeAlgorithmSandboxManifest",
                "RuntimeSimulationManifest",
            }:
                continue
            if artifact_kind == "RuntimeFormalizationGapPlannerLiveRoutePlannerManifest":
                rows.extend(
                    _runtime_learning_row_with_surface_targets(item)
                    for item in _formalization_gap_planner_live_route_planner_contract_feedback_learning_rows(
                        artifact
                    )
                )
                rows.extend(
                    _runtime_learning_row_with_surface_targets(item)
                    for item in _formalization_gap_planner_target_prover_replay_learning_rows(
                        artifact
                    )
                )
                continue
            if artifact_kind == "RuntimeAlgorithmSandboxManifest":
                rows.extend(_algorithm_sandbox_feedback_learning_rows(artifact))
                continue
            if artifact_kind == "RuntimeSimulationManifest":
                rows.extend(_generated_simulation_feedback_learning_rows(artifact))
                continue
            if artifact_kind == "RuntimeFormalizerLeanCandidateMaterialization":
                artifact = _normalize_formalizer_lean_candidate_materialization_artifact(
                    artifact
                )
                rows.extend(
                    _runtime_learning_row_with_surface_targets(item)
                    for item in _formalizer_lean_candidate_materialization_learning_rows(
                        artifact
                    )
                )
                continue
            if (
                artifact_kind
                == "RuntimeFormalizerLeanCandidateProofStateFeedbackManifest"
            ):
                extracted_rows = (
                    _formalizer_lean_candidate_proof_state_feedback_learning_rows(
                        artifact
                    )
                )
                if extracted_rows:
                    rows.extend(
                        _runtime_learning_row_with_surface_targets(item)
                        for item in extracted_rows
                    )
                    continue
            for item in artifact.get("learning_rows", []) or []:
                if isinstance(item, Mapping):
                    rows.append(_runtime_learning_row_with_surface_targets(item))
    return rows


def _formalizer_lean_candidate_proof_state_feedback_learning_rows(
    artifact: Mapping[str, Any],
) -> list[dict[str, Any]]:
    rows = [
        row for row in artifact.get("rows", []) or [] if isinstance(row, Mapping)
    ]
    if not rows:
        return []
    question = (
        artifact.get("question", {})
        if isinstance(artifact.get("question", {}), Mapping)
        else {}
    )
    first_row = rows[0]
    lean_lsp_mcp_live_called = (
        _formalizer_proof_state_feedback_has_live_lean_lsp_mcp_call(artifact)
    )
    requested_tools: list[str] = []
    executed_tools: list[str] = []
    tool_call_trace: list[dict[str, Any]] = []
    residual_goals: list[str] = []
    diagnostics: list[str] = []
    for row in rows:
        requested_tools.extend(
            str(value)
            for value in row.get("requested_tools", []) or []
            if str(value).strip()
        )
        executed_tools.extend(
            str(value)
            for value in row.get("executed_tools", []) or []
            if str(value).strip()
        )
        tool_call_trace.extend(
            dict(value)
            for value in row.get("tool_call_trace", []) or []
            if isinstance(value, Mapping)
        )
        residual_goals.extend(
            str(value)
            for value in row.get("residual_goals", []) or []
            if str(value).strip()
        )
        diagnostics.extend(
            str(value)
            for value in row.get("diagnostics", []) or []
            if str(value).strip()
        )
    return [
        {
            "schema_version": RUNTIME_SCHEMA_VERSION,
            "artifact_kind": "RuntimeLearningRow",
            "learning_task": "formalizer_lean_candidate_proof_state_feedback",
            "question_id": str(question.get("id", "") or ""),
            "question_title": str(question.get("title", "") or ""),
            "source_manifest_id": str(artifact.get("manifest_id", "") or ""),
            "source_materialization_manifest_id": str(
                artifact.get("source_materialization_manifest_id", "") or ""
            ),
            "next_owner_subsystem": "ProofEngineer",
            "input_summary": {
                "trigger": "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_FEEDBACK",
                "provider_name": str(artifact.get("provider_name", "") or ""),
                "n_feedback_rows": len(rows),
                "residual_goals": residual_goals[:8],
                "diagnostics": diagnostics[:8],
                "requested_tools": sorted(set(requested_tools)),
                "executed_tools": sorted(set(executed_tools)),
                "tool_call_trace": tool_call_trace[:4],
                "attempt_status": str(first_row.get("attempt_status", "") or ""),
                "lean_lsp_mcp_live_called": lean_lsp_mcp_live_called,
            },
            "target_behavior": (
                "ProofEngineer should consume the exact materialized Lean candidate "
                "artifact, proof-state diagnostics, residual goals, and requested "
                "search/tactic tools before proposing a repaired Lean candidate."
            ),
            "acceptance_gate": (
                "A subsequent formalize-lean-repair task produces a non-vacuous "
                "candidate that reruns through local Lean/AXLE; this feedback row "
                "alone is not proof evidence."
            ),
            "proof_evidence_status": (
                "FORMALIZER_LEAN_CANDIDATE_PROOF_STATE_LEARNING_NOT_PROOF_EVIDENCE"
            ),
            "proof_evidence_boundary": PROOF_STATE_FEEDBACK_BOUNDARY,
        }
    ]


def _algorithm_sandbox_feedback_learning_rows(
    artifact: Mapping[str, Any],
) -> list[dict[str, Any]]:
    prototypes = [
        row for row in artifact.get("prototypes", []) or [] if isinstance(row, Mapping)
    ]
    failure_statuses = {
        "FAILED",
        "FAILED_METRIC_GATE",
        "MODEL_CODE_REQUIRED_BUT_MISSING",
        "REJECTED_UNSAFE_GENERATED_CODE",
        "UNSUPPORTED_SANDBOX_TEMPLATE",
    }
    regeneration_required = any(
        str(row.get("prototype_status", "") or "") in failure_statuses
        or row.get("smoke_passed") is False
        or bool(row.get("metric_gate_errors", []) or [])
        or bool(row.get("safety_errors", []) or [])
        for row in prototypes
        if str(row.get("executor", "") or "") == "generated_python_sandbox"
        or str(row.get("prototype_status", "") or "") in failure_statuses
    )
    if not regeneration_required:
        return []
    failure_classification = (
        "generated_algorithm_sandbox_required_not_executed"
        if int(artifact.get("n_generated_code_executed", 0) or 0) == 0
        else "generated_algorithm_sandbox_metric_gate_failed"
        if int(artifact.get("n_metric_gate_failed", 0) or 0) > 0
        else "generated_algorithm_sandbox_repair_required"
    )
    feedback = _algorithm_sandbox_revision_feedback(
        manifest=artifact,
        boundary=str(artifact.get("boundary", "") or ""),
        failure_classification=failure_classification,
    )
    question = (
        artifact.get("question", {})
        if isinstance(artifact.get("question"), Mapping)
        else {}
    )
    return [
        {
            "schema_version": RUNTIME_SCHEMA_VERSION,
            "artifact_kind": "RuntimeLearningRow",
            "created_at": str(
                artifact.get("created_at", "")
                or datetime.now(timezone.utc).isoformat()
            ),
            "question_id": str(question.get("id", "") or ""),
            "learning_task": "algorithm_sandbox_execution_feedback",
            "source_manifest_id": str(artifact.get("manifest_id", "") or ""),
            "target_behavior": (
                "Regenerate the complete model-authored algorithm candidate from "
                "its prior source and exact local execution observations before "
                "proposing unrelated implementation targets."
            ),
            "acceptance_gate": (
                "Next AlgorithmEngineer packet must either produce safe "
                "run_sandbox code that passes sandbox/metric gates or record a "
                "specific unsupported-code blocker without claiming execution."
            ),
            **feedback,
            "proof_evidence_status": (
                "ALGORITHM_SANDBOX_FEEDBACK_MEMORY_NOT_PROOF_EVIDENCE"
            ),
            "memory_status": "ALGORITHM_SANDBOX_REPAIR_MEMORY",
            "next_owner_agent": "AlgorithmEngineer",
            "next_action": "regenerate complete generated algorithm candidate",
        }
    ]


def _generated_simulation_feedback_learning_rows(
    artifact: Mapping[str, Any],
) -> list[dict[str, Any]]:
    prototypes = [
        row
        for row in artifact.get("generated_simulation_sandbox_prototypes", []) or []
        if isinstance(row, Mapping)
    ]
    failure_statuses = {
        "FAILED",
        "FAILED_METRIC_GATE",
        "GENERATED_SIMULATION_CODE_REQUIRED_BUT_MISSING",
        "REJECTED_UNSAFE_GENERATED_CODE",
    }
    regeneration_required = any(
        str(row.get("prototype_status", "") or "") in failure_statuses
        or row.get("smoke_passed") is False
        or bool(row.get("metric_gate_errors", []) or [])
        or bool(row.get("safety_errors", []) or [])
        for row in prototypes
    )
    if not regeneration_required:
        return []
    failure_classification = (
        "generated_simulation_sandbox_metric_gate_failed"
        if int(
            artifact.get("n_generated_simulation_sandbox_metric_gate_failed", 0)
            or 0
        )
        > 0
        else "generated_simulation_sandbox_no_executable_draft"
    )
    feedback = _generated_simulation_revision_feedback(
        manifest=artifact,
        boundary=str(artifact.get("boundary", "") or ""),
        failure_classification=failure_classification,
    )
    question = (
        artifact.get("question", {})
        if isinstance(artifact.get("question"), Mapping)
        else {}
    )
    return [
        {
            "schema_version": RUNTIME_SCHEMA_VERSION,
            "artifact_kind": "RuntimeLearningRow",
            "created_at": str(
                artifact.get("created_at", "")
                or datetime.now(timezone.utc).isoformat()
            ),
            "question_id": str(question.get("id", "") or ""),
            "learning_task": "generated_simulation_sandbox_execution_feedback",
            "source_manifest_id": str(artifact.get("manifest_id", "") or ""),
            "target_behavior": (
                "Regenerate the complete model-authored simulation candidate "
                "from its prior source and exact local execution observations "
                "before proposing unrelated simulation targets."
            ),
            "acceptance_gate": (
                "Next SimulatorEngineer packet must either produce safe "
                "run_sandbox code that passes sandbox/metric gates or record a "
                "specific unsupported-code blocker without claiming execution."
            ),
            **feedback,
            "proof_evidence_status": (
                "GENERATED_SIMULATION_SANDBOX_FEEDBACK_MEMORY_NOT_PROOF_EVIDENCE"
            ),
            "memory_status": "GENERATED_SIMULATION_SANDBOX_REPAIR_MEMORY",
            "next_owner_agent": "SimulationEngineer",
            "next_action": "regenerate complete generated simulation candidate",
        }
    ]


def _runtime_theorem_reduction_closure_work_order_rows(
    results: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    by_work_order_id: dict[str, int] = {}
    for result in results:
        artifacts = result.get("blackboard", {}).get("artifacts", {})
        if not isinstance(artifacts, Mapping):
            continue
        for artifact in artifacts.values():
            if not (
                isinstance(artifact, Mapping)
                and artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
            ):
                continue
            question = artifact.get("question", {}) if isinstance(artifact.get("question"), Mapping) else {}
            work_order_items = list(
                artifact.get("theorem_reduction_closure_work_orders", []) or []
            )
            if not work_order_items:
                proposal_id = str(
                    artifact.get("llm_formalizer_proof_engineer_proposal_id", "")
                    or ""
                )
                proposal_packet = artifacts.get(proposal_id, {})
                if isinstance(proposal_packet, Mapping):
                    proof_bank_summary = (
                        artifact.get("proof_bank_runtime_memory_summary", {})
                        if isinstance(artifact.get("proof_bank_runtime_memory_summary"), Mapping)
                        else {}
                    )
                    theorem_goals = [
                        row
                        for row in artifact.get("deterministic_theorem_goals", []) or []
                        if isinstance(row, Mapping)
                    ]
                    work_order_items = _formalizer_theorem_reduction_closure_work_orders(
                        proposal_packet=proposal_packet,
                        proof_bank_runtime_memory_summary=proof_bank_summary,
                        theorem_goals=theorem_goals,
                    )
            for item in work_order_items:
                if not isinstance(item, Mapping):
                    continue
                row = dict(item)
                row["source_formalization_manifest_id"] = str(
                    artifact.get("manifest_id", "")
                )
                row["question_id"] = str(question.get("id", "") or "")
                row["question_title"] = str(question.get("title", "") or "")
                row["task_family"] = primary_task_family_from_mapping(question)
                row["runtime_queue_status"] = "PENDING_LEAN_PROOF_ATTEMPT"
                row["runtime_queue_boundary"] = (
                    "This queue row is a proof task exported from live runtime. "
                    "It is not proof evidence until AXLE/local Lean kernel verification "
                    "accepts the theorem-level reduction."
                )
                work_order_id = str(row.get("work_order_id", "") or "").strip()
                source_manifest_id = str(row.get("source_formalization_manifest_id", "") or "")
                if work_order_id in by_work_order_id:
                    existing = rows[by_work_order_id[work_order_id]]
                    source_ids = [
                        str(value)
                        for value in existing.get("source_formalization_manifest_ids", []) or []
                        if str(value).strip()
                    ]
                    if source_manifest_id and source_manifest_id not in source_ids:
                        source_ids.append(source_manifest_id)
                    existing["source_formalization_manifest_ids"] = source_ids
                    existing["n_source_formalization_manifests"] = len(source_ids)
                    continue
                row["source_formalization_manifest_ids"] = (
                    [source_manifest_id] if source_manifest_id else []
                )
                row["n_source_formalization_manifests"] = len(
                    row["source_formalization_manifest_ids"]
                )
                if work_order_id:
                    by_work_order_id[work_order_id] = len(rows)
                rows.append(row)
    return rows


def _runtime_theorem_reduction_closure_agent_runtime_artifacts(
    results: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    work_orders: list[dict[str, Any]] = []
    executions: list[dict[str, Any]] = []
    seen_work_orders: set[str] = set()
    seen_executions: set[str] = set()
    for result in results:
        blackboard = (
            result.get("blackboard", {})
            if isinstance(result.get("blackboard", {}), Mapping)
            else {}
        )
        artifacts = (
            blackboard.get("artifacts", {})
            if isinstance(blackboard.get("artifacts", {}), Mapping)
            else {}
        )
        for artifact in artifacts.values():
            if not isinstance(artifact, Mapping):
                continue
            kind = str(artifact.get("artifact_kind", "") or "")
            if kind == THEOREM_REDUCTION_CLOSURE_RUNTIME_WORK_ORDER_KIND:
                artifact_id = str(
                    artifact.get("work_order_id", "") or ""
                )
                if artifact_id and artifact_id not in seen_work_orders:
                    seen_work_orders.add(artifact_id)
                    work_orders.append(dict(artifact))
            elif kind == THEOREM_REDUCTION_CLOSURE_RUNTIME_EXECUTION_KIND:
                artifact_id = str(artifact.get("manifest_id", "") or "")
                if artifact_id and artifact_id not in seen_executions:
                    seen_executions.add(artifact_id)
                    executions.append(dict(artifact))
    return work_orders, executions


