def _pseudo_formal_next_action_target_ids(
    row: Mapping[str, Any],
) -> list[str]:
    values = [
        str(row.get("source_theorem_id", "") or ""),
        str(row.get("source_block_id", "") or ""),
        str(row.get("semantic_primitive", "") or ""),
        str(row.get("row_id", "") or row.get("work_order_id", "") or ""),
    ]
    return list(dict.fromkeys(value for value in values if value.strip()))


def _pseudo_formal_block_verifier_worker_execution_fields(
    row_kind: str,
) -> dict[str, Any]:
    if row_kind != PSEUDO_FORMAL_BLOCK_VERIFICATION_REQUEST_ROW_KIND:
        return {}
    component_gate_command = (
        "python -m ai_statistician.cli "
        "pseudo-formal-block-verifier-component-gate "
        "--runtime-learning-jsonl <runtime_learning_rows.jsonl> "
        "--provider anthropic "
        "--model-tier haiku "
        "--out runs/pseudo_formal_block_verifier_component_gate"
    )
    prompt_command = (
        "python -m ai_statistician.cli "
        "pseudo-formal-block-verifier-prompt-packets "
        "--runtime-learning-jsonl <runtime_learning_rows.jsonl> "
        "--out runs/pseudo_formal_block_verifier_prompt_packets"
    )
    llm_response_command = (
        "python -m ai_statistician.cli "
        "pseudo-formal-block-verifier-llm-responses "
        "--prompt-packets-manifest "
        "runs/pseudo_formal_block_verifier_prompt_packets/"
        "pseudo_formal_block_verifier_prompt_packets_manifest.json "
        "--provider anthropic "
        "--model-tier haiku "
        "--out runs/pseudo_formal_block_verifier_llm_responses"
    )
    response_validation_command = (
        "python -m ai_statistician.cli "
        "pseudo-formal-block-verifier-response-validation "
        "--prompt-packets-manifest "
        "runs/pseudo_formal_block_verifier_prompt_packets/"
        "pseudo_formal_block_verifier_prompt_packets_manifest.json "
        "--response-jsonl "
        "runs/pseudo_formal_block_verifier_llm_responses/"
        "pseudo_formal_block_verifier_responses.jsonl "
        "--out runs/pseudo_formal_block_verifier_response_validation"
    )
    return {
        "pseudo_formal_block_verifier_worker": {
            "worker_kind": "pseudo_formal_independent_block_verifier",
            "component_gate_command": component_gate_command,
            "prompt_packets_command": prompt_command,
            "llm_response_command": llm_response_command,
            "response_validation_command": response_validation_command,
            "component_gate_manifest": (
                "runs/pseudo_formal_block_verifier_component_gate/"
                "pseudo_formal_block_verifier_component_gate_manifest.json"
            ),
            "prompt_packets_manifest": (
                "runs/pseudo_formal_block_verifier_prompt_packets/"
                "pseudo_formal_block_verifier_prompt_packets_manifest.json"
            ),
            "prompt_packets_jsonl": (
                "runs/pseudo_formal_block_verifier_prompt_packets/"
                "pseudo_formal_block_verifier_prompt_packets.jsonl"
            ),
            "llm_response_manifest": (
                "runs/pseudo_formal_block_verifier_llm_responses/"
                "pseudo_formal_block_verifier_llm_response_manifest.json"
            ),
            "responses_jsonl": (
                "runs/pseudo_formal_block_verifier_llm_responses/"
                "pseudo_formal_block_verifier_responses.jsonl"
            ),
            "response_validation_manifest": (
                "runs/pseudo_formal_block_verifier_response_validation/"
                "pseudo_formal_block_verifier_response_validation_manifest.json"
            ),
            "runtime_learning_rows_jsonl": (
                "runs/pseudo_formal_block_verifier_response_validation/"
                "runtime_learning_rows.jsonl"
            ),
            "proof_evidence_status": PSEUDO_FORMALIZATION_NOT_PROOF_EVIDENCE,
            "proof_evidence_boundary": PSEUDO_FORMALIZATION_PROOF_BOUNDARY,
        },
        "recommended_commands": [
            component_gate_command,
            prompt_command,
            llm_response_command,
            response_validation_command,
        ],
        "recommended_next_action": (
            "Run the PF/BV component gate or its expanded prompt/response/"
            "validation steps, then rerun AgentRuntime with the validated "
            "non-proof runtime learning memory."
        ),
    }


def _pseudo_formal_safe_block_depth(value: Any) -> int:
    try:
        depth = int(value)
    except (TypeError, ValueError):
        return 1
    return max(1, min(PSEUDO_FORMAL_MAX_PROOF_TREE_DEPTH, depth))


def _pseudo_formal_next_action_owner(target_lane: str, *, row_kind: str = "") -> str:
    if row_kind == PSEUDO_FORMAL_PACKET_VALIDATION_QUARANTINE_ROW_KIND:
        return "Formalizer/ProofEngineer"
    if row_kind == PSEUDO_FORMAL_STRUCTURAL_DECOMPOSITION_REQUEST_ROW_KIND:
        return "Formalizer/ProofEngineer"
    if row_kind == PSEUDO_FORMAL_BLOCK_VERIFICATION_REQUEST_ROW_KIND:
        return "BlockVerifier/CalibrationReferee"
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_FORMAL_TARGETS:
        return "Formalizer/ProofEngineer/LeanProver"
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_LEAN_RAG:
        return "FormalSourceRetriever/FormalizationGapPlanner"
    if target_lane in {
        PSEUDO_FORMAL_TARGET_LANE_SOURCE_TO_BRIDGE,
        PSEUDO_FORMAL_TARGET_LANE_EXACT_SEMANTIC_DEFINITION,
    }:
        return "TheoryDeveloper/Formalizer/ProofEngineer"
    return "FormalizationGapPlanner"


def _pseudo_formal_next_action_action(
    row: Mapping[str, Any],
    *,
    source_block_id: str,
    target_lane: str,
) -> str:
    block_label = source_block_id or str(row.get("source_theorem_id", "") or "block")
    conclusion = str(row.get("source_block_conclusion", "") or "").strip()
    target_text = f" `{block_label}`"
    if conclusion:
        target_text += f" ({conclusion[:160]})"
    if (
        _pseudo_formal_work_order_row_kind(row)
        == PSEUDO_FORMAL_PACKET_VALIDATION_QUARANTINE_ROW_KIND
    ):
        return (
            "inspect the rejected pseudo-formal packet and exact validator observations"
            + target_text
            + ", then author a revised packet or typed blocker; runtime does not "
            "select the mathematical decomposition"
        )
    if (
        _pseudo_formal_work_order_row_kind(row)
        == PSEUDO_FORMAL_STRUCTURAL_DECOMPOSITION_REQUEST_ROW_KIND
    ):
        issues = ", ".join(
            str(value)
            for value in list(row.get("structural_quality_issues", []) or [])[:4]
            if str(value).strip()
        )
        return (
            "split or rewrite pseudo-formal block"
            + target_text
            + " into bounded Good-PF blocks with explicit premises, dependency "
            "statements, inherited scope, source anchors, and local proof text"
            + (f"; current structural issues: {issues}" if issues else "")
        )
    if (
        _pseudo_formal_work_order_row_kind(row)
        == PSEUDO_FORMAL_BLOCK_VERIFICATION_REQUEST_ROW_KIND
    ):
        return (
            "run independent PF/BV block verification for pseudo-formal block"
            + target_text
            + " using only explicit premises, inherited scope, declared "
            "dependency statements, conclusion, and local proof text; write the "
            "verdict back as verifier feedback, not proof evidence"
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_FORMAL_TARGETS:
        return (
            "materialize pseudo-formal block"
            + target_text
            + " as a concrete Lean candidate, run local Lean/AXLE, and keep "
            "pseudo-formal verification separate from proof evidence"
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_LEAN_RAG:
        return (
            "ground pseudo-formal block"
            + target_text
            + " against the Lean library/RAG index, recording exact declarations "
            "or a formal-library gap before attempting proof replay"
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_SOURCE_TO_BRIDGE:
        primitive = str(row.get("semantic_primitive", "") or "").strip()
        return (
            "derive or request the source-to-bridge semantic primitive"
            + (f" `{primitive}`" if primitive else "")
            + " required by pseudo-formal block"
            + target_text
            + ", then rerun a bounded Lean/AXLE premise check"
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_EXACT_SEMANTIC_DEFINITION:
        return (
            "author exact source-theorem semantic definitions for pseudo-formal "
            "block"
            + target_text
            + " and typecheck/materialize them before proof-body search resumes"
        )
    return (
        "review pseudo-formal block"
        + target_text
        + " in the FormalizationGapPlanner, split or reroute the residual gap, "
        "and only pass concrete subgoals to Lean/RAG/source-to-bridge lanes"
    )


def _pseudo_formal_next_action_acceptance_gate(
    target_lane: str,
    *,
    row_kind: str = "",
) -> str:
    if row_kind == PSEUDO_FORMAL_PACKET_VALIDATION_QUARANTINE_ROW_KIND:
        return (
            "Formalizer/ProofEngineer emits a replacement pseudo_formal_proof_packets "
            "entry that passes validate_pseudo_formal_packet and, when PF/BV "
            "activation is required, produces at least one lane-routable "
            "pseudo-formal work-order row. This repair row is not proof evidence."
        )
    if row_kind == PSEUDO_FORMAL_STRUCTURAL_DECOMPOSITION_REQUEST_ROW_KIND:
        return (
            "Formalizer/ProofEngineer emits a replacement pseudo-formal packet "
            "whose blocks satisfy the Good-PF bounded-context structural limits, "
            "then reruns faithfulness and independent block verification. This "
            "repair row is not proof evidence and cannot promote a theorem."
        )
    if row_kind == PSEUDO_FORMAL_BLOCK_VERIFICATION_REQUEST_ROW_KIND:
        return (
            "An independent block-verifier/calibrator records a block verdict "
            "with verifier_provenance independent from the Formalizer rewrite "
            "generator. The result is PF/BV diagnostic feedback only and still "
            "requires target-prover kernel replay for any theorem proof claim."
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_FORMAL_TARGETS:
        return (
            "A concrete Lean candidate for the block is generated and checked by "
            "local Lean/AXLE; pseudo-formal block verification remains non-proof "
            "until the target prover kernel verifies the candidate."
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_LEAN_RAG:
        return (
            "Formal library grounding returns exact Lean declarations or a "
            "documented formal-library gap, and no theorem proof claim is made "
            "without later target-prover kernel replay."
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_SOURCE_TO_BRIDGE:
        return (
            "TheoryDeveloper/Formalizer records a source-backed semantic primitive "
            "or premise derivation candidate and AXLE/local Lean verifies that "
            "bounded premise before any source-theorem proof promotion."
        )
    if target_lane == PSEUDO_FORMAL_TARGET_LANE_EXACT_SEMANTIC_DEFINITION:
        return (
            "Exact semantic definitions are source-anchored and Lean typechecked "
            "before proof-body search; pseudo-formal blocks alone never satisfy "
            "the source theorem kernel evidence gate."
        )
    return (
        "FormalizationGapPlanner records a concrete reroute, split target, or "
        "library/semantic blocker, and every downstream proof claim still requires "
        "target-prover kernel replay."
    )


def _runtime_source_to_bridge_premise_derivation_work_order_rows_from_formalizer(
    results: list[dict[str, Any]],
    *,
    runtime_learning_rows: Sequence[Mapping[str, Any]] = (),
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    by_work_order_id: dict[str, int] = {}
    for result in results:
        artifacts = result.get("blackboard", {}).get("artifacts", {})
        if not isinstance(artifacts, Mapping):
            continue
        for artifact in artifacts.values():
            if not (
                isinstance(artifact, Mapping)
                and artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
            ):
                continue
            question = (
                artifact.get("question", {})
                if isinstance(artifact.get("question"), Mapping)
                else {}
            )
            proof_bank_summary = (
                artifact.get("proof_bank_runtime_memory_summary", {})
                if isinstance(
                    artifact.get("proof_bank_runtime_memory_summary", {}),
                    Mapping,
                )
                else {}
            )
            work_order_items = list(
                artifact.get("source_to_bridge_premise_derivation_work_orders", [])
                or []
            )
            if not work_order_items:
                proposal_id = str(
                    artifact.get("llm_formalizer_proof_engineer_proposal_id", "")
                    or ""
                )
                proposal_packet = artifacts.get(proposal_id, {})
                if not isinstance(proposal_packet, Mapping):
                    continue
                theorem_goals = [
                    row
                    for row in artifact.get("deterministic_theorem_goals", []) or []
                    if isinstance(row, Mapping)
                ]
                work_order_items = (
                    _formalizer_source_to_bridge_premise_derivation_work_orders(
                        proposal_packet=proposal_packet,
                        proof_bank_runtime_memory_summary=proof_bank_summary,
                        theorem_goals=theorem_goals,
                    )
                )
            for item in work_order_items:
                if not isinstance(item, Mapping):
                    continue
                row = dict(item)
                row["source_formalization_manifest_id"] = str(
                    artifact.get("manifest_id", "") or ""
                )
                row["question_id"] = str(
                    row.get("question_id", "") or question.get("id", "") or ""
                )
                row["question_title"] = str(
                    row.get("question_title", "")
                    or question.get("title", "")
                    or ""
                )
                target_theorem_name = str(
                    row.get("target_theorem_name", "")
                    or row.get("target_lean_declaration", "")
                    or ""
                ).strip()
                target_lean_declaration = str(
                    row.get("target_lean_declaration", "")
                    or target_theorem_name
                    or ""
                ).strip()
                source_formal_target_id = str(
                    row.get("source_formal_target_id", "") or ""
                ).strip()
                target_ids = _source_theorem_target_ids_from_row(
                    row,
                    fallback_target_theorem_name=target_theorem_name,
                    fallback_source_formal_target_id=source_formal_target_id,
                )
                if target_ids:
                    row["target_ids"] = target_ids
                if not row.get("target_theorem_goal_ids") and target_ids:
                    row["target_theorem_goal_ids"] = list(target_ids)
                if target_theorem_name:
                    row["target_theorem_name"] = target_theorem_name
                if target_lean_declaration:
                    row["target_lean_declaration"] = target_lean_declaration
                premise_name = str(
                    row.get("premise_name", "")
                    or row.get("source_to_bridge_premise_name", "")
                    or ""
                ).strip()
                if not premise_name:
                    premise_names = _runtime_row_string_values(
                        row,
                        "premise_names",
                        "source_to_bridge_premise_names",
                    )
                    premise_name = premise_names[0] if premise_names else ""
                premise_candidate_declaration_name = str(
                    row.get("premise_candidate_declaration_name", "")
                    or row.get("source_to_bridge_premise_candidate_declaration_name", "")
                    or ""
                ).strip()
                for request_key in (
                    "source_to_bridge_premise_derivation_candidate_request",
                    "source_to_bridge_grouped_premise_derivation_candidate_request",
                ):
                    nested = row.get(request_key, {})
                    if not isinstance(nested, Mapping) or not nested:
                        continue
                    nested_request = dict(nested)
                    if target_ids:
                        nested_request.setdefault("target_ids", target_ids)
                    if row.get("target_theorem_goal_ids"):
                        nested_request.setdefault(
                            "target_theorem_goal_ids",
                            list(row.get("target_theorem_goal_ids", []) or []),
                        )
                    if target_theorem_name:
                        _runtime_set_text_if_missing(
                            nested_request,
                            "target_theorem_name",
                            target_theorem_name,
                        )
                    if target_lean_declaration:
                        _runtime_set_text_if_missing(
                            nested_request,
                            "target_lean_declaration",
                            target_lean_declaration,
                        )
                    if (
                        request_key
                        == "source_to_bridge_premise_derivation_candidate_request"
                    ):
                        _runtime_set_text_if_missing(
                            nested_request,
                            "premise_name",
                            premise_name,
                        )
                        if not premise_candidate_declaration_name:
                            premise_candidate_declaration_name = str(
                                nested_request.get(
                                    "premise_candidate_declaration_name",
                                    "",
                                )
                                or nested_request.get(
                                    "source_to_bridge_premise_candidate_declaration_name",
                                    "",
                                )
                                or ""
                            ).strip()
                        if not premise_candidate_declaration_name:
                            premise_candidate_declaration_name = (
                                stb_metadata.default_premise_candidate_declaration_name(
                                    {
                                        "target_lean_declaration": (
                                            target_lean_declaration
                                        ),
                                        "target_theorem_name": target_theorem_name,
                                        "premise_name": (
                                            premise_name
                                            or str(
                                                nested_request.get(
                                                    "premise_name",
                                                    "",
                                                )
                                                or ""
                                            )
                                        ),
                                    }
                                )
                            )
                        if premise_candidate_declaration_name:
                            _runtime_set_text_if_missing(
                                nested_request,
                                "premise_candidate_declaration_name",
                                premise_candidate_declaration_name,
                            )
                            _runtime_set_text_if_missing(
                                nested_request,
                                "source_to_bridge_premise_candidate_declaration_name",
                                premise_candidate_declaration_name,
                            )
                    row[request_key] = nested_request
                if not premise_candidate_declaration_name:
                    premise_candidate_declaration_name = (
                        stb_metadata.default_premise_candidate_declaration_name(
                            {
                                "target_lean_declaration": target_lean_declaration,
                                "target_theorem_name": target_theorem_name,
                                "premise_name": premise_name,
                            }
                        )
                    )
                if premise_candidate_declaration_name:
                    row["premise_candidate_declaration_name"] = (
                        premise_candidate_declaration_name
                    )
                    row["source_to_bridge_premise_candidate_declaration_name"] = (
                        premise_candidate_declaration_name
                    )
                if _source_to_bridge_work_order_redundant_wrong_declaration_retry(
                    row=row,
                    proof_bank_summary=proof_bank_summary,
                    runtime_learning_rows=runtime_learning_rows,
                ):
                    continue
                row["runtime_queue_status"] = (
                    "PENDING_SOURCE_TO_BRIDGE_PREMISE_DERIVATION"
                )
                row["runtime_queue_boundary"] = (
                    "This queue row was exported from a live Formalizer "
                    "source-to-bridge premise derivation candidate. It is not "
                    "proof evidence; the premise bridge must reject vacuous or "
                    "premise-assuming candidates, and local Lean/AXLE must kernel "
                    "verify the candidate before source-theorem retry."
                )
                work_order_id = str(row.get("work_order_id", "") or "").strip()
                source_manifest_id = str(
                    row.get("source_formalization_manifest_id", "") or ""
                )
                if work_order_id in by_work_order_id:
                    existing = rows[by_work_order_id[work_order_id]]
                    source_ids = [
                        str(value)
                        for value in existing.get(
                            "source_formalization_manifest_ids",
                            [],
                        )
                        or []
                        if str(value).strip()
                    ]
                    if source_manifest_id and source_manifest_id not in source_ids:
                        source_ids.append(source_manifest_id)
                    existing["source_formalization_manifest_ids"] = source_ids
                    existing["n_source_formalization_manifests"] = len(source_ids)
                    for key in (
                        "premise_derivation_candidate_lean_source",
                        "source_candidate_artifact_path",
                        "adapter_candidate_artifact_path",
                        "adapter_declaration_name",
                        "premise_target_type",
                        "premise_derivation_gap_kind",
                        "premise_derivation_gap_summary",
                        "premise_semantic_dependency_status",
                        "premise_semantic_dependency_requirements",
                        "premise_candidate_declaration_name",
                        "source_to_bridge_premise_candidate_declaration_name",
                        "source_to_bridge_premise_derivation_candidate_request",
                        "source_to_bridge_grouped_premise_derivation_candidate_request",
                        "target_ids",
                        "target_theorem_goal_ids",
                    ):
                        value = row.get(key)
                        if isinstance(value, bool) or value not in (None, "", [], {}):
                            existing[key] = value
                    continue
                row["source_formalization_manifest_ids"] = (
                    [source_manifest_id] if source_manifest_id else []
                )
                row["n_source_formalization_manifests"] = len(
                    row["source_formalization_manifest_ids"]
                )
                if work_order_id:
                    by_work_order_id[work_order_id] = len(rows)
                rows.append(row)
    return rows


def _source_to_bridge_work_order_redundant_wrong_declaration_retry(
    *,
    row: Mapping[str, Any],
    proof_bank_summary: Mapping[str, Any],
    runtime_learning_rows: Sequence[Mapping[str, Any]] = (),
) -> bool:
    source = str(
        row.get("premise_derivation_candidate_lean_source", "")
        or row.get("candidate_lean_source", "")
        or row.get("lean_statement_sketch", "")
        or ""
    ).strip()
    if not source:
        return False
    expected_declaration = _source_to_bridge_work_order_expected_declaration(row)
    if not expected_declaration:
        return False
    if re.search(rf"\btheorem\s+{re.escape(expected_declaration)}\b", source):
        return False
    return _proof_bank_summary_has_wrong_declaration_feedback_for_work_order(
        row=row,
        proof_bank_summary=proof_bank_summary,
        runtime_learning_rows=runtime_learning_rows,
        expected_declaration=expected_declaration,
    )


def _source_to_bridge_work_order_expected_declaration(
    row: Mapping[str, Any],
) -> str:
    candidate_request = row.get(
        "source_to_bridge_premise_derivation_candidate_request",
        {},
    )
    if not isinstance(candidate_request, Mapping):
        candidate_request = {}
    declaration = str(
        row.get("premise_candidate_declaration_name", "")
        or row.get("source_to_bridge_premise_candidate_declaration_name", "")
        or candidate_request.get("premise_candidate_declaration_name", "")
        or candidate_request.get(
            "source_to_bridge_premise_candidate_declaration_name",
            "",
        )
        or ""
    ).strip()
    if declaration:
        return declaration
    return stb_metadata.default_premise_candidate_declaration_name(
        {
            "target_lean_declaration": str(
                row.get("target_lean_declaration", "")
                or candidate_request.get("target_lean_declaration", "")
                or ""
            ),
            "target_theorem_name": str(
                row.get("target_theorem_name", "")
                or candidate_request.get("target_theorem_name", "")
                or ""
            ),
            "premise_name": str(
                row.get("premise_name", "")
                or candidate_request.get("premise_name", "")
                or ""
            ),
        }
    )


def _proof_bank_summary_has_wrong_declaration_feedback_for_work_order(
    *,
    row: Mapping[str, Any],
    proof_bank_summary: Mapping[str, Any],
    runtime_learning_rows: Sequence[Mapping[str, Any]] = (),
    expected_declaration: str,
) -> bool:
    diagnostics: list[Mapping[str, Any]] = []
    summary_diagnostics = proof_bank_summary.get(
        "source_to_bridge_premise_derivation_diagnostics",
        [],
    )
    if isinstance(summary_diagnostics, list | tuple):
        diagnostics.extend(
            diagnostic
            for diagnostic in summary_diagnostics
            if isinstance(diagnostic, Mapping)
        )
    for learning_row in runtime_learning_rows:
        if not isinstance(learning_row, Mapping):
            continue
        input_summary = learning_row.get("input_summary", {})
        if not isinstance(input_summary, Mapping):
            input_summary = {}
        failure = str(
            input_summary.get("failure_classification", "")
            or learning_row.get("failure_classification", "")
            or ""
        )
        if failure != "premise_derivation_candidate_wrong_declaration":
            continue
        merged = {**dict(input_summary), **dict(learning_row)}
        nested_input_request = input_summary.get(
            "source_to_bridge_premise_derivation_candidate_request",
            {},
        )
        if (
            "source_to_bridge_premise_derivation_candidate_request" not in merged
            and isinstance(nested_input_request, Mapping)
        ):
            merged["source_to_bridge_premise_derivation_candidate_request"] = (
                nested_input_request
            )
        diagnostics.append(merged)
    if not diagnostics:
        return False
    work_order_id = str(row.get("work_order_id", "") or "").strip()
    premise_name = str(row.get("premise_name", "") or "").strip()
    candidate_request_id = str(
        row.get("source_to_bridge_premise_derivation_candidate_request_id", "")
        or row.get("candidate_request_id", "")
        or ""
    ).strip()
    for diagnostic in diagnostics:
        if not isinstance(diagnostic, Mapping):
            continue
        failure = str(diagnostic.get("failure_classification", "") or "")
        if failure != "premise_derivation_candidate_wrong_declaration":
            continue
        diagnostic_request = diagnostic.get(
            "source_to_bridge_premise_derivation_candidate_request",
            {},
        )
        if not isinstance(diagnostic_request, Mapping):
            diagnostic_request = {}
        diagnostic_work_order_id = str(
            diagnostic.get("work_order_id", "")
            or diagnostic.get("source_premise_derivation_work_order_id", "")
            or ""
        ).strip()
        diagnostic_premise_name = str(
            diagnostic.get("premise_name", "")
            or diagnostic_request.get("premise_name", "")
            or ""
        ).strip()
        diagnostic_request_id = str(
            diagnostic.get(
                "source_to_bridge_premise_derivation_candidate_request_id",
                "",
            )
            or diagnostic.get("candidate_request_id", "")
            or diagnostic_request.get("candidate_request_id", "")
            or ""
        ).strip()
        diagnostic_declaration = str(
            diagnostic.get("premise_candidate_declaration_name", "")
            or diagnostic.get("source_to_bridge_premise_candidate_declaration_name", "")
            or diagnostic_request.get("premise_candidate_declaration_name", "")
            or diagnostic_request.get(
                "source_to_bridge_premise_candidate_declaration_name",
                "",
            )
            or ""
        ).strip()
        if diagnostic_declaration and diagnostic_declaration != expected_declaration:
            continue
        if diagnostic_work_order_id and diagnostic_work_order_id == work_order_id:
            return True
        if (
            candidate_request_id
            and diagnostic_request_id
            and diagnostic_request_id == candidate_request_id
            and diagnostic_premise_name == premise_name
        ):
            return True
        if premise_name and diagnostic_premise_name == premise_name:
            return True
    return False


def _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_formalizer_repair_targets(
    results: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    by_work_order_id: dict[str, int] = {}
    by_semantic_key: dict[tuple[str, str], tuple[int, int, int]] = {}
    row_order = 0
    for result in results:
        artifacts = result.get("blackboard", {}).get("artifacts", {})
        if not isinstance(artifacts, Mapping):
            continue
        for artifact in artifacts.values():
            if not (
                isinstance(artifact, Mapping)
                and artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
            ):
                continue
            question = artifact.get("question", {}) if isinstance(artifact.get("question"), Mapping) else {}
            proposal_id = str(
                artifact.get("llm_formalizer_proof_engineer_proposal_id", "") or ""
            )
            proposal_packet = artifacts.get(proposal_id, {})
            if not isinstance(proposal_packet, Mapping):
                continue
            proof_bank_summary = (
                artifact.get("proof_bank_runtime_memory_summary", {})
                if isinstance(artifact.get("proof_bank_runtime_memory_summary"), Mapping)
                else {}
            )
            theorem_goals = [
                row
                for row in artifact.get("deterministic_theorem_goals", []) or []
                if isinstance(row, Mapping)
            ]
            work_order_items = _formalizer_source_theorem_exact_semantic_definition_work_orders(
                proposal_packet=proposal_packet,
                proof_bank_runtime_memory_summary=proof_bank_summary,
                theorem_goals=theorem_goals,
            )
            for item in work_order_items:
                if not isinstance(item, Mapping):
                    continue
                row = dict(item)
                row["source_formalization_manifest_id"] = str(
                    artifact.get("manifest_id", "")
                )
                row["question_id"] = str(row.get("question_id", "") or question.get("id", "") or "")
                row["question_title"] = str(row.get("question_title", "") or question.get("title", "") or "")
                row["runtime_queue_status"] = (
                    "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_REPAIR"
                )
                row["runtime_queue_boundary"] = (
                    "This queue row is an exact semantic-definition repair task "
                    "exported from live Formalizer memory. It is not proof evidence "
                    "until AXLE/local Lean verifies the reviewed definition/import."
                )
                work_order_id = str(row.get("work_order_id", "") or "").strip()
                source_manifest_id = str(row.get("source_formalization_manifest_id", "") or "")
                semantic_key = (
                    str(row.get("target_theorem_name", "") or "").strip(),
                    str(row.get("placeholder_symbol", "") or "").strip(),
                )
                row_order += 1
                row_priority = (
                    _source_theorem_exact_semantic_definition_candidate_review_priority(
                        row
                    )
                )
                if semantic_key[0] and semantic_key[1] and semantic_key in by_semantic_key:
                    existing_index, existing_priority, existing_order = by_semantic_key[
                        semantic_key
                    ]
                    existing = rows[existing_index]
                    source_ids = [
                        str(value)
                        for value in existing.get(
                            "source_formalization_manifest_ids", []
                        )
                        or []
                        if str(value).strip()
                    ]
                    if source_manifest_id and source_manifest_id not in source_ids:
                        source_ids.append(source_manifest_id)
                    if (row_priority, row_order) >= (
                        existing_priority,
                        existing_order,
                    ):
                        _merge_exact_semantic_definition_work_order_candidate_metadata(
                            row,
                            existing,
                        )
                        row["source_formalization_manifest_ids"] = source_ids
                        row["n_source_formalization_manifests"] = len(source_ids)
                        rows[existing_index] = row
                        by_semantic_key[semantic_key] = (
                            existing_index,
                            row_priority,
                            row_order,
                        )
                        if work_order_id:
                            by_work_order_id[work_order_id] = existing_index
                    else:
                        _merge_exact_semantic_definition_work_order_candidate_metadata(
                            existing,
                            row,
                        )
                        existing["source_formalization_manifest_ids"] = source_ids
                        existing["n_source_formalization_manifests"] = len(source_ids)
                    continue
                if work_order_id in by_work_order_id:
                    existing = rows[by_work_order_id[work_order_id]]
                    source_ids = [
                        str(value)
                        for value in existing.get("source_formalization_manifest_ids", []) or []
                        if str(value).strip()
                    ]
                    if source_manifest_id and source_manifest_id not in source_ids:
                        source_ids.append(source_manifest_id)
                    existing["source_formalization_manifest_ids"] = source_ids
                    existing["n_source_formalization_manifests"] = len(source_ids)
                    continue
                row["source_formalization_manifest_ids"] = (
                    [source_manifest_id] if source_manifest_id else []
                )
                row["n_source_formalization_manifests"] = len(
                    row["source_formalization_manifest_ids"]
                )
                if work_order_id:
                    by_work_order_id[work_order_id] = len(rows)
                if semantic_key[0] and semantic_key[1]:
                    by_semantic_key[semantic_key] = (
                        len(rows),
                        row_priority,
                        row_order,
                    )
                rows.append(row)
    return rows


def _runtime_source_theorem_semantic_primitive_work_order_rows_from_learning_rows(
    learning_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Queue semantic primitive closure when exact candidates only typecheck via placeholders."""

    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in learning_rows:
        if not isinstance(row, Mapping):
            continue
        input_summary = row.get("input_summary", {})
        if not isinstance(input_summary, Mapping):
            input_summary = {}
        exact_semantic_context = _runtime_exact_semantic_definition_context(row)
        trigger = _runtime_learning_row_trigger(row, input_summary)
        learning_task = _runtime_learning_row_task(row, input_summary)
        if not learning_task and str(row.get("id", "") or "").startswith(
            "proof_feedback:"
        ):
            continue
        if learning_task in {
            "source_to_bridge_premise_semantic_repair_feedback",
            "generated_next_action_routing",
        }:
            continue
        is_source_to_bridge_premise_feedback = (
            learning_task == "source_to_bridge_premise_derivation_feedback"
            or learning_task == "source_theorem_truth_table_feedback"
            or trigger == "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_FEEDBACK"
            or trigger == "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP"
            or trigger == "RUNTIME_EVIDENCE_TRUTH_TABLE"
        )
        if is_source_to_bridge_premise_feedback:
            source_theorem_kernel_verified = bool(
                _bool_like(row.get("source_theorem_kernel_verified", False))
                or _bool_like(
                    input_summary.get("source_theorem_kernel_verified", False)
                )
            )
            premise_verified = _runtime_source_to_bridge_premise_derivation_kernel_verified(
                row
            )
            if source_theorem_kernel_verified or premise_verified:
                continue
            premise_name = str(
                row.get("premise_name", "")
                or input_summary.get("premise_name", "")
                or ""
            ).strip()
            premise_target_type = str(
                row.get("premise_target_type", "")
                or input_summary.get("premise_target_type", "")
                or ""
            ).strip()
            if not premise_name and not premise_target_type:
                continue
            target_theorem_name = str(
                row.get("target_theorem_name", "")
                or input_summary.get("target_theorem_name", "")
                or ""
            ).strip()
            source_target_provenance = _source_theorem_target_provenance_from_row(
                row
            )
            input_summary_provenance = _source_theorem_target_provenance_from_row(
                input_summary
            )
            for key, value in input_summary_provenance.items():
                if key not in source_target_provenance:
                    source_target_provenance[key] = value
            question_id = str(
                row.get("question_id", "")
                or input_summary.get("question_id", "")
                or source_target_provenance.get("question_id", "")
                or source_target_provenance.get("source_theorem_question_id", "")
                or ""
            )
            question_title = str(
                row.get("question_title", "")
                or input_summary.get("question_title", "")
                or ""
            )
            source_learning_row_id = str(
                row.get("runtime_learning_row_id", "")
                or row.get("learning_row_id", "")
                or row.get("premise_derivation_check_id", "")
                or ""
            ).strip()
            source_work_order_id = str(
                row.get("work_order_id", "")
                or input_summary.get("work_order_id", "")
                or ""
            )
            candidate_request_raw = (
                row.get("source_to_bridge_premise_derivation_candidate_request", {})
                or input_summary.get(
                    "source_to_bridge_premise_derivation_candidate_request",
                    {},
                )
                or {}
            )
            candidate_request = (
                dict(candidate_request_raw)
                if isinstance(candidate_request_raw, Mapping)
                else {}
            )
            raw_target_goal_ids = list(
                _str_tuple(
                    row.get("target_theorem_goal_ids", [])
                    or input_summary.get("target_theorem_goal_ids", [])
                    or candidate_request.get("target_theorem_goal_ids", [])
                    or []
                )
            )
            explicit_target_ids = list(
                dict.fromkeys(
                    [
                        *_source_theorem_explicit_target_ids_from_row(row),
                        *_source_theorem_explicit_target_ids_from_row(input_summary),
                        *_source_theorem_explicit_target_ids_from_row(
                            candidate_request
                        ),
                    ]
                )
            )
            target_ids = list(explicit_target_ids)
            if not target_ids:
                target_ids = (
                    list(raw_target_goal_ids)
                    if raw_target_goal_ids
                    else ([target_theorem_name] if target_theorem_name else [])
                )
            target_goal_ids = (
                list(target_ids) if explicit_target_ids else list(raw_target_goal_ids)
            )
            if not target_goal_ids:
                target_goal_ids = list(target_ids)
            if target_ids:
                source_target_provenance.setdefault("target_ids", target_ids)
